window.TXB=window.TXB||{};TXB["alab/Eze"]={"1:1":"وحدث في اليوم الخامس من الشهر الرابع العبري، في السنة الثلاثين، فيما كنت بين المسبيين بجوار نهر خابور، أن انفتحت السماوات فشاهدت رؤى من عند الله.","1:2":"في اليوم الخامس من الشهر، في السنة الخامسة لسبي الملك يوياكين،","1:3":"أوحى الرب إلى حزقيال الكاهن ابن بوزي عند جوار نهر خابور، في ديار الكلدانيين، إذ كانت علي يد الرب،","1:4":"فأبصرت ريحا عاصفة تهب من الشمال مصحوبة بسحابة هائلة، ونار متواصلة متوهجة بهالة محيطة من الضياء؛ ومن وسطها يتألق مثل النحاس اللامع البارق من وسط النار.","1:5":"ومن داخلها بدا شبه أربعة كائنات حية تماثل في صورها شبه إنسان،","1:6":"وكان لكل واحد منها أربعة أوجه وأربعة أجنحة.","1:7":"وكانت سيقانها مستقيمة، وأقدامها مشابهة لأقدام العجل، وهي تبرق كبريق النحاس المصقول.","1:8":"وتحت أجنحتها القائمة على جوانبها الأربعة، أيدي بشر، وكان لكل كائن من هذه الكائنات الأربعة أجنحة وأوجه.","1:9":"وكانت أجنحتها تتلامس، وأوجهها لا تدور عند سيرها، بل يسير كل منها ووجهه متجه إلى الأمام.","1:10":"أما أشكال أوجهها، فكان لكل واحد منها وجه إنسان، يحاذيه إلى اليمين وجه أسد، وإلى الشمال وجه ثور، ثم إلى جواره وجه نسر.","1:11":"كانت هذه أشكال أوجهها. وكان لكل منها أربعة أجنحة تمتد من وسط الظهر: اثنان يتصل طرف كل منهما بطرف جناح الكائن الآخر، واثنان يستران أجسامهما.","1:12":"وكان كل واحد منها يتجه إلى الأمام من غير أن يدور، فحيثما يتوجه الروح يتوجهون هم أيضا.","1:13":"أما منظر الكائنات الحية هذه فكان كجمرات نار متقدة، أو مشاعل تجوز جيئة وذهابا بين الكائنات الحية. وكانت النار مضيئة يلمع منها وميض برق.","1:14":"والكائنات الحية تتراكض ذهابا وإيابا في سرعة لمح البرق.","1:15":"وفيما كنت أتأمل في الكائنات الحية، إذا بي أشاهد أربع عجلات، عجلة لكل واحد من الكائنات الحية.","1:16":"أما شكل العجلات وصنعتها فكان كمثل الزبرجد، وهي متشابهة الصورة. وكان منظرها وصنعتها كأنها عجلة داخل عجلة.","1:17":"وإذا سارت فإنها تسير في أي من الاتجاهات الأربعة إلى الأمام، من غير أن تتحول عن اتجاهها.","1:18":"أما أطرها فعالية وهائلة، وجميعها ملأى بالعيون.","1:19":"وكلما تتحرك الكائنات الحية، تتحرك معها العجلات، وكلما ترتفع عن الأرض ترتفع معها العجلات أيضا.","1:20":"وحيثما يتوجه الروح تتوجه أيضا، وترتفع معها عجلاتها، لأن روح الكائنات الحية سار أيضا في العجلات.","1:21":"فإن سارت هذه تسير تلك، وإن توقفت تتوقف، لأن روح الكائنات الحية سار في العجلات أيضا.","1:22":"وانبسط فوق رؤوس الكائنات الحية جلد يشبه البلور المتلأليء الهائل.","1:23":"وامتدت أجنحتها تحت الجلد باستقامة، الواحد نحو الآخر. لكل واحد منها جناحان يستران جسمه من الجانبين.","1:24":"وعندما سارت سمعت رفرفة أجنحتها كهدير مياه غزيرة، كصوت القدير، كصوت جلبة جيش، وعند توقفها كانت ترخي أجنحتها.","1:25":"وصدر صوت من فوق الجلد المنبسط على رؤوسها. وحين تتوقف كانت ترخي أجنجتها.","1:26":"وانتصب فوق الجلد المنبسط على رؤوسها شبه عرش، منظره كحجر اللازورد. ويجلس على شبه العرش من فوق من هو كشبه إنسان.","1:27":"ورأيت ما يبدو من حقويه فما فوق وكأنه نحاس لامع يتوهج في داخله وحواليه. أما ما يبدو من حقويه وما تحت، فكأنه نار، وحواليها يشع بالضياء.","1:28":"وكان منظر اللمعان المحيط به كمنظر قوس قزح في يوم مطير؛ هكذا كان منظر شبه مجد الرب. وعندما أبصرت خررت على وجهي وسمعت صوتا يتكلم.","2:1":"ثم قال لي: «ياابن آدم، قف على قدميك فأخاطبك».","2:2":"وحالما تكلم دخل في الروح وأنهضني على قدمي وسمعته يخاطبني:","2:3":"«ياابن آدم، ها أنا باعثك إلى بني إسرائيل، إلى أمة متمردة عصتني، إذ تعدوا هم وآباؤهم علي إلى هذا اليوم.","2:4":"أنا باعثك إلى الأبناء المتصلبين القساة، فتقول لهم: هذا ما يعلنه الرب.","2:5":"فإن سمعوا، أو أبوا لأنهم شعب عاص فإنهم يعلمون على الأقل أن نبيا بينهم.","2:6":"أما أنت، ياابن آدم، فلا ترهبهم ولا تخش كلامهم، وإن كانوا لك قريسا وشوكا. وأنت ساكن بين عقارب، فلا ترهب كلامهم، ولا تفزع من محضرهم لأنهم شعب متمرد.","2:7":"إنما عليك أن تبلغهم كلامي سواء سمعوا أو أبوا، لأنهم شعب متمرد.","2:8":"والآن ياابن آدم، أصغ لما أخاطبك به. لا تكن متمردا مثل ذلك الشعب المتمرد. افتح فمك وكل ما أطعمك».","2:9":"فنظرت وإذا بيد ممتدة إلي، وفيها درج كتاب.","2:10":"وعندما نشره أمامي رأيت الكتابة تملأه من الداخل والخارج وقد دونت فيه مراث ومناحات وويلات.","3:1":"ثم قال لي: «ياابن آدم، كل ما تجده. كل هذا الدرج وامض وخاطب شعب إسرائيل».","3:2":"ففتحت فمي فأطعمني هذا الدرج،","3:3":"وقال لي: «أطعم جوفك واملأه بهذا الدرج الذي أعطيك إياه». فالتهمته، فكان في فمي في حلاوة العسل.","3:4":"ثم قال لي: «ياابن آدم، انطلق إلى شعب إسرائيل وخاطبهم بكلماتي.","3:5":"فإنك لست مرسلا إلى أمة ذات لهجة غريبة ولغة مبهمة، بل إلى شعب إسرائيل،","3:6":"ولا إلى شعوب كثيرة غريبة اللهجات ومبهمة اللغات لا تفهم كلامهم. حقا لو أرسلتك إلى هؤلاء لسمعوا لك!","3:7":"لكن شعب إسرائيل لا يودون الاستماع لك، لأنهم لا يودون الاستماع لي، لأنهم جميعا معاندون قساة القلوب.","3:8":"ها أنا قد جعلت وجهك صلبا مثل وجوههم، وجبهتك قاسية مثل جباههم.","3:9":"قد جعلت جبهتك في صلابة الماس، أقسى من الصوان، فلا تخف منهم ولا ترتعب من مرآهم لأنهم شعب متمرد».","3:10":"ثم أردف قائلا: «ياابن آدم، استوعب في قلبك كل ما أحدثك به من كلام، واستمع إليه بأذنين مرهفتين.","3:11":"وامض إلى المسبيين من أبناء شعبك وقل لهم: هذا ما يعلنه السيد الرب. سواء سمعوا لك أو أبوا».","3:12":"ثم حملني الروح، فسمعت خلفي صوت زلزلة عنيفة قائلا: «مبارك مجد الرب من مكانه».","3:13":"فكان ذلك صوت أجنحة حين تلامست، وصوت العجلات المجاورة لها، فبدا كجلبة زلزال عنيف.","3:14":"وهكذا حلق بي روح الرب وحملني بعيدا، وقد جاشت حرارة روحي بمرارة نفسي، ولكن كانت يد الرب علي شديدة.","3:15":"ثم أقبلت على المسبيين القاطنين إلى جوار نهر خابور عند تل أبيب، فأقمت هناك حيث يسكنون متحيرا سبعة أيام.","3:16":"وفي ختام السبعة الأيام، أوحى إلي الرب بكلمته قائلا:","3:17":"«ياابن آدم، قد جعلتك رقيبا لشعب إسرائيل، فأصغ إلى كلمتي وأنذرهم بها على لساني.","3:18":"فإذا قلت للشرير: أنت لابد مائت، وأنت لم تنذره ولم تحذره ليرجع عن طرقه الأثيمة فيحيا، فإن ذلك الشرير يموت بذنبه، أما دمه فمن يدك أطلبه.","3:19":"لكن إن أنذرت الشرير ولم يرجع عن شره وعن طرقه الأثيمة، فإنه يموت بذنبه، وتنجو أنت بنفسك.","3:20":"وكذلك إن حاد البار عن بره وارتكب الإثم، ونصبت أمامه معثرة، فإنه يموت. ولأنك لم تنذره فإنه يموت بذنبه ولا تذكر بعد أعماله الصالحة التي قام بها، أما دمه فمن يدك أطلبه.","3:21":"أما إن كنت قد أنذرت البار حتى لا يخطيء، ولم يخطيء، فإنه حتما يحيا لأنه قبل الإنذار، وتنجو أنت بنفسك».","3:22":"ثم كانت هناك علي يد الرب فقال لي: «قم اخرج إلى السهل فأخاطبك».","3:23":"فنهضت ومضيت إلى السهل، وهناك رأيت مجد الرب واقفا، مماثلا لمجد الرب الذي رأيته عند نهر خابور، فانطرحت على وجهي.","3:24":"فدخل في الروح وأقامني على قدمي، ثم قال لي: «اذهب واعتزل في بيتك.","3:25":"وأنت ياابن آدم، ها هم يربطونك بالحبال ويقيدونك فلا تخرج في ما بينهم.","3:26":"وألصق لسانك بحنكك فتبكم وتكف عن تقريعهم لأنهم شعب متمرد.","3:27":"ولكن عندما أخاطبك، أفتح فمك فتقول لهم: هذا ما يعلنه الرب، من يسمع فليسمع، ومن يأب فليمتنع، لأنهم شعب متمرد».","4:1":"أما أنت ياابن آدم فخذ لنفسك لبنة وابسطها أمامك وارسم عليها مدينة أورشليم،","4:2":"وأقم عليها حصارا، وابن برجا، وانصب عليها متراسا، وطوقها بالجيوش، وأحطها من كل جانب بالمجانق،","4:3":"ثم خذ لنفسك صاجا من حديد واجعله سورا من حديد بينك وبين المدينة، وثبت وجهك عليها فتصبح محاصرة وأنت تحاصرها، فتكون هذه علامة لشعب إسرائيل.","4:4":"أما أنت فاتكيء على جانبك الأيسر، وضع عليه إثم شعب إسرائيل، إذ أنك تحمل إثمهم على حسب عدد الأيام التي تتكيء فيها عليه.","4:5":"فإني قد جعلت لك عدد أيام كعدد سنوات إثمهم: ثلاث مئة وتسعين يوما. فتحمل عبء إثم شعب إسرائيل.","4:6":"وحالما تكملها عد فاتكيء على جانبك الأيمن، واحمل إثم شعب يهوذا أربعين يوما. إذ جعلت كل يوم مقابل سنة.","4:7":"ثم ثبت وجهك نحو حصار أورشليم بذراع مكشوفة، وتنبأ عليها،","4:8":"وها أنا أوثقك بحبال لئلا تتقلب من جنب إلى جنب حتى تكتمل أيام حصارك.","4:9":"أما أنت فخذ لنفسك قمحا وشعيرا وفولا وعدسا ودخنا وكرسنة، واعجنها في وعاء واحد، واصنع لنفسك خبزا تأكل منه ثلاث مئة وتسعين يوما كعدد الأيام التي تتكيء فيها على جنبك.","4:10":"ويكون وزن كمية الطعام التي تأكلها في كل يوم تعادل عشرين شاقلا (نحو مئتين وأربعين جراما). تأكل وجبة واحدة في اليوم.","4:11":"وتشرب الماء بالكيل، فلا يزيد عن سدس الهين (نحو ثلثي لتر)، تشرب منه بين حين وآخر.","4:12":"وتأكله ككعك الشعير، بعد أن تخبزه على مشهد منهم فوق براز الإنسان.","4:13":"لأنه هكذا سيأكل أبناء إسرائيل خبزهم النجس بين الأمم الذين أجليهم إليهم».","4:14":"ولكني قلت: «آه، أيها السيد الرب، أنا لم أنجس نفسي أبدا فمنذ حداثتي حتى الآن لم آكل ميتة أو فريسة، ولم يدخل فمي لحم نجس».","4:15":"فقال: «انظر ها أنا أعطيك بعر البقر لتستعيض به عن براز الإنسان لتصنع عليه خبزك.","4:16":"ياابن آدم، ها أنا أبيد مؤونة الخبز في أورشليم، فيأكلون الخبز بالوزن معجونا بالغم، ويشربون الماء بالكيل ممزوجا بالحيرة.","4:17":"إذ يعوزهم الخبز والماء، ويلجأ الواحد إلى أخيه وقد اعترتهم الحيرة فيفنون جميعا بإثمهم.","5:1":"أما أنت ياابن آدم فخذ لنفسك سيفا حادا استخدمه كموسى الحلاق لتحلق رأسك ولحيتك، ثم خذ لنفسك ميزانا واقسم الشعر إلى ثلاثة أثلاث،","5:2":"واحرق بالنار ثلثا في وسط المدينة إذا اكتملت أيام الحصار، ثم تناول ثلثا آخر واضربه بالسيف حول خريطة المدينة المرسومة. أما الثلث الأخير فذره مع الريح، وأنا أستل سيفا خلفه.","5:3":"ولكن احتفظ بكمية قليلة منه وصرها في أطراف ثوبك.","5:4":"كذلك خذ بعضا من الشعر واطرحه في النار ليحترق، فتندلع منه نار على كل شعب إسرائيل».","5:5":"وهذا ما يعلنه السيد الرب: «هذه هي أورشليم التي أقمتها في وسط الشعوب تحيط بها الأراضي،","5:6":"فخالفت أحكامي بأشر مما خالفتها الأمم وسكان الأراضي المحيطة بها، إذ تنكروا لأحكامي، وفرائضي لم يمارسوها.","5:7":"لذلك من حيث أنكم تمردتم أكثر من الأمم المحيطة بكم، ولم تمارسوا فرائضي ولم تعملوا بمقتضى أحكامي، ولا بمقتضى أحكام الأمم التي حولكم.","5:8":"ها أنا أيضا أنقلب عليك ياأورشليم، وأجري عليك قضاء على مشهد من الأمم،","5:9":"فأصنع بك ما لم أصنعه من قبل، وما لن أصنع مثله من بعد، عقابا لك على جميع أرجاسك.","5:10":"إذ يأكل الآباء أبناءهم، والأبناء آباءهم، لأنني أجري فيك قضاء وأذري بقيتك كلها مع كل ريح.","5:11":"لهذا حي أنا يقول السيد الرب، لأنك قد دنست مقدسي بكل أصنامك المكروهة، وبجميع رجاساتك، فأنا أيضا أستأصل، ولا تترَأف عليك عيني ولا أعفو.","5:12":"ثلث سكانك يموتون بالوباء والجوع في وسطك، وثلث ثان يقتل حولك بالسيف، وثلث أخير أشتته بين الأمم وأتعقبه بسيف مسلول.","5:13":"وهكذا أنفس عن غضبي ويخمد سخطي إذ أكون قد انتقمت. وحين يستكين حنقي عليهم يدركون أني أنا الرب الذي أصدرت قضائي في احتدام غيرتي.","5:14":"وأجعلك خرابا وعارا بين الأمم المحيطة بك وأمام كل من يجتاز بك،","5:15":"فتكونين عارا ولعنة وعبرة ومثار دهشة للأمم المحيطة بك حين أنفذ فيك قضائي بغضب وغيظ وتقريعات حانقة. أنا الرب قد تكلمت.","5:16":"وعندما أرسل عليهم سهام الجوع المميتة التي أعدت للتدمير، السهام التي أرسلتها لخرابكم، عندئذ أزيد من الجوع عليكم وأبيد مؤونة خبزكم،","5:17":"وأرسل عليكم المجاعة والوحوش الضارية، فتثكلكم ويعمكم الوباء وسفك الدماء، وأجلب عليكم السيف. أنا الرب قد قضيت».","6:1":"وأوحى إلي الرب قائلا:","6:2":"«ياابن آدم، التفت بوجهك نحو جبال إسرائيل وتنبأ عليها،","6:3":"وقل: ياجبال إسرائيل أصغي إلى كلمة السيد الرب الذي يقول للجبال والتلال والأنهار والأودية: ها أنا أجلب عليكم سيفا وأهدم مرتفعاتكم،","6:4":"فتصبح مذابحكم أطلالا، وتتحطم مذابح بخوركم وأطرح قتلاكم أمام أصنامكم،","6:5":"وألقي جثث أبناء إسرائيل أمام أوثانهم، وأذري عظامكم حول مذابحكم.","6:6":"وحيثما تقيمون تتحول مدنكم إلى أطلال، ومرتفعات عبادتكم إلى خرائب، وأصنامكم إلى حطام ودمار، ومذابح بخوركم إلى أنقاض، وأعمالكم إلى فناء،","6:7":"ويسقط القتيل في وسطكم، فتدركون أني أنا الرب.","6:8":"وأعفو عن بقية منكم ليكون لكم ناجون من السيف يتشتتون بين الأمم، إذ تتبددون في كل الأرض.","6:9":"عندئذ يذكرني الناجون منكم، المشتتون بين الأمم التي سبيتهم إليها، لأني سحقت قلوبهم الزانية التي ضلت عني، وعيونهم التي زاغت وراء أصنامهم، فيعافون أنفسهم من جراء ما ارتكبوه من شرور، ومن أجل ما اقتر فوه من أرجاس،","6:10":"فيدركون أني أنا الرب، لم أتكلم عبثا حين توعدتهم بهذا الشر».","6:11":"وهذا ما يعلنه السيد الرب: «صفق بيديك، واخبط برجلك قائلا: آه من كل رجاسات شعب إسرائيل الشريرة، فإنهم سيموتون بالسيف والجوع والوباء.","6:12":"يموت البعيد بالوباء، والقريب يصرعه السيف، والباقي منهم والمحاصر تقضي عليهم المجاعة. وهكذا أنفث فيهم حنقي.","6:13":"عندئذ تدركون أني أنا الرب، حين يتناثر قتلاهم بين أصنامهم حول مذابحهم، وفوق كل أكمة عالية، وعلى قمم جميع الجبال، وتحت كل شجرة خضراء وبلوطة مورقة حيث كانوا يقربون رائحة سرور لكل أوثانهم.","6:14":"وأمد يدي عليهم في جميع مواطن إقامتهم، فأجعل الأرض خربة موحشة من الصحراء إلى دبلة، فيدركون أني أنا الرب».","7:1":"وأوحى إلي الرب قائلا:","7:2":"«ياابن آدم، هذا ما يعلنه الرب لأرض إسرائيل. النهاية قد أزفت على زوايا الأرض الأربع.","7:3":"قد أقبلت النهاية عليك، فأطلق غضبي عليك وأدينك بمقتضى طرقك، وأجازيك على كل رجاساتك ياأرض إسرائيل،","7:4":"فلا تتر أف عليك عيني، ولا أعفو، بل أجازيك بمقتضى طرقك، وتكون رجاساتك في وسطك. عندئذ تدركون أني أنا الرب».","7:5":"وهذا ما يعلنه السيد الرب: «هوذا شر قد أقبل، شر لا مثيل له.","7:6":"قد أزفت النهاية قد أزفت النهاية. انتبهت لك، وها هي مقبلة.","7:7":"قد حل بك القضاء ياساكن الأرض، وأزف الموعد، اقترب يوم الاضطراب لا يوم الهتاف في الجبال.","7:8":"أنا موشك على صب غضبي عليك وأنفث غيظي فيك، وأدينك بمقتضى طرقك، وأجازيك على كل رجاساتك،","7:9":"فلا تترَأف عليك عيني ولا أعفو، بل أجازيك بمقتضى طرقك، وتكون رجاساتك في وسطك. وعندئذ تدركون أني أنا الضارب.","7:10":"ها هو اليوم قد أقبل! قد أزف القضاء وأزهر الظلم وأفرخت الكبرياء","7:11":"انتصب الجور وصار عصا للشر، لذلك يفنى الظالمون وتفنى ثروتهم وضجيجهم ولا من ينوح عليهم.","7:12":"قد حان الموعد واقترب اليوم، فلا يفرحن المشتري ولا يحزنن البائع، لأن الغضب منصب على جمهورهم بأسره.","7:13":"فالبائع لن يسترد ما باعه مهما طال به العمر لأن قضاء الله ينطبق على كل جمهورهم ولن يتحول عنهم، وليس في وسع الشرير أن يحتفظ بحياته.","7:14":"قد نفخوا في البوق، وأعدوا كل شيء، ولكن ليس من يذهب لخوض القتال، لأن غضبي منصب على جمهورهم.","7:15":"السيف مسلط من خارج، والوباء والجوع من داخل. والذي في الصحراء يقضي عليه السيف، ومن في المدينة يفترسه الجوع والوباء.","7:16":"أما الناجون منهم فيلوذون بالجبال كحمام الأودية، يبكي كل واحد منهم على إثمه.","7:17":"جميع الأيدي مسترخية، وكل الركب مائعة كالمياه.","7:18":"يتلفعون بالمسوح، ويغشاهم الرعب، ويكسو العار وجوههم جميعا، ويطغى القرع على رؤوسهم.","7:19":"يطرحون فضتهم في الشوارع، ويضحى ذهبهم نجاسة، وتعجز فضتهم وذهبهم عن إنقاذهم في يوم غضب الرب. لا يشبعون منهما جوعهم، ولا يملأون منهما أجوافهم لأنهما كانا معثرة إثم لهم.","7:20":"حولوا جمال زينة هيكل الرب إلى زهو، وصنعوا من الذهب والفضة تماثيل أرجاسهم وأصنامهم المكروهة، لذلك جعلتها رجاسة لهم.","7:21":"أسلمها إلى أيدي الغرباء نهبا، ولأشرار الأرض سلبا فينجسونها.","7:22":"وأشيح بوجهي عنهم فيدنسون هيكلي، ويدخل إليه الناهبون وينجسونه.","7:23":"اصنع السلسلة لشعبي لأن الأرض قد عمها سفك الدماء، وساد المدينة الجور.","7:24":"لذلك، أجلب أشر الأمم فيرثون بيوتهم، وأقضي على كبرياء الأقوياء فتتنجس مقادسهم.","7:25":"وعندما يقبل الرعب يلتمسون السلام فلا يجدونه،","7:26":"وتتوالى بلية فوق بلية، وتروج إشاعة تلو إشاعة، فيطلبون رؤيا من النبي. غير أن الشريعة تنصرف عن الكاهن والمشورة عن الشيوخ.","7:27":"ينوح الملك ويتلفع الرئيس بالقنوط، وترجف أيدي الشعب. أعاملهم بمقتضى تصرفاتهم، وأدينهم بموجب أحكامهم فيدركون أني أنا الرب».","8:1":"وفي اليوم الخامس من الشهر السادس العبري (أي آب - أغسطس) من السنة السادسة، بينما كنت جالسا في بيتي، وشيوخ يهوذا ماثلون أمامي، حلت علي قوة السيد الرب هناك،","8:2":"فنظرت وإذا بشبه إنسان وكأنه من نار، وبدا وكأن نارا تتأجج من حقويه إلى أسفل. أما من حقويه فما فوق فبدا لمعان كلمعان النحاس المتألق.","8:3":"ثم مد شبه يد وقبض علي بناصية رأسي، وحلق بي روح بين الأرض والسماء وأحضرني في رؤى الله إلى أورشليم، إلى مدخل البوابة الشمالية للساحة الداخلية، حيث ينتصب التمثال المثير للغيرة.","8:4":"فإذا بمجد إله إسرائيل حال هناك كما كان حالا في الرؤيا التي شاهدتها في السهل.","8:5":"ثم خاطبني: «ياابن آدم، التفت الآن نحو الشمال». فالتفت وإذا بي أرى من شمالي باب المذبح تمثال الغيرة هذا منتصبا في المدخل.","8:6":"وقال لي: «ياابن آدم، هل شاهدت ما يرتكبون: هذه الرجاسات الفظيعة التي يقترفها شعب إسرائيل ليبعدوني عن مقدسي؟ ولكن انتظر، فلا تلبث أن تشهد أرجاسا أفظع».","8:7":"ثم أحضرني إلى مدخل الساحة، فنظرت وإذا بثقب في الجدار،","8:8":"فقال لي: «ياابن آدم، انقب في الجدار». فنقبت الجدار وإذا باب.","8:9":"فقال لي: «ادخل واشهد الأرجاس المقيتة التي يرتكبونها هنا».","8:10":"فدخلت ونظرت، فإذا كل تصاوير أشكال الحيوانات والبهائم النجسة، وجميع أصنام شعب إسرائيل مرسومة على كل جوانب الجدران،","8:11":"وقد مثل أمامها سبعون رجلا من شيوخ شعب إسرائيل، وانتصب في وسطهم يازنيا بن شافان، وفي يد كل واحد منهم مجمرته تتصاعد منها غمامة عطرة من البخور.","8:12":"فقال لي: «أرأيت ياابن آدم ما يقترفه كل واحد من شيوخ شعب إسرائيل في محراب تماثيله المنحوتة قائلين: الرب لا يرانا! الرب قد هجر الأرض.","8:13":"ولكن انتظر فلا تلبث أن تشهد أرجاسا أفظع يرتكبونها».","8:14":"ثم أحضرني إلى المدخل الشمالي لبوابة هيكل الرب، فإذا هناك نساء يندبن تموز (إله الخصب).","8:15":"فقال لي: «أشهدت ياابن آدم؟ انتظر فلا تلبث أن تشهد أرجاسا أفظع من هذه».","8:16":"ثم أحضرني إلى الفناء الداخلي لبيت الرب، فإذا عند مدخل هيكل الرب بين الرواق والمذبح نحو خمسة وعشرين رجلا أداروا ظهورهم لهيكل الرب، واتجهوا بوجوههم نحو الشرق ساجدين للشمس.","8:17":"فقال لي: «أشهدت ياابن آدم؟ أقليل ما ارتكبه شعب يهوذا من رجاسات هنا؟ فقد عاثوا في الأرض فسادا، وثابروا على إغاظتي، وقربوا كل ما هو منتن في هيكلي","8:18":"لذلك أعاقبهم بالغضب، ولا تترَأف عيني عليهم، ولا أعفو، وإن استغاثوا بصوت عال لا أستجيب لهم».","9:1":"ثم صرخ في مسمعي بصوت عال قائلا: «ليقترب محافظو المدينة. ليقترب كل واحد متزودا بأداة تدميره».","9:2":"فأقبل ستة رجال من طريق الباب الشمالي الأعلى، وكل واحد يحمل عدة تدميره بيده، يتوسطهم رجل مرتد كتانا، وعلى خاصرته دواة كاتب. فدخلوا ووقفوا إلى جوار مذبح النحاس.","9:3":"فارتفع مجد الرب من حيث كان حالا فوق الكروبيم، واتجه نحو عتبة الباب. ونادى الرجل المرتدي ثوب الكتان، الحامل على خاصرته دواة الكاتب","9:4":"وقال له الرب: «اجتز وسط مدينة أورشليم وارسم سمة على جباه الرجال الذين يئنون ويزفرون على كل ما ارتكب من أرجاس فيها».","9:5":"ثم قال للستة الآخرين على مسمعي: «اعبروا في المدينة خلفه واقتلوا. لا تترَأف عيونكم ولا تعفوا.","9:6":"أهلكوا الشيخ والشاب والعذراء والطفل والنساء. ولكن لا تقربوا من أي إنسان عليه السمة، وابتدئوا من مقدسي». فابتدأوا يهلكون الرجال والشيوخ الموجودين أمام الهيكل.","9:7":"وقال لهم: «نجسوا الهيكل واملأوا ساحاته بالقتلى، ثم اخرجوا». فاندفعوا إلى المدينة وشرعوا يقتلون.","9:8":"وبينما هم يقتلون بقيت أنا وحدي. فانطرحت على وجهي وصرخت قائلا: «آه أيها السيد الرب، أتفني جميع البقية الباقية من إسرائيل في سخطك على أورشليم؟»","9:9":"فأجابني: «إن إثم شعب إسرائيل ويهوذا عظيم جدا جدا، وقد غرقت الأرض بالدماء، وامتلأت المدينة فسادا لأنهم يقولون: قد هجر الرب الأرض، والرب لا يرى.","9:10":"لذلك أنا أيضا لا تترَأف عيني ولا أعفو، إنما أوقع ذنب تصرفاتهم على رؤوسهم».","9:11":"ثم ما لبث الرجل المرتدي الكتان الحامل على خاصرته داوة الكاتب أن رفع تقريره قائلا: «إني فعلت كما أمرتني».","10:1":"ثم نظرت وإذا على أديم المقبب الذي فوق رأس الكروبيم ما يشبه العرش، وكأنه من حجر العقيق الأزرق.","10:2":"وقال للرجل المرتدي الكتان: «ادخل بين العجلات تحت الكروب واملأ كفيك جمر نار من بين الكروبيم، وذر على المدينة». فدخل على مرأى مني.","10:3":"وكان الكروبيم واقفين عن يمين البيت حين دخل بين العجلات، فملأت السحابة الفناء الداخلي.","10:4":"ثم ارتفع مجد الرب عن الكروب واستقر على عتبة الهيكل، فامتلأ الهيكل من السحابة، وغمر الفناء لمعان من مجد الرب.","10:5":"وبلغ صوت أجنحة الكروبيم الفناء الخارجي كصوت الله القدير إذا تكلم.","10:6":"فلما أمر الرجل المرتدي الكتان أن يأخذ نارا من بين العجلات من بين الكروبيم دخل الرجل ووقف إزاء العجلة.","10:7":"فمد كروب من بين الكروبيم يده إلى النار التي كانت بين الكروبيم، وتناول منها جمرا، ووضعه في كفي المرتدي الكتان، فأخذها هذا وخرج.","10:8":"وبدا أن للكروبيم تحت أجنحتهم يدا تشبه يد البشر.","10:9":"ونظرت وإذا بأربع عجلات إزاء الكروبيم؛ كل عجلة بجوار كروب. وكان منظر العجلات كمنظر حجر الزبرجد.","10:10":"وكانت الأربع متماثلة الشكل وكأنما كل عجلة في وسط عجلة.","10:11":"وإذا تحركت لتسير فإنها كانت تتجه في سيرها في أي اتجاه من الاتجاهات الأربعة، وفقا لاتجاه الرأس، فتسير خلفه ولا تحيد عن طريقها.","10:12":"وكانت جوانب أجسام الكائنات وظهورها وأيديها وأجنحتها والعجلات التي تخصها ملأى بالعيون.","10:13":"ودعيت العجلات على مسمعي بالعجلات.","10:14":"وكان لكل واحد أربعة أوجه: الوجه الأول وجه كروب، والوجه الثاني وجه إنسان والوجه الثالث وجه أسد، والوجه الرابع وجه نسر.","10:15":"ثم ارتفع الكروبيم، فكانت هذه هي الكائنات التي شاهدتها بجوار نهر خابور.","10:16":"وعندما تحرك الكروبيم تحركت العجلات بجوارهم، وعندما فرد الكروبيم أجنحتهم ليحلقوا فوق الأرض، حلقت العجلات إلى جوارهم بنفس الاتجاه، ولم تحد عنهم.","10:17":"فإن توقفوا توقفت، وإن حلقوا تحلق معهم، لأن روح الكائنات الحية كان فيها أيضا.","10:18":"وفارق مجد الرب عتبة الهيكل وخيم فوق الكروبيم.","10:19":"وعندما ارتفع الكروبيم فردوا أجنحتهم وحلقوا فوق الأرض على مرأى مني، وحلقت العجلات معهم، ثم توقفوا عند مدخل بوابة بيت الرب الشرقي، ومجد الرب ما برح مخيما عليهم.","10:20":"هذه هي الكائنات الحية التي شاهدتها تحت إله إسرائيل عند نهر خابور. فعرفت أنهم الكروبيم.","10:21":"وكان لكل واحد أربعة أوجه وأربعة أجنحة، وتحت أجنحتهم أيد مماثلة لأيدي البشر.","10:22":"أما أشكال وجوههم فكانت نفس الوجوه التي رأيتها عند نهر خابور، لا تختلف عنها في صورها ومعالمها، وكل واحد يتحرك إلى الأمام حسب اتجاهه.","11:1":"ثم حلق بي الروح وأحضرني إلى بوابة بيت الرب الشرقية، فإذا عند مدخلها خمسة وعشرون رجلا، شاهدت في وسطهم يازنيا بن عزور وفلطيا بن بنايا رئيسي الشعب.","11:2":"فقال لي: «ياابن آدم، هؤلاء هم الرجال المتواطئون على الشر، المتآمرون بمشورة السوء في هذه المدينة،","11:3":"القائلون: ألم يحن الوقت لنبني حصونا؟ فهذه المدينة هي كالقدر (أي كسور حولنا) ونحن كاللحم. (أي كالمحتمين بالسور).","11:4":"لذلك تنبأ عليهم ياابن آدم، تنبأ!","11:5":"«واستقر علي روح الرب وقال: «هذا ما يعلنه الرب. هذا ما تحدثتم به ياشعب إسرائيل، ولكنني عالم بما يدور في خلدكم.","11:6":"لقد أكثرتم قتلاكم في هذه المدينة وملأتم منهم شوارعها.","11:7":"لذلك فإن قتلاكم الذين طرحتموهم في وسطها هم اللحم وهي القدر، وسأخرجكم منها.","11:8":"قد فزعتم من السيف، لذلك أجلب السيف عليكم، يقول الرب.","11:9":"وأخرجكم من وسط المدينة وأسلمكم إلى قبضة أعدائكم، وأنفذ فيكم أحكاما،","11:10":"فتقتلون بالسيف. وأنفذ قضاء فيكم في تخوم إسرائيل، فتدركون حينئذ أني أنا الرب.","11:11":"لن تكون هذه المدينة لكم قدرا، وأنتم لن تكونوا اللحم في وسطها. بل أنفذ قضائي في تخوم إسرائيل،","11:12":"فتدركون أني أنا الرب الذي لم تسلكوا في فرائضه، ولم تمارسوا أحكامه بل عملتم بمقتضى ممارسات الأمم المحيطة بكم».","11:13":"وحدث فيما كنت أتنبأ أن فلطيا بن بنايا مات، فانطرحت على وجهي وصرخت بصوت عظيم: «آه أيها السيد الرب أتبيد بقية إسرائيل؟»","11:14":"ثم أوحى الرب إلي بكلمته قائلا:","11:15":"«ياابن آدم، قل لإخوتك، وأقربائك وسائر شعب إسرائيل في الشتات معك، الذين قال لهم أهل أورشليم: ابتعدوا عن الرب إذ لنا قد وهبت هذه الأرض ميراثا.","11:16":"ولكن إن كنت قد فرقتهم بين الأمم وشتتهم بين البلاد، فإني أكون لهم مقدسا صغيرا في الأرض التي تبددوا فيها.","11:17":"لذلك قل لهم: سأجمعكم من بين الشعوب وأحشدكم من الأراضي التي شتتكم فيها وأهبكم أرض إسرائيل.","11:18":"وعندما يقبلون إليها ينتزعون منها جميع أوثانها الممقوتة ورجاساتها،","11:19":"وأعطيهم جميعا قلبا واحدا، وأجعل في داخلهم روحا جديدا، وأزيل قلب الحجر من لحمهم. وأستبدله بقلب من لحم،","11:20":"لكي يسلكوا في فرائضي ويطيعوا أحكامي ويمارسوها، ويكونوا لي شعبا وأنا أكون لهم إلها.","11:21":"أما الذين ضلت قلوبهم وراء أوثانهم ورجاستهم، فإني أجعلهم يلقون عقاب طرقهم، يقول السيد الرب».","11:22":"ثم فرد الكروبيم أجنحتهم وحلقوا مع العجلات ومع مجد الرب الذي ما برح مخيما عليهم من فوق.","11:23":"وارتفع مجد الرب عن وسط المدينة ووقف على الجبل شرقي المدينة.","11:24":"وحل الروح وأحضرني، في الرؤيا التي أعلنها لي روح الله، إلى أرض الجلاء في بلاد الكلدانيين، ثم ارتفعت عني الرؤيا التي شاهدتها،","11:25":"فأبلغت أهل السبي بجميع الوحي الذي أعلنه لي الرب.","12:1":"ثم أوحى إلي الرب بكلمته قائلا:","12:2":"«ياابن آدم، أنت مقيم في وسط شعب متمرد، لهم عيون ليروا ولكن لا يبصرون، ولهم آذان ليسمعوا ولكن لا يصغون، لأنهم شعب متمرد.","12:3":"أما أنت ياابن آدم فتأهب للسبي واخرج نهارا على مرأى منهم وامض من موضعك إلى موضع آخر لعلهم يفهمون، فإنهم شعب متمرد.","12:4":"فتخرج متاعك، متاع السفر نهارا على مشهد منهم، ثم تغادر أنت مساء أمامهم كالذاهبين إلى السبي.","12:5":"انقب لك حائطا أمام عيونهم واخرج منه.","12:6":"وعلى مشهد منهم احمل متاعك على كتفك وانقله عند العتمة. غط وجهك لكي لا ترى الأرض لأني جعلتك آية لشعب إسرائيل».","12:7":"ففعلت كما أمرت، فأخرجت نهارا متاعي. وعند المساء نقبت الحائط بيدي ونقلت أحمالي على كتفي عند العتمة أمامهم.","12:8":"ثم في الصباح أعلنت لي كلمة الرب قائلة:","12:9":"«ياابن آدم، ألم يسألك شعب إسرائيل المتمرد ماذا تصنع؟","12:10":"أبلغهم ما يعلنه الرب: هذه نبوءة بشأن رئيس أورشليم وكافة شعب إسرائيل الساكنين فيها.","12:11":"قل لهم: أنا آية لكم. فكما صنعت يصنع بهم، فيذهبون كلهم إلى الجلاء وإلى السبي.","12:12":"ويحمل الرئيس المتولي شؤونهم أحماله على كتفه في العتمة ويخرج. وتنقب له ثغرة في الحائط ليخرج منها وهو يغطي وجهه لئلا يرى الأرض بعينيه.","12:13":"وأبسط شبكتي عليه فيقع في شركي، وأحضره إلى بابل إلى أرض الكلدانيين، ولكن لن يراها، هناك يموت.","12:14":"وأبدد حاشيته وأعوانه وكل جيوشه في كل مكان وأتعقبهم بسيف مسلول.","12:15":"فيدركون أني أنا الرب حين أشتتهم بين الأمم وأبددهم في البلاد.","12:16":"وأبقي على فئة قليلة منهم أنجيها من السيف والجوع والوباء، لكي يحدثوا بكل رجاساتهم بين الأمم التي فرقتهم فيها فيدركون أني أنا الرب».","12:17":"ثم أوحى إلي الرب بكلمته قائلا:","12:18":"«ياابن آدم، كل خبزك بارتعاش، واشرب ماءك بارتعاد وخوف،","12:19":"وقل لشعب الأرض: هذا ما يعلنه السيد الرب عن أهل أورشليم في أرض إسرائيل: سيأكلون خبزهم بفزع، ويشربون ماءهم بارتعاد، لأن الأرض تقفر من قاطنيها من جراء ظلم المقيمين فيها.","12:20":"ويصيب المدن الآهلة الخراب. وتوحش الأرض، فتدركون أني أنا الرب».","12:21":"ثم أوحى إلي الرب بكلمته قائلا:","12:22":"«ياابن آدم، ما هذا المثل الشائع في أرض إسرائيل القائل: قد طالت الأيام وكذبت كل رؤيا؟.","12:23":"لذلك قل لهم: هذا ما يعلنه السيد الرب: ها أنا قد أبطلت هذا المثل فلا يعودون يرددونه في إسرائيل، بل قل لهم: قد أزفت الأيام وحان تحقيق كلام كل رؤيا،","12:24":"إذ لن تكون بعد رؤيا باطلة ولا عرافة متملقة في وسط شعب إسرائيل.","12:25":"لأني أنا الرب أتكلم، والكلمة التي أقضي بها تتم، من غير مماطلة، بل ها أنا أنطق بقضائي في أيامكم أيها الشعب المتمرد وأنفذه في حينه، يقول السيد الرب».","12:26":"ثم أوحى إلي الرب بكلمته قائلا:","12:27":"«ياابن آدم، ها شعب إسرائيل يقولون: إن الرؤيا التي تراها لا تتم إلا بعد أيام كثيرة، ونبوءتك لا تتحقق إلا في أزمنة بعيدة","12:28":"لذلك قل لهم: هذا ما يعلنه السيد الرب: لن يتأخر بعد تنفيذ كلمة من كلامي الذي قضيت به، فكل كلمة نطقت بها لابد أن تتم، يقول السيد الرب».","13:1":"وأوحى إلي الرب بكلمته قائلا:","13:2":"«ياابن آدم، تنبأ على أنبياء إسرائيل الكذبة المتنبئين من عند أنفسهم وقل لهم: اسمعوا كلمة الرب.","13:3":"ويل للأنبياء الحمقى الضالين وراء أرواحهم من غير أن يروا شيئا.","13:4":"أنبياؤك ياإسرائيل هم كالثعالب في الخرائب.","13:5":"لم تبرزوا إلى الثغرات، ولم تشيدوا جدارا حول بيت إسرائيل لتصمدوا في القتال في يوم الرب،","13:6":"إنما رؤياهم باطلة، وعرافتهم كاذبة. يقولون: يقول الرب، والرب لم يرسلهم، ومع ذلك يطمعون في تحقيق كلمتهم.","13:7":"ألم تروا رؤيا باطلة، وتنطقوا بعرافة كاذبة قائلين: يقول الرب، وأنا لم أتكلم؟","13:8":"لذلك يعلن الرب: لأنكم تكلمتم باطلا وادعيتم رؤيا كاذبة، فها أنا أنقلب عليكم يقول السيد الرب.","13:9":"فتكون يدي على الأنبياء ذوي الرؤيا الباطلة والعرافة الكاذبة، فلا يكون لهم مقام في جماعة شعبي، ولا تدون أسماؤهم في كتاب بيت إسرائيل، ولا يدخلون أرض إسرائيل، فتدركون أني أنا السيد الرب.","13:10":"لأنهم حقا أضلوا شعبي قائلين: سيكون لكم سلام مع أنه ليس هناك سلام، فكان شعبي يبني حائطا وهم يطلونه بماء الكلس.","13:11":"قل للطالين بماء الكلس: إن الحائط يتداعى، إذ ينهمر مطر جارف. وأنتن ياحجارة البر د تساقطن، ولتعصف به ريح جائحة.","13:12":"فلا يلبث السور أن ينهار أفلا تسألون آنئذ: أين الطين الذي طينتم به؟","13:13":"لذلك، هذا ما يعلنه السيد الرب: ها أنا أجعل ريحا عاتية تخترق السور بفعل حنقي، ومطرا جارفا ينهمر في خضم غضبي، وحجارة برد تتساقط في أثناء سخطي لكي تهلك،","13:14":"فأهدم السور الذي طليتموه بماء الكلس وأسويه بالأرض فيتعرى أساسه وتتداعى المدينة وتفنون جميعا في وسطها فتدركون أني أنا الرب.","13:15":"فأنفث غضبي بالسور وبمن يطلونه بماء الكلس وأقول لكم: قد تلاشى السور والذين يطلونه.","13:16":"الذين هم أنبياء إسرائيل الأدعياء، المتنبئون لإسرائيل، الذين يرون لها رؤى سلام، مع أنه لا سلام هناك، يقول السيد الرب.","13:17":"أما أنت ياابن آدم، فالتفت نحو بنات شعبك المتنبئات من عند أنفسهن وتنبأ عليهن،","13:18":"وقل هذا ما يعلنه السيد الرب: ويل للخائطات العصائب السحرية لكل معاصم الأيدي والأنقاب لرأس كل قامة لاصطياد النفوس. أنتن تصطدن نفوس شعبي وتستحيين نفوسكن","13:19":"فتدنسنني عند شعبي لقاء حفنة شعير وفتات خبز حتى تمتن نفوسا ما كان يجب أن تموت، ولكي تستحيين نفوسا أخرى لم يكن لها أن تحيا من جراء كذبكن على شعبي السامع للكذب.","13:20":"لذلك، هذا ما يعلنه السيد الرب: أنا ضد عصائبكن السحرية التي تصطدن بها النفوس كفراخ الطير سأمزقها عن أذرعكن، وأحرر النفوس التي اصطدتموها فتطير.","13:21":"وأمزق أنقابكن وأنقذ شعبي من أيديكن، فلا يظلون بعد في قبضتكن فريسة، فتدركن أني أنا الرب.","13:22":"لأنكن أحزنتن قلب الصديق بأكاذيبكن، مع أنني لم أحزنه، وشددتن عزائم الشرير لئلا يرجع عن طريقه الأثيمة فيحيا.","13:23":"لذلك لن تعدن ترين رؤى باطلة، ولا تمارسن العرافة بعد، وأنقذ شعبي من أيديكن فتدركن أني أنا الرب».","14:1":"وحضر إلي بعض شيوخ إسرائيل وجلسوا أمامي،","14:2":"فأوحى إلي الرب بكلمته قائلا:","14:3":"ياابن آدم، إن هؤلاء الرجال قد نصبوا أصنامهم في قلوبهم، وأقاموا معثرة إثمهم تلقاء وجوههم، أفأجيب عن سؤالهم؟","14:4":"لذلك قل لهم: هذا ما يعلنه السيد الرب: كل رجل من شعب إسرائيل نصب أصنامه في قلبه وأقام معثرة إثمه تلقاء وجهه، ثم أقبل إلى النبي، فإني أنا الرب أجيب ذلك الوافد على كثرة أصنامه،","14:5":"لكي أستأسر قلوب شعب إسرائيل ثانية، لأنهم ارتدوا عني بالغواية وراء أصنامهم.","14:6":"لذلك قل لشعب إسرائيل، هذا ما يعلنه السيد الرب: توبوا وارجعوا عن أصنامكم واصرفوا وجوهكم عن كل رجاستكم.","14:7":"لأن كل رجل من شعب إسرائيل ومن الغرباء الدخلاء القاطنين في إسرائيل، إذا ارتد عني ونصب أصنامه في قلبه وأقام معثرة إثمه تلقاء وجهه، ثم حضر إلى النبي ليسأله عني، فإني أنا الرب أجيبه بذاتي.","14:8":"وأنقلب على ذلك الإنسان وأجعله عبرة ومثلا، وأستأصله من بين شعبي، فتدركون أني أنا الرب.","14:9":"فإذا ضل النبي ونطق بنبوءة باطلة، فإني أنا الرب قد أغويت ذلك النبي، لأنه تصرف من نفسه. فأعاقبه وأبيده من بين شعبي إسرائيل.","14:10":"وينالون عقاب إثمهم، ويكون ذنب النبي مماثلا لذنب السائل.","14:11":"لكي لا يضل عني شعب إسرائيل من بعد، ويتنجسوا بآثامهم، وإنما يكونون لي شعبا وأنا أكون لهم إلها، يقول السيد الرب».","14:12":"ثم أوحى إلي الرب بكلمته قائلا:","14:13":"«ياابن آدم، إذا أخطأت إلي أرض وخانت عهدي، أعاقبها وأعوزها مؤونة الخبز وأشيع فيها الجوع، وأفني منها الناس والبهائم،","14:14":"وحتى لو كان فيها هؤلاء الرجال الثلاثة: نوح ودانيآل وأيوب، فإنهم يخلصون وحدهم فقط ببرهم.","14:15":"وإن أطلقت في تلك الأرض وحوشا ضارية فأقفرتها، وأصبحت أطلالا لا يجتاز فيها عابر خوفا من الوحوش،","14:16":"وكان يقيم فيها هؤلاء الثلاثة الرجال، فحي أنا يقول السيد الرب، إنهم لا يقدرون على إنقاذ أبناء لها وبنات. إنما هم وحدهم يخلصون، وتصير الأرض موحشة.","14:17":"وإذا جلبت سيفا على تلك الأرض وقلت: ياسيف اعبر في الأرض وافنها وأبدت منها الناس والبهائم،","14:18":"وكان يقيم فيها هؤلاء الثلاثة الرجال، فحي أنا يقول الرب، إنهم لا يقدرون على إنقاذ أبناء لها وبنات، إنما هم وحدهم يخلصون.","14:19":"إذا أفشيت وبأ في تلك الأرض، وسكبت عليها غضبي بسفك الدم لأفني منها الناس والبهائم،","14:20":"وكان يقيم فيها هؤلاء الثلاثة الرجال، فحي أنا يقول الرب إنهم لا يقدرون على إنقاذ ابن لها أو ابنة، إنما يخلصون وحدهم فقط ببرهم.","14:21":"فكم بالأحرى يحدث إذا أرسلت أحكامي الأربعة الشديدة: الحرب والمجاعة والوحوش الضارية والوباء على أورشليم لأبيد منها الناس والبهائم.","14:22":"ولكن ستبقى فيها بقية ناجية من أبناء وبنات، يخرجون منها، فيقبلون إليكم فتشهدون حسن سلوكهم وتصرفاتهم فتتعزون عن المصائب التي أوقعتها بأورشليم وعن جميع ما ابتليتها به.","14:23":"عندئذ يعزونكم حين تشهدون حسن سلوكهم وتصرفاتهم، فتدركون أن كل ما صنعته فيها لم يكن عبثا، يقول السيد الرب».","15:1":"وأوحى إلي الرب بكلمته قائلا:","15:2":"«ياابن آدم، بماذا يفضل عود الكرم على كل عود آخر أو على غصن من أغصان شجر الغابة؟","15:3":"أيؤخذ منه قضيب ليصنع منه شيء ما؟ أو يختارون منه وتدا يعلق عليه إناء؟","15:4":"إنما يطرح وقودا للنار فتلتهم النار طرفيه وتجعل وسطه فحما، أيصلح بعد لشيء؟","15:5":"فإن كان وهو سليم لم يصلح لعمل ما، فكم بالأحرى بعد أن التهمته النيران واحترق؟ أيصلح بعد لصنع شيء؟","15:6":"لذلك يقول السيد الرب، كما جعلت عود الكرم من بين أشجار الغابة وقودا للنار، هكذا أجعل أهل أورشليم حطبا لها.","15:7":"وأنقلب عليهم حتى إذا خرجوا من نار تلتهمهم نار أخرى، فتدركون أني أنا الرب حين أنقلب عليكم.","15:8":"وأجعل الأرض مقفرة لأنهم خانوا عهدي يقول السيد الرب».","16:1":"وأوحى إلي الرب بكلمته قائلا:","16:2":"«ياابن آدم، أطلع أهل أورشليم على أرجاسهم.","16:3":"وقل هذا ما يعلنه السيد الرب لأورشليم: أصلك ومولدك من أرض الكنعانيين. أبوك أموري وأمك حثية.","16:4":"في يوم مولدك لم يقطع حبل سرتك ولم تنظفي بماء ولم تدلكي بملح، ولم تقمطي. (إشارة إلى أن أحدا لم يكترث لها).","16:5":"لم ترأف بك عين أو تعطف عليك لتصنع لك شيئا من هذا. بل نبذت في الصحراء احتقارا لك يوم مولدك.","16:6":"وحين مررت بك وشهدتك مازلت ملطخة بدمائك قلت لك: عيشي بدمك. نعم عيشي بدمك.","16:7":"وكثرتك كنبت الحقل، فنميت وكبرت وبلغت عمرا صرت فيه أجمل الجميلات، فنهد ثدياك ونما شعرك، ولكنك كنت عارية متجردة.","16:8":"فمررت بك ورأيتك وإذا بك قد بلغت سن الحب، فبسطت عليك أطراف ثوبي، وسترت عورتك وحلفت لك وأبرمت معك عهدا، فصرت لي، يقول السيد الرب.","16:9":"ثم غسلتك بماء، ونظفتك من الدم وطيبتك بالدهن.","16:10":"وكسوتك بثياب موشاة وحذوتك بنعلين من جلد الدلفين، ولفعتك بالكتان الفاخر، ودثرتك بالحرير،","16:11":"وزينتك بالحلي، إذ وضعت أساور في يديك وعقدا في عنقك.","16:12":"وجعلت خزامة في أنفك وقرطين في أذنيك وإكليل جمال على رأسك","16:13":"فتزينت بالذهب والفضة، وكانت ثيابك من الكتان الفاخر والحرير وكل ما هو موشى. وأكلت السميذ والعسل والزيت، فتمتعت بأروع الجمال حتى صرت صالحة لتكوني زوجة ملك.","16:14":"فذاع اسمك بين الأمم لفرط جمالك لأنه اكتمل بفضل بهائي الذي أضفيته عليك، يقول السيد الرب.","16:15":"ولكنك اعتمدت على جمالك وزنيت اتكالا على شهرتك. أغدقت عهارتك على كل عابر سبيل راغب فيك","16:16":"وأخذت بعض ثيابك فصنعت لنفسك مشارف للأصنام ملونة زنيت عليها زنى لم يكن له مثيل ولن يكون.","16:17":"وأحضرت ما وهبتك من حلي الجواهر، من ذهبي وفضتي، فصنعت منها تماثيل ذكور وزنيت بها (أي عبدتها).","16:18":"وأخذت ثيابك الموشاة فكسوتها بها، ووضعت أمامها دهني وبخوري،","16:19":"وخبزي الذي قدمته لك والسميذ والزيت والعسل الذي أطعمتك، وقربتها أمامها كتقدمة سرور، هكذا فعلت يقول السيد الرب.","16:20":"ثم أخذت أبناءك وبناتك الذين أنجبتهم لي، فذبحتهم قرابين لها. فهل كان زناك أمرا يسيرا؟","16:21":"قد ذبحت أبنائي وسلمتهم للأوثان ليجوزوا في النار قربانا لها.","16:22":"وفي جميع رجاساتك وزناك لم تذكري أيام حداثتك حين كنت عارية متجردة ملطخة بدمك.","16:23":"ثم من بعد كل شرك ويل، ويل لك يقول السيد الرب","16:24":"شيدت لنفسك ماخورا وصنعت لك أنصابا في كل ساحة.","16:25":"بنيت مرتفعتك عند ناصية كل طريق، ودنست جمالك ووهبت جسدك لكل عابر سبيل لتكثري من عهارتك.","16:26":"وزنيت مع أبناء مصر، جيرانك الشهوانيين، وأكثرت فواحشك لإسخاطي.","16:27":"ها أنا أعاقبك وأنقص من نصيبك وأسلمك لأهواء عدواتك بنات الفلسطينيين اللواتي يخجلن من تصرفك الفاجر.","16:28":"وإذ لم تشبعي زنى ارتكبت الفواحش مع أبناء أشور من غير أن تكتفي.","16:29":"ثم أكثرت من ارتكاب الفجور في أرض الكنعانيين حتى ديا ر الكلدانيين، ومع ذلك لم تكتفي.","16:30":"ما أشر قلبك يقول السيد الرب إذ اقترفت هذه الموبقات كلها، فعل امرأة زانية صفيقة.","16:31":"فشيدت ماخورك عند ناصية كل طريق، وأقمت مرتفعة صنمك في كل ساحة ولم تكوني كالزانية التي تقبض أجرة زناها، لأنك وهبت نفسك مجانا احتقارا لكل أجرة.","16:32":"إذ كنت زوجة فاسقة أحلت الغرباء موضع زوجها.","16:33":"كل الزانيات ينلن هدايا من الرجال، أما أنت فأعطيت هداياك لمحبيك، ورشوتهم كي يقبلوا إليك من كل صوب ليزنوا معك.","16:34":"فأنت في زناك تختلفين عن بقية النساء الزانيات، إذ لا يسعى أحد وراءك ليزني معك بل على النقيض، أنت تعطينهم أجرة ليفسقوا معك ولا تقبضين منهم أجرة.","16:35":"لذلك اسمعي أيتها الزانية قضاء الرب:","16:36":"من حيث أنك أنفقت مالك وكشفت عن عريك في فواحشك لعشاقك ولسائر أصنامك الممقوتة، ومن أجل دماء أبنائك الذين قربتهم لها،","16:37":"ها أنا أحشد جميع عشاقك الذين تلذذت بهم، وجميع من تدلهت بهم مع كل الذين أبغضتهم فأجمعهم عليك من كل ناحية، وأكشف عن عريك فيشاهدون عورتك كلها،","16:38":"وأدينك كما تدان الزانيات وسافكات الدماء، وأوقع بك عقاب دم سخطي وغيرتي،","16:39":"وأسلمك لأيديهم فيهدمون ماخورك ومرتفعة نصبك، ويسلبونك ثيابك ويستولون على جواهر زينتك ويتركونك عارية متجردة،","16:40":"ويثيرون عليك الجموع ويرجمونك بالحجارة ويمزقونك بسيوفهم.","16:41":"ويحرقون بيوتك بالنار، وينفذون فيك أحكاما على مرأى نساء كثيرات. عندئذ أمنعك عن الزنى ولا تبذلين أجرة بعد للزناة معك.","16:42":"حينئذ أسكن شدة غضبي عليك وأصرف عنك غيرتي فأهدأ ولا أسخط بعد.","16:43":"ولأنك لم تذكري أيام حداثتك، وإنما أثرت حنقي بارتكاب جميع هذه الموبقات، ها أنا بدوري أعاقبك أشد العقاب، يقول السيد الرب، فلا تقترفين هذه الرذيلة فوق رجاساتك كلها.","16:44":"ها إن كل متمثل يقتبس هذ المثل عليك قائلا: كما تكون الأم تكون ابنتها","16:45":"فأنت ابنة أمك التي كرهت زوجها وأبناءها، وأنت شقيقة أخواتك اللواتي عفن رجالهن وأبناءهن. فأمكن حثية وأبوكن أموري.","16:46":"وأختك الكبرى هي السامرة المقيمة مع بناتها إلى الشمال منك، وأختك الصغرى هي سدوم المقيمة مع بناتها إلى الجنوب منك.","16:47":"ولم تكتفي بالسلوك في طرق فجورهن وارتكاب مثل أرجاسهن وكأن ذلك قليل عليك بل تفوقت عليهن فسادا في جميع طرقك.","16:48":"لذلك يقول السيد الرب حي أنا، إن سدوم أختك وبناتها لم يقترفن المفاسد التي اقترفتها أنت وبناتك.","16:49":"أما إثم أختك سدوم، فإنها مع بناتها طغت عليها الغطرسة والتخمة وسلام الاطمئنان، ولم تغث الفقير والمسكين.","16:50":"وتشامخن وارتكبن الرجس أمامي، فمحوتهن عندما شاهدت ذلك.","16:51":"ولم تخطيء السامرة نصف خطاياك، بل كنت أكثر رجاسات منهن، فجعلت أختيك تبدوان أكثر صلاحا منك، من جراء جميع رجاساتك التي اقترفتها","16:52":"فاحملي أنت أيضا عارك، إذ جعلت القضاء في صالح أختيك لفرط معاصيك التي تفوقت بها على رجاستهن. قد أصبحن أكثر برا منك، فاخزي واحملي عارك إذ قد بررت أخواتك.","16:53":"ولكني سأرد سبيهن: سبي سدوم وبناتها، وسبي السامرة وبناتها، وسبي مسبييك في جملتهم.","16:54":"لكي تحملي عارك وتخجلي مما ارتكبت عندما أصبحت تعزية لهن.","16:55":"فأخواتك: سدوم وبناتها، والسامرة وبناتها يعدن إلى سابق عهدهن، وكذلك أنت وبناتك أيضا.","16:56":"إن اسم أختك سدوم لم يرد ذكره على فمك في يوم غطرستك،","16:57":"قبل انكشاف شرك. وها أنت قد صرت مثار تعيير بنات أرام وجميع المحيطين بها من بنات فلسطين وكل اللواتي حولك ممن احتقرنك.","16:58":"لقد حملت عقاب فجورك ورجاساتك، يقول الرب.","16:59":"لهذا سأصنع بك كما صنعت، إذ ازدريت بالقسم عندما نكثت العهد.","16:60":"أما أنا فأذكر عهدي معك في أيام حداثتك، وأعقد معك عهدا أبديا،","16:61":"فتذكرين عندئذ طرقك حين تستقبلين أختيك: الكبرى والصغرى كلتيهما، وأجعلهما كبنتين لك، إنما ليس ذلك بفضل عهدك.","16:62":"فأقيم عهدي معك فتدركين أني أنا الرب،","16:63":"لكي تتذكري فتخجلي ولا تفتحي فمك من بعد بسبب خزيك، حين أغفر لك كل ما ارتكبت من شر يقول السيد الرب».","17:1":"ثم أوحى إلي الرب بكلمته قائلا:","17:2":"«ياابن آدم، اطرح أحجية، واضرب مثلا لشعب إسرائيل،","17:3":"وقل هذا ما يعلنه السيد الرب: قد حضر إلى لبنان نسر عظيم ضخم الجناحين، طويل القوادم، كث الريش الملون، وأخذ ناصية الأرز.","17:4":"فقصف رأس خراعيبه وحمله إلى أرض كنعان، ووضعه في مدينة التجار","17:5":"وأخذ أيضا بعض بزور الأرض وزرعها في تربة خصيبة إلى جوار مياه غزيرة، وأقامها كالصفصاف.","17:6":"فنبتت البزور وصارت كرمة ممتدة الفروع ذات ساق قصيرة، انعطفت نحو النسر وتأصلت جذورها تحته. وهكذا صارت كرمة أنبتت فروعا وأفرخت أغصانا.","17:7":"ولكن كان هناك نسر آخر ضخم الجناحين كث الريش، فإذا بهذه الكرمة تعطف نحوه أصولها وتمد إليه فروعها لكي يرويها ماء في حوض مغرسها.","17:8":"وكانت قد غرست في أرض خصيبة إلى جوار مياه غزيرة، لتفرخ أغصانا وتحمل ثمارا وتصبح كرمة رائعة.","17:9":"فهل تزدهر؟ ألا يجتث أصولها ويقطع ثمرها فتذوي هي وكل أوراق أغصانها؟ إنها لن تحتاج إلى ذراع قوية أو إلى أمة كبيرة كي يقتلعوها من أصولها.","17:10":"وإذا غرست ثانية فهل تزدهر؟ ألا تذوي ذويا كاملا حين تهب عليها الريح الشرقية؟ إنها حتما تذبل في حوض مغرسها».","17:11":"ثم أوحى إلي الرب بكلمته قائلا:","17:12":"«قل للشعب المتمرد: ألم تعلموا مغزى هذه الأحجية؟ ها إن ملك بابل قد زحف إلى أورشليم وأسر ملكها ورؤساءها وأتى بهم إليه، إلى بابل.","17:13":"واختار واحدا من ذرية العائلة الملكية وأبرم معه عهدا، وارتبط معه بقسم، واعتقل جميع أشراف البلاد،","17:14":"لتظل المملكة ذليلة عاجزة عن النهوض، بل توفي فقط بعهده ولا تنقرض.","17:15":"لكن الملك تمرد عليه وأوفد رسلا إلى مصر يطلب خيلا وجيوشا غفيرة. أيفلح في ذلك؟ أيفلت مرتكب هذا الفعل؟ لقد نقض عهدا، أفيفلت من العواقب؟","17:16":"حي أنا يقول السيد الرب، إنه يموت عنده في بابل، مدينة الملك الذي نصبه ملكا، فازدرى هو حلفه، ونكث عهده.","17:17":"ولن يغيثه فرعون بجيوشه العظيمة وجموعه الغفيرة في القتال، حين تقام المتاريس وتبنى بروج الحصار للقضاء على نفوس كثيرة.","17:18":"لقد ازدرى الحلف حين نكث العهد، وها هو قد مد يد الولاء إلى مصر. ولكنه وإن فعل هذا كله لن يفلت.","17:19":"لذلك، هذا ما يقوله السيد الرب: حي أنا؛ إن حلفي الذي ازدراه، وعهدي الذي نكثه لابد أن يقعا على رأسه.","17:20":"وأنشر شبكتي عليه فيقع في شركي، وأحضره إلى بابل وأحاكمه هناك على ما ارتكبه من تعد علي.","17:21":"ويصرع السيف نخبة جيشه ويتشتت الناجون مع كل ريح، فتدركون أني أنا الرب قد تكلمت.","17:22":"ثم آخذ من ناصية الأرز العالي برعما وأنصبه، وأقطف من رؤوس أغصانه غصنا طريا وأغرسه في جبل شامخ شاهق،","17:23":"في جبل إسرائيل المرتفع فينبت أغصانا ويحمل ثمارا ويصبح أرزا وارفا يأوي تحت ظل أغصانه كل طائر.","17:24":"فتدرك جميع أشجار الصحراء (أي جميع الأمم) أني أنا الرب، أذللت الأشجار المتعالية، وعظمت الأشجار الدنية. يبست الشجر النضر، وأنضرت الشجر المتيبس، أنا الرب قلت وأنجزت».","18:1":"وأوحى إلي الرب بكلمته قائلا:","18:2":"«ما بالكم تضربون هذا المثل بشأن أرض إسرائيل قائلين: أكل الآباء الحصرم فضرست أسنان الأبناء؟","18:3":"حي أنا يقول الرب: إنكم حتما لن تضربوا هذا المثل في إسرائيل بعد اليوم.","18:4":"ها جميع النفوس هي لي. نفس الأب كنفس الابن كلتاهما لي. والنفس التي تخطيء هي تموت.","18:5":"ولكن إن كان المرء صالحا يمارس الحق والعدل،","18:6":"ولم يصعد إلى الجبال ليأكل أمام الأنصاب، ولم يلتفت إلى أصنام شعب إسرائيل، ولم يزن مع امرأة جاره ولم يعاشر امرأة طامثا،","18:7":"ولم يظلم أحدا، بل رد للمديون رهنه، ولم يسلب قط، وأطعم الجائع خبزه وكسا العريان ثوبا،","18:8":"ولم يقرض بالربا ولم يأخذ حراما، وكف يده عن ارتكاب الإثم، وقضى بالإنصاف والحق بين إنسان وإنسان.","18:9":"ومارس فرائضي، وأطاع أحكامي بأمانة، فهو صديق وحتما يحيا، يقول السيد الرب.","18:10":"فإن أنجب ابنا لصا سفاكا للدماء، فاقترف بحق أخيه بعضا من ذلك الشر،","18:11":"ولم يصنع شيئا من ذلك الخير، بل صعد إلى الجبال ليأكل أمام الأنصاب، وزنى مع امرأة جاره،","18:12":"وجار على البائس والمسكين وسلب ولم يرد الرهن، والتفت إلى الأصنام ليعبدها وارتكب الأرجاس،","18:13":"وأقرض بالربا وأخذ ربحا حراما، أفيحيا؟ إنه لا يحيا! لأنه اقترف جميع هذه الموبقات فإنه حتما يموت، ويكون دمه على رأسه.","18:14":"أما إن أنجب ابنا شهد جميع ما ارتكبه أبوه من ذنوب ولم يقترف مثلها،","18:15":"فلم يأكل على الجبال أمام الأنصاب، ولم يلتفت إلى أصنام شعب إسرائيل ليعبدها، ولم يزن مع امرأة جاره،","18:16":"ولم يظلم أحدا، ولم يحتفظ برهن ولم يسلب قط، بل أطعم خبزه للجائع وكسا العريان ثوبا.","18:17":"ولم يسيء إلى البائس، ولم يقرض بالربا ولا بالربح الحرام، وقضى بالإنصاف ومارس فرائضي وأطاع أحكامي، فإنه لا يموت بإثم أبيه، بل حتما يحيا.","18:18":"أما أبوه فلأنه ظلم وسلب أخاه وارتكب ما هو طالح بين شعبه، فهو حتما يموت بإثمه.","18:19":"ومع ذلك تقولون: لماذا لا يعاقب الابن بوزر أبيه؟ حين يمارس الابن الإنصاف والحق ويعمل بكل فرائضي فإنه حتما يحيا.","18:20":"أما النفس التي تخطيء فهي تموت. لا يعاقب الابن بإثم أبيه ولا الأب بإثم ابنه. يكافأ البار ببره ويجازى الشرير بشره.","18:21":"ولكن إن رجع الشرير عن خطاياه كلها التي ارتكبها، ومارس جميع فرائضي وصنع ما هو عدل وحق فإنه حتما يحيا، لا يموت.","18:22":"ولا تذكر له جميع آثامه التي ارتكبها. إنما يحيا ببره الذي عمله.","18:23":"أحقا أسر بموت الشرير يقول السيد الرب؟ أليس برجوعه عن طرقه الآثمة فيحيا؟","18:24":"وإذا تحول الصديق عن بره وارتكب إثما على غرار كل الرجاسات التي يرتكبها الشرير، أفيحيا؟ إن كل ما صنعه من بر لا يذكر له. إنما يموت بخيانته التي خانها، وما اقترفه من خطايا.","18:25":"ومع ذلك تقولون: ليست طريق الرب عادلة. فأصغوا الآن ياشعب إسرائيل: أطريقي غير عادلة؟ أليست طرقكم هي المعوجة؟","18:26":"إذا تحول البار عن بره وارتكب إثما ومات بسببه، فهو بإثمه الذي جناه يموت.","18:27":"وإذا رجع الأثيم عن شره الذي اقترفه ومار س الحق والعدل، فهو يحيي نفسه،","18:28":"لأنه اعتبر وتاب عن كل ذنوبه التي ارتكبها. لذلك حتما يحيا. لا يموت.","18:29":"ومع ذلك يقول شعب إسرائيل إن طريق الرب غير عادلة. أطرقي غير عادلة ياشعب إسرائيل؟ أليست طرقكم هي المعوجة؟","18:30":"لذلك أدينكم ياشعب إسرائيل، كل واحد بمقتضى طرقه، يقول السيد الرب. توبوا وارجعوا عن ذنوبكم كلها، فلا يكون لكم الإثم معثرة هلاك.","18:31":"اطرحوا عنكم كل ذنوبكم التي ارتكبتموها، واحصلوا لأنفسكم على قلب جديد وروح جديدة. فلماذا تنقرضون ياشعب إسرائيل؟","18:32":"إذ لا أسر بموت أحد، يقول السيد الرب، فتوبوا واحيوا.","19:1":"أما أنت فاتل مرثاة على رؤساء إسرائيل:","19:2":"وقل: ماذا كانت أمك؟ لبوة ربضت بين الأسود وربت جراءها بين الأشبال.","19:3":"حتى إذا كبر أحد جرائها وصار شبلا، وتعلم الصيد، أكل الناس.","19:4":"وعندما بلغ أمره الأمم وقع في حفرتهم، فأخذوه مسوقا بخزائمه إلى ديار مصر.","19:5":"وعندما أدركت في أثناء انتظارها أن رجاءها قد هلك، أخذت جروا آخر وجعلته شبلا.","19:6":"فتمشى بين الأسود وصار شبلا وتعلم الصيد، وأكل الناس،","19:7":"وهدم قصور هم وخرب مدنهم، فارتعبت الأرض ومن فيها من زمجرة زئيره،","19:8":"فاجتمعت عليه الأمم من كل صوب، وألقوا عليه شبكتهم فوقع في حفرتهم،","19:9":"فساقوه بخزائم وزجوه في قفص وأحضروه إلى ملك بابل، واعتقلوه في قلاع لكيلا تتردد أصداء صوته بعد فوق جبال إسرائيل.","19:10":"أمك ككرمة مثلك غرست إلى جوار المياه، فأثمرت وأفرخت لغزار ة المياه.","19:11":"فروعها متينة تصلح صولجانا للمتسلطين، وانتصب ساقها عاليا بين الأغصان الكثيفة، فبدت شامخة للعيان بفضل أغصانها الكثيرة.","19:12":"لكنها اقتلعت بحنق وطرحت على الأرض، فيبست الريح الشرقية أثمارها، وقصفت فروعها القوية حتى جفت فالتهمتها النيران.","19:13":"وها هي الآن مغروسة في الصحراء، في أرض جدباء ظمأى.","19:14":"واندلعت نار من فرعها التهمت أغصانها وأثمارها، فلم يبق منها فرع متين يصلح لصولجان متسلط. هذه مرثية لتكون قصيدة رثاء».","20:1":"وفي اليوم العاشر من الشهر الخامس (أي تموز - يوليو) من السنة السابعة أقبل إلي بعض شيوخ إسرائيل ليستشيروا الرب، فجلسوا أمامي.","20:2":"فأوحى إلي الرب بكلمته قائلا:","20:3":"«ياابن آدم، قل لشيوخ إسرائيل: هذا ما يعلنه السيد الرب: هل جئتم لتستشيروني؟ حي أنا، لن أتيح لكم طلب المشورة مني.","20:4":"أتدينهم ياابن آدم؟ أتحاكمهم؟ أطلعهم على رجاسات آبائهم،","20:5":"وقل لهم: هذا ما يعلنه السيد الرب: في اليوم الذي اصطفيت فيه إسرائيل، وحلفت لذرية بيت يعقوب وأعلنت لهم عن نفسي في ديار مصر، حلفت لهم قائلا: أنا الرب إلهكم.","20:6":"في ذلك اليوم أقسمت لهم أن أخرجهم من ديار مصر إلى الأرض التي استكشفتها لهم والتي تفيض لبنا وعسلا، فخر كل الأراضي،","20:7":"وقلت لهم: لينبذ كل منكم الأرجاس التي تنجس عينيه، ولا تتدنسوا بأصنام مصر؛ أنا الرب إلهكم.","20:8":"ولكنهم تمردوا علي ولم يسمعوا لي، ولم يتركوا الأرجاس التي تنجس عيونهم، ولم يهجروا أصنام مصر. فقلت: سأسكب عليهم غضبي وأنفث فيهم كامل سخطي في وسط ديار مصر.","20:9":"غير أني تصرفت على غير ذلك إكراما لاسمي، لئلا يتنجس أمام عيون الأمم التي يسكن شعب إسرائيل بينها. إذ أعلنت نفسي أمام عيون الأمم حين أخرجت شعب إسرائيل من ديار مصر.","20:10":"وهكذا أخرجتهم من ديار مصر، وأتيت إلى البرية،","20:11":"وأعطيتهم فرائضي، وأعلنت لهم أحكامي التي إن مارسها إنسان يحيا بها،","20:12":"وأعطيتهم كذلك سبوتي لتكون علامة بيني وبينهم ليدركوا أني أنا الرب الذي أقدسهم.","20:13":"لكن شعب إسرائيل تمردوا علي في البرية ولم يمارسوا فرائضي، وتنكروا لأحكامي التي إن عمل بها إنسان يحيا، ونجسوا أيام سبوتي كثيرا. فقلت: سأسكب غضبي عليهم في البرية لأميتهم.","20:14":"لكنني تصرفت على غير ذلك إكراما لاسمي، لئلا يتنجس أمام عيون الأمم التي أخرجت شعب إسرائيل على مشهد منها.","20:15":"وحلفت لهم في البرية بأني لن أقودهم إلى الأرض التي وهبتها لهم، التي تفيض لبنا وعسلا، فخر الأراضي كلها،","20:16":"لأنهم تنكروا لأحكامي ولم يمارسوا فرائضي، بل دنسوا أيام سبوتي وضل قلبهم وراء أصنامهم.","20:17":"ولكن عيني ترَأفت عليهم فلم أهلكهم ولم أفنهم في البرية.","20:18":"وأوصيت أبناءهم في البرية ألا يسلكوا في طرق آبائهم ولا يمارسوا أعمالهم ولا يتنجسوا بأصنامهم.","20:19":"أنا الرب إلهكم فاسلكوا في فرائضي واحفظوا أحكامي واعملوا بها.","20:20":"وقدسوا سبوتي فتكون علامة بيني وبينكم لتعلموا أني أنا الرب إلهكم","20:21":"فتمرد الأبناء علي. لم يسلكوا في فرائضي ولم يحفظوا أحكامي ليعملوها التي إن عملها إنسان يحيا بها، ونجسوا سبوتي. فقلت إني أسكب غضبي عليهم لأتم سخطي عليهم في البرية.","20:22":"ولكني كففت يدي عنهم وتصرفت على غير ذلك إكراما لاسمي، لئلا يتنجس أمام عيون الأمم التي أخرجت شعب إسرائيل على مشهد منها.","20:23":"وحلفت لهم في البرية أن أفرقهم بين الأمم وأشتتهم عبر البلدان.","20:24":"لأنهم لم يطبقوا أحكامي بل تنكروا لفرائضي ودنسوا أيام سبوتي وتعلقت عيونهم بأصنام آبائهم.","20:25":"لذلك أعطيتهم فرائض غير صالحة وأحكاما لا يحيون بها.","20:26":"وجعلتهم يتنجسون بعطاياهم إذ أجازوا في النار كل بكر لأبيدهم، حتى يدركوا أني أنا الرب.","20:27":"لهذا، ياابن آدم، قل لشعب إسرائيل: بهذه الأمور جدف على آباؤكم إذ خانوناي أشد خيانة.","20:28":"عندما جئت بهم إلى الأرض التي أقسمت أن أهبها لهم، ورأوا كل أكمة مرتفعة وكل شجرة وارفة، فذبحوا قرابينهم هناك وقربوا ذبائحهم المغيظة، وأصعدوا تقدمات، روائح الرضى وسكبوا سكائب خمرهم،","20:29":"فسأ لتهم: ما هذه المرتفعةُ التي تأتون إليها؟ فدعيت مرتفعة إلى هذا اليوم.","20:30":"لذلك قل لشعب إسرائيل هذا ما يعلنه السيد الرب: هل دنستم أنفسكم كما فعل آباؤكم وغويتم وراء أصنامكم الرجسة؟","20:31":"إنكم تتنجسون مع كل أصنامكم إلى هذا اليوم، حين تقدمون عطاياكم للأوثان وتجيزون أبناءكم في النار . فهل بعد هذا تأتون إلي لطلب مشورتي ياشعب إسرائيل؟ حي أنا يقول السيد الرب، لن أتيح لكم طلب مشورتي.","20:32":"إذ لن يتحقق ما يخطر ببالكم إذ تقولون، لنكن كسائر قبائل الأرض فنعبد الخشب والحجر.","20:33":"حي أنا، يقول السيد الرب، إني بيد قوية وذراع قديرة وغضب مصبوب أملك عليكم،","20:34":"وأخرجكم من بين الشعوب وأجمعكم من البلدان التي تشتتم فيها، بيد قوية وذراع قديرة وغضب مصبوب،","20:35":"وآتي بكم إلى برية الأمم فأحاكمكم هناك مواجهة،","20:36":"وكما حاكمت أسلافكم في برية ديار مصر، أحاكمكم أنتم أيضا.","20:37":"وأحصيكم، وأدخلكم في ميثاق العهد،","20:38":"وأعزل من بينكم المتمردين والعصاة علي، وأخرجهم من أرض غربتهم، ولكنهم لن يدخلوا أرض إسرائيل، فتدركون آنئذ أني أنا الرب.","20:39":"أما أنتم ياشعب إسرائيل فامضوا وليعبد كل إنسان أصنامه، ولكن فيما بعد، ستستمعون حتما لي، ولن تدنسوا اسمي القدوس بعد بعطاياكم وأوثانكم.","20:40":"لأنه في جبل قدسي، جبل إسرائيل الشامخ، هناك يعبدوني في الأرض شعب إسرائيل كلهم. هناك أرضى عنهم وألتمس تقدماتكم وباكورة غلاتكم مع جميع مقدساتكم.","20:41":"وأرضى عنكم كرائحة سرور حين أخرجكم من بين الشعوب، وأجمعكم من البلدان التي تشتتم إليها، وأتجلى بقداستي بينكم على مشهد من الأمم.","20:42":"فتدركون أني أنا الرب حين أردكم إلى أرض إسرائيل، إلى الأرض التي أقسمت لآبائكم أن أهبها لهم.","20:43":"هناك تذكرون طرق شركم وأعمالكم التي تدنستم بها، وتمقتون أنفسكم من أجل ما ارتكبتموه من شرور.","20:44":"فتدركون أني أنا الرب حين أعاملكم، إكراما لاسمي، لا بمقتضى طرقكم الشريرة ولا بموجب أعمالكم السيئة ياشعب إسرائيل، يقول السيد الرب».","20:45":"وأوحى إلي الرب بكلمته قائلا:","20:46":"«ياابن آدم، التفت نحو الجنوب وأنذره، وتنبأ على أرض الغابات في النقب","20:47":"وقل لغابات النقب: اسمعوا قضاء الرب، فهذا ما يعلنه السيد الرب: ها أنا أضرم نارا فيك فتلتهم كل شجرة خضراء ويابسة، ولا ينطفيء لهيبها المتأجج، فتحترق بها كل الوجوه من الجنوب إلى الشمال.","20:48":"فيرى كل بشر أني أنا الرب الذي أضرمتها، ولا يمكن أن تنطفيء».","20:49":"عندئذ قلت: «آه ياسيد الرب: هم يقولون عني: أما يضرب هو أمثالا فقط؟»","21:1":"وأوحى إلي الرب بكلمته قائلا:","21:2":"«ياابن آدم: التفت نحو أورشليم وتنبأ على المقادس وعلى أرض إسرائيل","21:3":"وقل لأرض إسرائيل: هذا ما يعلنه الرب، ها أنا أنقلب عليك وأستل سيفي من غمده فأستأصل منك الصالح والطالح.","21:4":"لذلك يخرج سيفي من غمده فيقضي على كل إنسان من الجنوب إلى الشمال.","21:5":"فيدرك كل بشر أني أنا الرب، سللت سيفي من غمده ولن يرتد إليه.","21:6":"أما أنت ياابن آدم، فتنهد بقلب منكسر وحزن مرير أمامهم","21:7":"فإن سألوك: على ماذا تتنهد؟ تجبهم: على الأخبار الواردة التي تذيب كل قلب، فتسترخي الأيدي ويعتري القنوط كل روح، وتصبح الركب كالماء. ها هي الأخبار واردة ولابد أن تتم، يقول السيد الرب».","21:8":"وأوحى إلي الرب بكلمته قائلا:","21:9":"«ياا بن آدم، تنبأ وقل: هذا ما يعلنه الرب: سيف، سيف قد تم سنه وصقله أيضا.","21:10":"قد سن للذبح المبرم، وصقل ليومض بالبريق فهل نغتبط (قائلين): عصا ابني تحتقر كل قضيب؟","21:11":"قد أعطي السيف ليصقل ويجرد بالكف، وها هو بعد سنه وصقله يسلم ليد القاتل.","21:12":"اصرخ وأعول ياابن آدم لأنه يتسلط على شعبي وعلى كل رؤساء إسرائيل؛ يتعرض شعبي لأهوال من جراء هذا السيف، لذلك اضرب على صدرك فزعا.","21:13":"لأن الامتحان قد أعد وماذا يحدث إن لم تقبل هذه العصا المحتقرة؟ يقول السيد الرب.","21:14":"فتنبأ ياابن آدم، واصفق كفا على كف، وليضرب السيف مرتين، بل ثلاث مرات. إنه سيف القتلى، سيف المجزرة العظيمة المحدقة بهم،","21:15":"لكي تذوب القلوب، فيتهاوى كثيرون صرعى عند كل بواباتهم. لهذا جردت سيفا متقلبا براقا مصقولا متأهبا للذبح.","21:16":"فياسيف اجرح يمينا، اجرح شمالا، اجرح كيفما توجه حدك.","21:17":"وأنا أيضا أصفق بكفي وأهديء سورة غضبي، أنا الرب تكلمت».","21:18":"وأوحى إلي الرب بكلمته قائلا:","21:19":"«أما أنت ياابن آدم، فخطط طريقين لزحف سيف ملك بابل. من أرض واحدة تخرج الطريقان، وأقم معلما عند ناصية الطريق المفضية إلى المدينة.","21:20":"خطط طريقا يسلكه السيف على ربة عمون وعلى يهوذا في أورشليم الحصينة،","21:21":"لأن ملك بابل قد توقف عند مفرق الطريقين على الناصية، يلتمس عرافة، فضرب بالسهام، وطلب مشورة أصنام أسلافه، ونظر إلى الكبد.","21:22":"فعن يمينه ألقيت قرعة على أورشليم لإقامة المجانق، وإصدار الأوامر بالقتل، وإطلاق هتاف الحرب، لنصب المجانق على الأبواب، لإقامة مترسة لبناء برج.","21:23":"ولكنها تبدو لمن أقسم بالولاء للكلدانيين أنها عرافة كاذبة، ولكن ملك بابل يتذكر نكثهم للعهد فيؤخذون به.","21:24":"لذلك، هذا ما يعلنه السيد الرب: لأنكم ذكرتم بإثمكم، إذ انكشف تمردكم، فتجلت خطاياكم في كل ما ارتكبتموه من أعمال، لهذا إذ ذكرتم بأنفسكم يقبض عليكم باليد.","21:25":"وأنت أيها المطعون الأثيم، ملك إسرائيل، يامن أزف يومه في ساعة العقاب النهائي","21:26":"اخلع العمامة، وانزع التاج، فلن يبقى الحال كسالف العهد به، ارفع الوضيع، وضع الرفيع.","21:27":"ها أنا أقلبه، أقلبه، أقلبه، حتى لا يبقى منه أثر، إلى أن يأتي صاحب الحكم، فأعطيه إياه.","21:28":"أما أنت ياابن آدم، فتنبأ وقل هذا ما يقضي به الرب على بني عمون وعلى تعييرهم: ها سيف، سيف مسلول للذبح، مصقول للالتهام يومض كالبرق.","21:29":"فبينما يرون لك رؤى باطلة، وينطقون لك بعرافة كاذبة يطر حك (السيف) كي تلقى حتفك فوق جثث القتلى الأشرار الذين حان يومهم في ساعة العقاب النهائي.","21:30":"أعده إلى غمده. ففي الموضع الذي خلقت فيه يامملكة عمون، في أرض مولدك، أحاكمك.","21:31":"وأصب عليك غضبي، وأنفخ عليك بنار غيظي وأسلمك لقبضة رجال أفظاظ متمرسين في التدمير.","21:32":"فتكونين وقودا للنار، ويهطل دمك في وسط الأرض، ولا تذكرين فيما بعد لأني أنا الرب تكلمت».","22:1":"وأوحى إلي الرب بكلمته قائلا:","22:2":"«وأنت ياابن آدم، أتدين المدينة السافكة الدماء؟ إذا عرفها بكل رجاساتها،","22:3":"وقل: هذا ما يعلنه السيد الرب: أيتها المدينة التي تسفك الدماء في وسطها لتستجلب العقاب على نفسها، التي تصنع لنفسها أصناما تتنجس بها.","22:4":"قد أثمت بما سفكت من دماء، وتنجست بما عملت من أصنامك. قد قربت يوم دينونتك، وبلغت منتهى أيامك، لذلك جعلتك عارا عند الأمم ومثار سخرية لجميع البلدان.","22:5":"تسخر منك البلدان القريبة والنائية على حد سواء، أنت يانجسة، ياكثيرة الشغب.","22:6":"هوذا كل واحد من رؤساء إسرائيل ممن كانوا فيك انهمك في سفك الدماء على قدر طاقته.","22:7":"فيك استخفوا بأب وأم وجاروا في وسطك على الغريب، واضطهدوا اليتيم والأرملة،","22:8":"احتقرت مقدساتي ونجست أيام سبوتي.","22:9":"أقام فيك وشاة عملوا على سفك الدم، وأكلوا أمام الأصنام على الجبال، وارتكبوا في وسطك الموبقات.","22:10":"فيك فضح الإنسان عري أبيه، وفيك أذلوا من برحت متنجسة بطمثها.","22:11":"فيك إنسان زنى مع امرأة قريبه، واقترف إنسان الرذيلة مع كنته، وفيك ضاجع إنسان أخته ابنة أبيه.","22:12":"فيك أخذوا الرشوة لقاء سفك الدماء. أخذت الربا ومال الحرام، وسلبت أقرباءك ظلما ونسيتني، يقول السيد الرب.","22:13":"ها أنا قد صفقت بكفي من جراء ما حصلت عليه من ربح حرام، وما سفك من دم في وسطك.","22:14":"فهل يصمد قلبك أو تحتفظ يداك بقوتهما في الأيام التي فيها أتعامل معك؟ أنا الرب قد تكلمت وأتمم ما أنطق به.","22:15":"سأشتتك بين الأمم، وأبعثرك في البلدان، وأزيل نجاستك منك.","22:16":"وتتدنسين بنفسك أمام عيون الأمم، وتدركين أني أنا الرب».","22:17":"وأوحى إلي الرب بكلمته قائلا:","22:18":"«ياابن آدم، قد أصبح شعب إسرائيل لي نفاية. كلهم مثل النحاس والقصدير والحديد والرصاص في كور. صاروا حثالة فضة.","22:19":"لأجل ذلك هذا ما يعلنه السيد الرب: لأنكم كلكم قد صرتم نفاية، فها أنا أجمعكم في وسط أورشليم،","22:20":"كما تجمع الفضة والنحاس والحديد والرصاص والقصدير في الكور، لتنفخ عليها نار لتسبك. كذلك أجمعكم في غضبي وسخطي وأطرحكم وأسبككم.","22:21":"أجمعكم وأنفخ عليكم في نار غضبي فتسبكون فيها","22:22":"كما تسبك الفضة في بوتقة النار، هكذا تسبكون فيها، فتدركون أني أنا الرب قد سكبت سخطي عليكم».","22:23":"وأوحى إلي الرب بكلمته قائلا:","22:24":"«ياابن آدم، تنبأ وقل لها: أنت أرض لم تتطهري ولم يمطر عليها في يوم الغضب.","22:25":"تواطأ أنبياؤها الكذبة فيها مثل أسد مزمجر يمزق الفريسة. التهموا نفوسا، واستولوا على نفائس الناس وكنوزهم، وكثروا أراملها فيها.","22:26":"خالف كهنتها شريعتي ونجسوا مقادسي. لم يميزوا بين المقدس والرجس، ولم يعلموا الفرق بين الطاهر والنجس، وحجبوا عيونهم عن أيام سبوتي فصرت مدنسا في وسطهم.","22:27":"رؤساؤها فيها كذئاب خاطفة تمزق فرائسها إذ يسفكون دماء الناس في سبيل الربح الحرام.","22:28":"وأنبياؤها قد طلوا لهم بماء الكلس، إذ يرون لهم رؤى باطلة، ويعرفون لهم عرافة كاذبة قائلين: هذا ما يعلنه السيد الرب، مع أن الرب لم يعلن شيئا.","22:29":"أفرطوا في ظلم شعب الأرض واغتصبوا سالبين، واضطهدوا الفقير والمسكين، وظلموا الغريب جورا.","22:30":"فالتمست من بينهم رجلا واحدا يبني جدارا ويقف في الثغرة أمامي مدافعا عن الأرض، حتى لا أخربها فلم أجد.","22:31":"فصببت سخطي عليهم، التهمتهم بنار غضبي، جازيتهم بحسب طرقهم، يقول السيد الرب».","23:1":"وأوحى إلي الرب بكلمته قائلا:","23:2":"«ياابن آدم، كانت هناك امرأتان، ابنتا أم واحدة،","23:3":"زنتا في صباهما في مصر حيث دوعبت ثديهما، وعبث بترائب عذرتهما.","23:4":"اسم الكبرى أهولة واسم أختها أهوليبة، وكانتا لي وأنجبتا أبناء وبنات، أما السامرة فهي أهولة، وأورشليم هي أهوليبة.","23:5":"وزنت أهولة مع أنها كانت لي، وعشقت محبيها الأشوريين الأبطال.","23:6":"اللابسين في الأردية الأرجوانية من ولاة وقادة. وكلهم شبان شهوة، وفرسان خيل.","23:7":"فأغدقت على نخبة أبناء أشور زناها، وتنجست بكل من عشقتهم وبكل أصنامهم.","23:8":"ولم تتخل عن زناها منذ أيام مصر لأنهم ضاجعوها منذ حداثتها، وعبثوا بترائب عذرتها وسكبوا عليها شهواتهم،","23:9":"لذلك سلمتها ليد عشاقها أبناء أشور الذين أولعت بهم.","23:10":"ففضحوا عورتها، وأسروا أبناءها وبناتها، وذبحوها بالسيف، فصارت عبرة للنساء ونفذوا فيها قضاء.","23:11":"ومع أن أختها أهوليبة شهدت هذا، فإنها أوغلت أكثر منها في عشقها وزناها،","23:12":"إذ عشقت أبناء أشور من ولاة وقادة المرتدين أفخر اللباس، فرسان خيل وجميعهم شبان شهوة.","23:13":"فرأيت أنها قد تنجست، وسلكتا كلتاهما في ذات الطريق.","23:14":"غير أن أهوليبة تفوقت في زناها، إذ حين نظرت إلى صور رجال الكلدانيين المرسومة على الحائط بالمغرة،","23:15":"متحزمين بمناطق على خصورهم، وعمائمهم مسدولة على رؤوسهم، وكلهم بدوا كرؤساء مركبات مماثلين تماما لأبناء الكلدانيين في بابل أرض ميلادهم،","23:16":"عشقتهم وبعثت إليهم رسلا إلى أرض الكلدانيين.","23:17":"فأقبل إليها أبناء بابل وعاشروها في مضجع الحب ونجسوها بزناهم. وبعد أن تنجست بهم كرهتهم.","23:18":"وإذ واظبت على زناها علانية، وتباهت بعرض عريها، كرهتها كما كرهت أختها.","23:19":"ومع ذلك أكثرت من فحشها، ذاكرة أيام حداثتها حيث زنت في ديار مصر.","23:20":"فأولعت بعشاقها هناك، الذين عورتهم كعور ة الحمير ومنيهم كمني الخيل.","23:21":"وتقت إلى فجور حداثتك حين كان المصريون يداعبون ترائب عذرتك طمعا في نهد حداثتك.","23:22":"لذلك ياأهوليبة، هذا ما يعلنه السيد الرب: ها أنا أثير عليك عشاقك الذين جفتهم نفسك، وآتي بهم عليك من كل ناحية.","23:23":"أبناء البابليين، وسائر الكلدانيين من أقوام فقود وشوع وقوع ومعهم جميع أبناء أشور، شبان شهوة، من ولاة وقادة ورؤساء مركبات وذوي الشهرة، وكلهم فرسان خيل.","23:24":"فيهاجمونك بأسلحة ومركبات وعربات وأقوام شعوب ويحاصرونك بترس ومجن وخوذة. وأعهد إليهم بمقاضاتك فيحكمون عليك بمقتضى أحكامهم.","23:25":"وأصب سخطي عليك فيعاملونك بغيظ. يجدعون أنفك وأذنيك، وتقتل بقيتك بالسيف. يأسرون أبناءك وبناتك، وتلتهم النار بقيتك،","23:26":"ويجردونك من ثيابك ويستولون على حليك.","23:27":"وهكذا أضع حدا لعهرك وزناك اللذين شرعت فيهما في أرض مصر، فلا تعودين تتعلقين بهم، أو تذكرين مصر بعد.","23:28":"ها أنا أسلمك إلى يد الذين كرهتهم وإلى أيدي الذين جفتهم نفسك.","23:29":"فيعاملونك ببغض ويستولون على كل ثمار تعبك، ويتركونك متجردة عارية، فتنفضح عورة زناك وعهرك.","23:30":"وأوقع بك هذه الأمور لأنك ضللت وراء الأمم، وتنجست بعبادة أصنامهم،","23:31":"وسلكت في أثر أختك، لهذا أجرعك كأسها","23:32":"وهذا ما يعلنه السيد الرب: ستشربين كأس عقاب أختك العميقة، وتكونين مثار ضحك واستهزاء. لأن الكأس تسع كثيرا.","23:33":"تمتلئين سكرا وحزنا، فكأس أختك السامرة، كأس الرعب والخراب،","23:34":"تشربينها وتمتصينها، ثم تقضمين قطعها، وتجتثين نهديك لأني تكلمت، يقول السيد الرب.","23:35":"لأنك نسيتني ونبذتني وراء ظهرك، تحملي عواقب عهرك وزناك».","23:36":"وقال الرب لي: «ياابن آدم، أتدين أهولة وأهوليبة؟ إذن أطلعهما على ما ارتكبتاه من رجس،","23:37":"لأنهما قد زنتا وسفكتا دماء، فقد زنتا بعبادة أصنامهما وأجازتا أبناءهما الذين أنجبتاهم في النار، ليكونوا وقودا لها.","23:38":"وأثمتا في حقي إذ أنهما في ذلك اليوم نجستا مقدساتي ودنستا أيام سبوتي.","23:39":"وبعد أن ذبحتا أبناءهما قرابين لأصنامهما قدمتا في ذلك اليوم إلى مقدسي لتنجساه. فانظر! هذا ما ارتكبتاه في هيكلي.","23:40":"بل استدعيتما رجالا قادمين من بعيد، بعد أن أرسلتما إليهم رسولا، وها هم قد أقبلوا، ومن أجلهم استحممت وكحلت عينيك وتز ينت بالحلي.","23:41":"وتربعت على سرير فاخر، بسطت أمامه مائدة منضضة وضعت عليها بخوري وزيتي.","23:42":"وأحاطت بها جلبة قوم لاهين، واستجلب من البرية سكارى مع أناس من رعاع الخلق، زينوا أيدي المذنبتين بأسورة، ووضعوا على رأسيهما تاج جمال.","23:43":"فقلت عن العريقة في الزنا: الآن يزنون معها وهي معهم،","23:44":"لأنهم تهافتوا عليها كما يتهافت على امرأة زانية. هكذا تهافتوا على أهولة وأهوليبة المرأتين العاهرتين.","23:45":"ولكن سيدينهما الرجال الصديقون، فيصدرون عليهما حكم الزانية وحكم سافكة الدم، لأنهما عاهرتان تلطخت أيديهما بالدم.","23:46":"لأن هذا ما يعلنه السيد الرب: ها أنا أجلب عليهما قوما من الأعداء، وأوقع بهما الرعب والنهب،","23:47":"فيرجمهما القوم بالحجارة، ويمزقونهما بالسيوف ويذبحون أبناءهما وبناتهما، ويحرقون بيوتهما بالنار.","23:48":"فأضع حدا للرذيلة في الأرض، فتعتبر جميع النساء ولا يرتكبن الفحشاء كما فعلتما.","23:49":"وتلقيان جزاء زناكما وتحملان خطايا عبادة أصنامكما، وتدركان أني أنا السيد الرب».","24:1":"وفي اليوم العاشر من الشهر العاشر في السنة التاسعة (من أسر الملك يهوياقيم)، أوحى الرب إلي بكلمته قائلا:","24:2":"«ياابن آدم، دون اسم هذا اليوم بعينه، فإن ملك بابل قد حاصر فيه أورشليم.","24:3":"واضرب مثلا للشعب المتمر د وقل لهم: هذا ما يعلنه السيد الرب: ضع القدر وصب فيها ماء.","24:4":"واطرح فيها قطع الذبيحة، كل قطعة طيبة، الفخذ والكتف وخيار العظام.","24:5":"لتكن الذبيحة منتقاة من خيار الغنم، وضعها فوق كومة العظام. أغلها جيدا حتى تسلق عظامها فيها.","24:6":"لأن هذا ما يعلنه السيد الرب: ويل للمدينة سافكة الدماء، وللقدر المغشاة بزنجارها الذي لا يخرج منها. فرغوها قطعة قطعة من غير اقتراع عليها.","24:7":"لأن دمها ما برح فيها، قد وضعته على صخرة جرداء، لم ترقه على الأرض لتواريه بالتراب","24:8":"وحتى تثير الغضب المفضي إلى الانتقام وضعت دمها على صخرة جرداء لئلا يوارى.","24:9":"لذلك ويل للمدينة سافكة الدماء، فإني أنا أجعل كومة حطبها عظيمة.","24:10":"كثر الحطب، أضرم النار، أنضج اللحم وضع عليه التوابل ولتحرق العظام.","24:11":"ثم ضع القدر فارغة على الجمر حتى تحمى ويتوهج نحاسها، فيذوب قذرها ويفنى زنجارها.","24:12":"قد أجهدت نفسي بمتاعبها ولم تتطهر من كثرة زنجارها فصار مآله للنار.","24:13":"في قذارتك رذيلة لأني سعيت لتطهيرك، فلم تطهري ولن تطهري من نجاستك حتى أصب عليك غضبي.","24:14":"أنا الرب قد تكلمت، وما قضيت به لابد أن يتم. لن أرجع عنه ولن أشفق ولن أندم، بل يحكمون عليك بمقتضى تصرفاتك وطرقك، يقول السيد الرب».","24:15":"وأوحى إلي الرب بكلمته قائلا:","24:16":"«ياابن آدم، ها أنا أحرمك من بهجة عينيك (أي زوجته) على أثر فاجعة. فلا تنح ولا تبك ولا تذرف دموعك.","24:17":"تنهد بصمت. لا تقم مناحة على الموتى. تلفع بعصابتك وضع نعليك في رجليك. لا تحجب شاربيك ولا تأكل من خبز الناس».","24:18":"فخاطبت الشعب في الصباح، وعند المساء توفيت زوجتي، ففعلت في اليوم التالي ما أمرت به.","24:19":"فسألني الشعب: «ألا تخبرنا ما تعنيه لنا هذه الأمور التي أنت تصنعها؟»","24:20":"فأجبتهم: «قد أوحى إلي الرب بكلامه قائلا:","24:21":"أبلغ شعب إسرائيل: ها أنا مزمع على تنجيس مقدسي فخر عزكم ومشتهى أعينكم، وبهجة نفوسكم، فيتهاوى أبناؤكم وبناتكم الذين خلفتهم وراءكم صرعى بالسيف.","24:22":"وتفعلون كما فعلت: لا تحجبون شواربكم ولا تأكلون من خبز الناس،","24:23":"وتكون عصائبكم على رؤوسكم، ونعالكم في أرجلكم. لا تنوحون ولا تندبون إنما تبيدون بآثامكم، ويئن بعضكم على بعض.","24:24":"وهكذا يصبح حزقيال لكم آية: فتصنعون كما صنع. فإن تم هذا تدركون أني أنا السيد الرب.","24:25":"أما أنت ياابن آدم، ففي اليوم الذي أحرمهم فيه من عزهم وبهجة فخرهم، ومشتهى عيونهم، ولذة قلوبهم (أي أبنائهم وبناتهم)،","24:26":"يقبل إليك الناجي في ذلك اليوم ليبلغك هذه الأخبار.","24:27":"في ذلك اليوم ينفتح فمك فتخاطب الناجي المنفلت ولا تكون بعد أبكم، وتكون لهم آية، فيدركون أني أنا الرب».","25:1":"وأوحى إلي الرب بكلمته قائلا:","25:2":"«ياابن آدم، التفت بوجهك نحو بني عمون وتنبأ عليهم.","25:3":"وقل لهم اسمعوا ما يعلنه السيد الرب من قضاء: لأنك شمت بمقدسي لأنه تدنس، وبأرض إسرائيل لأنها خربت وبشعب يهوذا لأنهم سيقوا إلى السبي،","25:4":"أسلمك للبدو وأبناء المشرق، فتصيرين ملكا لهم فينصبون مضاربهم فيك، ويقيمون مساكنهم فوق أرضك. هم يلتهمون غلتك، ويشربون لبنك.","25:5":"وأجعل مدينة ربة مناخا للإبل، وسائر مدن بني عمون مرابض للغنم، فتدركون أني أنا الرب.","25:6":"لأنك صفقت بكفيك طربا، وخبطت برجليك، وفرحت بكل ما فيك من لؤم لما حل بأرض إسرائيل.","25:7":"لذلك ها أنا أثقل يدي عليك، وأسلمك غنيمة للأمم، وأستأصلك من بين الشعوب، وأفنيك من بين البلدان، وأدمرك، فتدرك أني أنا الرب.","25:8":"وهذا ما يعلنه السيد الرب: لأن الموآبيين وأهل سعير يقولون: هل شعب يهوذا كبقية الأمم.","25:9":"لذلك ها أنا أقوض جبهتهم الشرقية، وأدمر مدن حدودهم، بيت بشيموت وبعل معون وقريتايم وهي مدن مفخرة موآب.","25:10":"فيستولى قبائل البدو عليها، ويصير بنو عمون ملكا لهم فلا يعود لهم ذكر بين الأمم.","25:11":"وأنفذ في الموآبيين أحكاما، فيدركون أني أنا الرب.","25:12":"وهذا أيضا ما يعلنه السيد الرب: لأن الأدوميين أقدموا على الانتقام من شعب يهوذا، وأساءوا إليه أشد إساءة.","25:13":"ها أنا أعاقب الأدوميين وأستأصل من أرضهم الإنسان والحيوان، وأحولها إلى أطلال دارسة من التيمن إلى ددان، إذ يقتل أهلها جميعا بالسيف.","25:14":"وأعهد بنقمتي إلى شعبي إسرائيل، فيفعلون بالأدوميين بمقتضى غضبي وسخطي، فيدركون شدة نقمتي، يقول السيد الرب.","25:15":"وهذا أيضا ما يعلنه السيد الرب لأن الفلسطينيين قد أقدموا على الانتقام وأفرطوا فيه بكل لؤم قلوبهم، عامدين إلى الخراب بسبب عداوة أبدية،","25:16":"ها أنا أعاقب الفلسطينيين وأستأصل الكريتيين، وأبيد بقية سكان ساحل البحر،","25:17":"وأنفذ فيهم انتقامي العظيم بتأديب مفعم بالسخط، فيدركون أني أنا الرب، إذ أصب نقمتي عليهم».","26:1":"وفي السنة الحادية عشرة (من سبي الملك يهوياكين)، في اليوم الأول من الشهر، أوحى إلي الرب بكلمته قائلا:","26:2":"«ياابن آدم، لأن صور قد شمتت بأورشليم، وقالت: ها بوابة الشعوب قد انهارت، وتحولت القوافل إلي. ها أنا أزدهر إذ حل بها الدمار.","26:3":"لذلك يعلن السيد الرب: ها أنا أعاقبك ياصور، فأجعل أمما كثيرة تهاجمك كما يهجم البحر بأمواجه.","26:4":"فيهدمون أسوار صور وأبراجها، وأكشط ترابها عنها، وأحولها إلى صخرة جرداء.","26:5":"فتصبح منشرا للشباك في وسط البحر لأني أنا قضيت، يقول السيد الرب، ثم تغدو غنيمة للأمم.","26:6":"وتهلك ضواحيها الريفية بالسيف، فيدركون أني أنا الرب.","26:7":"لأن هذا ما يعلنه السيد الرب: ها أنا آتي بملك الملوك، نبوخذناصر ملك بابل من الشمال بخيل وبمركبات وبفرسان وأقوام غفيرة،","26:8":"فيبيد بالسيف قرى ريفك ويشيد حولك سور حصار، ويبني عليك أبراجا، ويقيم مترسة، ويهاجمك بترس.","26:9":"ويقذف أسوارك بمجانق، ويهدم أبراجك بعدة حربه.","26:10":"ولكثرة خيله يحجبك غبار حوافرها، وتتزلزل أسوارك من صوت الفرسان والعربات والمركبات عند اقتحامه أبوابك كما تقتحم مدينة مثغورة،","26:11":"فيدوس بحوافر خيله كل شوارعك، ويقضي بالسيف على شعبك، فتتهاوى إلى الأرض أركان عزك،","26:12":"وينهبون ثروتك، ويستولون على تجارتك ويهدمون أسوارك وبيوتك المبهجة، ويطرحون حجارتك وخشبك وترابك إلى مياه البحر.","26:13":"وأخرس أهازيج أغانيك، ولا تتردد بعد رنات أعوادك،","26:14":"وأجعلك كصخرة جرداء، فتكونين منشرا للشباك، ولا تعمرين في ما بعد. لأني أنا الرب قضيت يقول السيد الرب.","26:15":"وهذا ما يعلنه السيد الرب عن مدينة صور: ألا ترتعد مدن السواحل لجلبة سقوطك، ولصراخ الجرحى، ولوقوع القتل فيك،","26:16":"فينزل جميع رؤساء المدن الساحلية عن عروشهم ويخلعون جببهم ويطرحون عنهم أرديتهم المزركشة، ويكتسون الرعب ثوبا، ويجلسون على الأرض مرتجفين في كل لحظة، مذعورين لما أصابك","26:17":"عندئذ ينوحون عليك بمرثاة قائلين: كيف تلاشيت من بين البحار أيتها المدينة العامرة الشهيرة، التي كانت مسيطرة هي وسكانها على البحر، فألقوا رعبهم على جميع جيرانها.","26:18":"الآن ترتعد مدن السواحل في وقت سقوطك، وتضطرب الجزائر في وسط البحر لانهيارك،","26:19":"إذ أحولك إلى مدينة خربة كالمدن المقفرة. أطغي عليك لجج البحر وأغمرك بالمياه الكثيرة،","26:20":"وأحدرك مع الهابطين إلى الهاوية، إلى الشعب القديم، وأجعلك تقيمين في أسافل الأرض في الخرب الدائرة لتظلي مقفرة، فلا يكون لك مكان في أرض الأحياء،","26:21":"وأجلب الرعب عليك فلا يبقى منك أثر وإذ يبحث عنك لا يعثر عليك أبدا، يقول السيد الرب».","27:1":"وأوحى إلي الرب بكلمته قائلا:","27:2":"«وأما أنت ياابن آدم، فاندب صور بمرثاة،","27:3":"وقل لصور القائمة عند مداخل البحر، تاجرة الشعوب، القاطنة في مدن السواحل: ياصور أنت قلت: أنا كاملة الجمال.","27:4":"تخومك في قلب البحار، وبناؤوك أكملوا جمالك،","27:5":"صنعوا كل ألواحك من سرو سنير، وأخذوا أرزا من لبنان ليعملوا لك سواري.","27:6":"من بلوط باشان صنعوا مجاذيفك، وطعموا مقاعدك بالعاج المستجلب من سواحل قبرص.","27:7":"نصبوا شراعك من كتان مطرز من مصر ليكون لك راية. وكانت مظلتك من قماش أزرق وأرجواني من جزائر أليشة.","27:8":"كان أهل صيدون وإرواد ملاحيك، وحكماؤك المهرة ياصور الذين كانوا فيك هم ربابينك،","27:9":"شيوخ جبيل وصناعها المهرة الذين كانوا فيك هم قلافوك الذين يسدون شقوقك. جميع سفن البحر وملاحوها قدموا إليك للمتاجرة معك.","27:10":"أقوام من فارس ولود وفوط انخرطوا في جيشك وكانوا من رجال حربك. علقوا على أسوارك أتراسا وخوذا، وخلعوا عليك بهاءك.","27:11":"أبناء إرواد مع جيشك قائمون على أسوارك المحيطة بك، وتمنعت أبراجك برجال أبطال، علقوا أتراسهم على أسوارك المحيطة بك، وأكملوا جمالك.","27:12":"ترشيش تاجرت معك لكثرة ما فيك من أنواع الغنى، فدفعت فضة وحديدا وقصديرا ورصاصا لقاء بضائعك.","27:13":"تاجرت معك اليونان وتوبال وماشك، فقايضوا بضائعك بالرقيق وآنية النحاس،","27:14":"وقايض أهل بيت توجرمة بضائعك بالخيل والفرسان والبغال.","27:15":"تاجر معك أهل رودس، ومدن ساحلية كثيرة كانت مراكز أسواقك، فدفعوا لك قرون العاج والآبنوس.","27:16":"أدوم تاجرت معك، فقايضوا بضائعك في أسواقك بحجارة البهرمان والأرجوان، والقماش المطرز والبوص والمرجان والياقوت،","27:17":"وتاجرت معك أرض يهوذا وإسرائيل، فقايضوا بضائعك بالحنطة والزيتون وأوائل التين والعسل والزيت والبلسان.","27:18":"دمشق تاجرت معك لكثرة بضائعك وفرط غناك، فقايضت بضائعك بخمرة حلبون والصوف الأبيض.","27:19":"وقايض أهل دان واليونان بضائعك بخمرة أوزال والحديد المشغول والقرفة الصينية وقصب الذريرة.","27:20":"وقايضت رودس بضائعك بأغطية السروج.","27:21":"وتاجر معك العرب وكل رؤساء قيدار، فقايضوا بضائعك بالخرفان والكباش والأعتدة.","27:22":"وتاجر معك أيضا تجار شبا ورعمة، فقايضوا بضائعك بأفخر أنواع الطيب والحجارة الكريمة والذهب.","27:23":"ومن المتاجرين معك أيضا أهل حران وكنة وعدن وشبا، وأشور وكلمد.","27:24":"هؤلاء قايضوا بضائعك بنفائس الأردية الأسمانجونية والمطرزة، وبسجاجيد ملونة مبرومة الخيطان ومضفورة بإحكام.","27:25":"وكانت سفن ترشيش قوافلك البحرية المحملة بتجارتك، فامتلأت وتعظمت جدا في عرض البحار.","27:26":"أبحر بك ملاحوك إلى لجج المياه حيث جعلتك الريح الشرقية حطاما في قلب البحار.","27:27":"غرقت ثروتك وأسواقك وبضاعتك وملاحوك وربابينك وقلافوك والمتاجرون بمنتوجاتك في أعماق البحر في يوم سقوطك.","27:28":"ترتعش مسارح القطعان من صوت صراخ ربابينك.","27:29":"يهجر كل المجذفين والملاحين وربابنة البحر سفنهم ويقفون على البر.","27:30":"يرفعون صوتهم بالنواح عليك ويصرخون بمرارة، ويذرون ترابا فوق رؤوسهم، ويتمرغون في الرماد.","27:31":"يحلقون شعر رؤوسهم عليك، ويرتدون المسوح، ويندبونك بمرارة نفس ندبا أليما.","27:32":"وفي ندبهم يقيمون عليك مناحة، ويرثونك قائلين: أية مدينة عمها الصمت مثل صور في قلب البحار؟","27:33":"عند وصول بضائعك عبر البحار أشبعت أمما كثيرة، وأغنيت ملوك الأرض بكثرة ثروتك وتجارتك.","27:34":"ولكن حين أغرقتك العواصف في أعماق المياه، غرق معك ملاحوك وتجارتك.","27:35":"فاعترى الذعر عليك كل سكان المدن الساحلية، واقشعر ملوكهم رعبا، واضطربت وجوههم.","27:36":"يصفر تجار الشعوب دهشة عليك لما حل بك من مصير رهيب، ولن يبقى بعد منك أثر».","28:1":"وأوحى إلي الرب بكلمته قائلا:","28:2":"«ياابن آدم، قل لملك صور، هذا ما يعلنه السيد الرب: لأنك تكبرت وقلت: «أنا إله، وأتربع في مجلس الآلهة، في قلب البحار»؛ مع أنك إنسان ولست إلها، وإن ظننت أن لديك حكمة الآلهة!","28:3":"ها أنت أحكم من دانيآل ولا يخفى عليك سر.","28:4":"قد استحوذت بحكمتك وفهمك على الذهب والفضة وادخرتها في خزائنك،","28:5":"وبمهارتك العظيمة في التجارة ضاعفت ثروتك، فتكبر قلبك لفرط غناك.","28:6":"لذلك يقول السيد الرب: لأنك ظننت أن لديك حكمة الآلهة،","28:7":"ها أنا أثير عليك غرباء من أعتى الأمم، فيجردون سيوفهم على بهاء حكمتك، ويدنسون جمالك.","28:8":"يطر حونك إلى الهاوية فتموت موت القتلى في أعماق البحار.","28:9":"أتظل تقول أنئذ أمام قاتلك: أنا إله؟ أنت إنسان لا إله في قبضة ذابحيك.","28:10":"فتلقى حتفك كالغلف بيد الغرباء، لأني أنا قضيت يقول السيد الرب».","28:11":"وأوحى إلي الرب بكلمته قائلا:","28:12":"«ياابن آدم، اندب ملك صور بمرثاة وقل له هذا ما يعلنه السيد الرب: كنت خاتم الكمال، مفعما بالحكمة وكامل الجمال.","28:13":"كنت في جنة الله عدن، حجابك كل حجر كريم: عقيق أحمر وياقوت أصفر وعقيق أبيض وزبرجد وجزع ويشب وياقوت أزرق وبهرمان وزمرد وذهب. صاغوا منه بيوت حجارتك الكريمة وترصيعاتك يوم خلقت.","28:14":"ومسحتك لتكون الكروبيم المظلل وأقمتك على جبل الله المقدس، وتمشيت بين حجار ة النار.","28:15":"كنت كاملا في طرقك منذ يوم خلقت إلى أن وجد فيك إثم.","28:16":"إنما بسبب كثرة تجارتك امتلأ داخلك ظلما، فأخطأت. لهذا أطرحك من جبل الله كشيء نجس، وأبيدك أيها الكروب المظلل من بين حجارة النار.","28:17":"قد تكبر قلبك بسبب بهائك، وأفسدت حكمتك من جراء جلالك. سألقي بك إلى الأرض أمام الملوك لتكون عرضة لعيونهم الهازئة.","28:18":"قد نجست مقادسك بفرط آثامك وتجارتك الظالمة. لذلك أجعل النار تندلع من وسطك فتلتهمك، وأحولك إلى رماد على الأرض أمام كل من يراك.","28:19":"فيتحير لما أصابك جميع الذين يعرفونك بين الشعوب، إذ تحل بك الأهوال ولا يبقى منك أثر».","28:20":"وأوحى إلي الرب بكلمته قائلا:","28:21":"«ياابن آدم، التفت بوجهك نحو صيدون وتنبأ عليها.","28:22":"وقل هذا ما يعلنه السيد الرب: ها أنا أنقلب عليك ياصيدون وأتجلى بمجدي فيك فيدرك سكانك أني أنا الرب حين أنفذ فيك أحكاما وأتقدس في وسطك.","28:23":"أجعل الوبأ يتفشى فيك وتسفك دماء في أزقتك، ويتساقط في وسطك جرحى السيف الذي يحدق بك من كل ناحية، فيدركون أني أنا الرب.","28:24":"فلا يتعرض شعب إسرائيل إلى وخزات العليق ولا إلى شوكة مؤذية من الأمم المحيطة بهم ممن تبغضهم، فيدركون أني أنا السيد الرب.","28:25":"وهذا ما يعلنه السيد الرب: عندما أجمع شعب إسرائيل من بين الشعوب التي تفرقوا إليها، وتتجلى قداستي فيهم أمام عيون الأمم، عندما يعودون ويستوطنون في أرضهم التي وهبتها لعبدي يعقوب،","28:26":"ويقيمون فيها مطمئنين ويشيدون بيوتا ويغرسون كروما ويسكنون آمنين. وعندما أنفذ أحكاما في جميع أعدائهم المحيطين بهم، عندئذ يدركون أني أنا الرب إلههم».","29:1":"وفي اليوم الثاني عشر من الشهر العاشر العبري (أي كانون الأول - ديسمبر) من السنة العاشرة (لسبي الملك يهوياكين)، أوحى إلي الرب بكلمته قائلا:","29:2":"«ياابن آدم، التفت نحو فرعون ملك مصر وتنبأ عليه وعلى مصر كلها","29:3":"وقل هذا ما يعلنه السيد الرب: ها أنا أنقلب عليك يافرعون ملك مصر، أيها التمساح الكامن في وسط أنهاره، القائل: النهر لي وقد صنعته لنفسي.","29:4":"ها أنا أضع خزائم في فكيك وأجعل سمك أنهارك يلتصق بحراشفك، وأخرجك قسرا من أنهارك، وأسماكها ما برحت لاصقة بحراشفك.","29:5":"وأهجرك في البرية مع جميع سمك أنهارك، فتتهاوى على سطح أرض الصحراء فلا تجمع ولاتلم بل تكون قوتا لوحوش البر ولطيور السماء.","29:6":"فيدرك كل أهل مصر أني أنا الرب، لأنهم كانوا عكاز قصب هشة لشعب إسرائيل،","29:7":"ما إن اعتمدوا عليك بأكفهم حتى انكسرت ومزقت أكتافهم، وعندما توكأوا عليك تحطمت وقصفت كل متونهم.","29:8":"لذلك ها أنا أجلب عليك سيفا وأستأصل منك الإنسان والحيوان،","29:9":"فتصبح ديار مصر مقفرة خربة، فيدركون أني أنا الرب، لأن فرعون قال: لي النهر وأنا قد صنعته.","29:10":"لذلك ها أنا أنقلب عليك وعلى أنهارك، وأجعل أراضي مصر خرائب متردمة مقفرة، من مجدل إلى أسوان حتى تخوم إثيوبيا.","29:11":"لا تمر بها قدم إنسان ولا تجتازها رجل بهيمة، وتظل مهجورة من الناس طوال أربعين سنة.","29:12":"وأجعل ديار مصر الأكثر وحشة بين الأراضي المقفرة، وتظل مدنها الأكثر خرابا بين المدن الخربة وأشدها وحشة طوال أربعين سنة، وأشتت المصريين بين الأمم وأفرقهم في البلدان.","29:13":"وفي نهاية الأربعين سنة أجمع المصريين من بين الشعوب التي تشتتوا بينها.","29:14":"وأرد سبيهم، وأعيدهم إلى أرض فتروس موطنهم، فيكونون هناك مملكة حقيرة.","29:15":"بل تكون أحقر الممالك فلا تتشامخ بعد على بقية الأمم، وأجعلهم أقلية لئلا يتسلطوا على الشعوب.","29:16":"فلا تكون بعد محط اعتماد لشعب إسرائيل، بل تذكرهم بإثمهم حين ضلوا وراءهم، فيدركون أني أنا السيد الرب».","29:17":"وفي مطلع الشهر الأول العبري (أي آذار - مارس) في السنة السابعة والعشرين (من سبي الملك يهوياكين) أوحى إلي الرب بكلمته قائلا:","29:18":"«ياابن آدم، إن نبوخذناصر ملك بابل قد سخر جيشه أشد تسخير ضد صور، فأصبحت كل رأس من رؤوس جنوده صلعاء، وكل كتف مجردة من الثياب. ولكن لم يغنم هو ولا جيشه شيئا من صور رغم ما كابده من جهد للاستيلاء عليها.","29:19":"لذلك هذا ما يعلنه السيد الرب: ها أنا أبذل ديار مصر لنبوخذناصر ملك بابل فيستولي على ثروتها، ويسلبها غنائمها وينهبها، فتكون هذه أجرة لجيشه.","29:20":"قد أعطيته أرض مصر لقاء تعبه، لأنه وجيشه قد عملوا في خدمتي، يقول السيد الرب.","29:21":"في ذلك اليوم، أنمي قوة شعب إسرائيل وأفتح فمك بينهم، فيدركون أني أنا الرب».","30:1":"وأوحى إلي الرب بكلمته قائلا:","30:2":"«ياابن آدم، تنبأ وقل: هذا ما يعلنه السيد الرب: ولولوا قائلين: يالليوم الرهيب!","30:3":"إن يوم الرب بات وشيكا؛ يوم الرب قريب، إنه يوم مكفهر بالغيوم، ساعة دينونة للأمم،","30:4":"إذ يجرد سيف على مصر، فيعم الذعر الشديد إثيوبيا، عندما يتهاوى قتلى مصر ويستولى على ثروتها، وتنقض أسسها.","30:5":"ثم تسقط معهم بالسيف إثيوبيا وفوط ولود وشبه الجزيرة العربية وليبيا وشعوب الأرض المتحالفة معهم.","30:6":"حقا يسقط مناصر مصر وتذل كبرياء عزتها، فيتهاوى بالسيف سكانها من مجدل إلى أسوان، يقول السيد الرب.","30:7":"فتصبح أكثر الأراضي المقفرة وحشة، وتضحى مدنها أكثر المدن خرابا!","30:8":"فيدركون أني أنا الرب حين أضرم نارا في مصر وينهار جميع حلفائها.","30:9":"في ذلك اليوم يسرع رسلي إلى إثيوبيا المطمئنة ليثيروا فيها الرعب في يوم هلاك مصر، الذي لابد أن يتحقق.","30:10":"لأني سأفني جماهير مصر بيد نبوخذناصر ملك بابل.","30:11":"إذ يقبل هو وجيشه، أعتى جيوش الأمم، لخراب ديار مصر، فيجردون عليها سيوفهم ويملأون أرضها بالقتلى.","30:12":"وأجفف مجاري نهر النيل، وأبيع الأرض لقوم أشرار، وأخرب البلاد فيها بيد غرباء. أنا الرب قضيت.","30:13":"ثم أحطم الأصنام وأزيل الأوثان من ممفيس، ولا يبقى بعد رئيس في ديار مصر، وألقي فيها الرعب.","30:14":"وأخرب فتروس، وأضرم نارا في صوعن، وأنفذ أحكاما في طيبة.","30:15":"وأصب غضبي على سين حصن مصر، وأبيد أهل طيبة.","30:16":"وأضرم نارا في مصر فتقاسي سين أشد الألم، وتتمزق طيبة شر تمزيق، وتتعرض ممفيس للرعب في كل يوم.","30:17":"ويتساقط بالسيف شبان آون وفيبستة، ويسبى بقية سكانها","30:18":"ويظلم النهار في تحفنحيس عندما أحطم أنيار مصر هناك، وتتلاشى كبرياء عزتها. أما هي فتغشاها سحابة، وتسبى بناتها.","30:19":"وهكذا أنفذ أحكاما في مصر، فيدركون أني أنا الرب».","30:20":"وفي اليوم السابع من الشهر الأول العبري (أي آذار - مارس) من السنة الحادية عشرة (من سبي الملك يهوياكين)، أوحى إلي الرب بكلمته قائلا:","30:21":"«ياابن آدم، إني حطمت ذراع فرعون ملك مصر، ولن تجبر بالرفائد أو العصائب، فتجرد سيفا،","30:22":"وها أنا أنقلب على فرعون ملك مصر وأحطم ذراعيه، السليمة والمكسورة، وأسقط السيف من يده.","30:23":"وأشتت المصريين بين الأمم وأفرقهم في البلدان.","30:24":"وأشدد ذراعي ملك بابل وأضع سيفي في يده، وأحطم ذراع فرعون، فيئن أمامه أنين الجريح.","30:25":"وأشدد ذراعي ملك بابل. أما ذراعا فرعون فتتهاويان، فيدركون أني أنا الرب حين أضع سيفي في يد ملك بابل، فيجرده على ديار مصر.","30:26":"وأبدد المصريين بين الأمم وأمزقهم في البلدان، فيدركون أني أنا الرب».","31:1":"وفي مطلع الشهر الثالث العبري (أي أيار - مايو) من السنة الحادية عشرة (لسبي الملك يهوياكين)، أوحى إلي الرب بكلمته قائلا:","31:2":"«ياابن آدم، قل لفرعون ملك مصر ولشعبه: من ماثلت بعظمتك؟","31:3":"إنني أشبهك بشجرة أرز في لبنان، بهية الأغصان، وارفة الظل، شامخة تطاول قمتها الغيوم،","31:4":"ترويها المياه، وتنميها اللجج. تجري أنهارها حول مغرسها، وتنساب جداولها إلى كل أشجار الحقل.","31:5":"لهذا طاولت قامتها خميع أشجار الحقل وتكاثرت أغصانها، وامتدت فروعها التي نبتت لغزارة مياهها.","31:6":"وعششت في أغصانها كل طيور السماء، وتحت فروعها ولدت كل حيوان البر، وأوت تحت ظلها كل أمم الأرض العظيمة.","31:7":"فكانت رائعة في عظمتها وفي شموخ قامتها لأن جذورها كانت مغروسة في مياه غريرة.","31:8":"لم يضاهها الأرز في جنة الله، ولم يعادل السرو أغصانها، ولم يماثل الدلب فروعها. كل الأشجار في جنة الله لم تشبهها في حسنها.","31:9":"جعلتها بهية لكثرة أغصانها حتى حسدتها كل أشجار عدن التي في جنة الله.","31:10":"لذلك يقول السيد الرب: لأنك يافرعون شمخت بقامتك وطاولت بهامتك الغيوم، تكبر قلبك من جراء عظمتك.","31:11":"أسلمتك إلى يد المتسلط على الأمم فيعاملك أقسى معاملة. إني نبذتك لفرط شرك.","31:12":"ويستأصله الغرباء عتاة الأمم، ويتركونه، فتتهاوى أغصانه على الجبال وفي جميع الوهاد، وتتحطم فروعه إلى جوار كل أنهار الأرض، ويهجر ظله كل شعوب الأرض وينبذونه.","31:13":"وتجثم على حطامه طيور السماء جميعها، وتربض فوق قضبانه كل حيوان البر","31:14":"لئلا تشمخ شجرة ما مغروسة على المياه لاَرتفاع قامتها، ولا تطاول بهامتها الغيوم، ولكي لا تبلغ أية شجرة ترويها المياه مثل هذا العلو، لأنها جميعها مآلها الموت، حيث تمضي إلى الأرض السفلى بين الفانين من بني آدم، مع الهابطين إلى الهاوية.","31:15":"وهذا ما يعلنه السيد الرب: وفي يوم هبوطه إلى الهاوية يعم النواح الطبيعة، فأكسو الغمر ثياب الحداد عليه، وأكبح جريان أنهاره، وتكف مياهه عن التدفق وأجعل لبنان ينوح عليه، وتذبل كل أشجار الحقل حزنا على هلاكه.","31:16":"من جلبة سقوطه حين أنزلته إلى الهاوية مع الهابطين إليها ارتعدت الأمم، فتتعزى في الأرض السفلى كل أشجار عدن ونخبة أشجار لبنان، وكل مرتوية من ماء.","31:17":"هم أيضا ينحدرون معه إلى الهاوية لينضموا إلى قتلى السيف، وكذلك يهلك حلفاؤه من الأمم المقيمين تحت ظله.","31:18":"من ماثلت بين أشجار عدن في المجد والعظمة؟ ستنحدر إلى الأرض السفلى مع أشجار عدن، وترقد مع الغلف، مع المقتولين بالسيف. هذا هو مصير فرعون وكل شعبه، يقول السيد الرب».","32:1":"وفي مطلع الشهر الثاني عشر (أي شباط - فبراير) من السنة الثانية عشرة (لسبي الملك يهوياكين) أوحى إلي الرب بكلمته قائلا:","32:2":"«ياابن آدم، اندب فرعون ملك مصر بمرثاة وقل له: أنت شبهت نفسك بشبل بين الأمم، مع أنك مثل تمساح في البحار. اقتحمت أنهارك وكدرت الماء بقدميك وعكرت أنهارهم.","32:3":"لذلك ها أنا أنشر عليك شبكتي مع أقوام شعوب غفيرة فيصعدونك وأنت عالق فيها.","32:4":"وأتركك ملقى على الأرض وأطرحك في العراء، فأجعل كل طيور السماء تستقر عليك، وأشبع منك جميع وحوش الأرض.","32:5":"وأنثر لحمك على الجبال، ومن جيفك أملأ الأودية.","32:6":"وأروي الأرض من دمك الجاري حتى يبلغ الجبال وتفيض به الوهاد.","32:7":"وعندما أخمدك أحجب السماوات وأظلم نجومها، وأكفن الشمس بسحاب، ولا ينير القمر بضوئه.","32:8":"وأعتم فوقك كل أنوار السماء المضيئة، وأجعل الظلمة تغمر أرضك يقول السيد الرب.","32:9":"وأشيع الغم في قلوب أمم كثيرة عندما أكسرك بين الشعوب في أراض غريبة عنك.","32:10":"ولأجل ما يصيبك يعتري الفزع شعوبا كثيرة، وتنتاب ملوكهم قشعريرة رهيبة، عندما أخطر أمامهم بسيفي، فيرتعدون جميعا في كل لحظة، كل واحد خوفا على نفسه في يوم سقوطك.","32:11":"لأن هذا ما يعلنه السيد الرب: ها سيف ملك بابل يقع عليك،","32:12":"فأهلك جيوشك بسيوف الجبابرة من أعتى الأمم فيذلون كبرياء مصر ويفنون جيوشها.","32:13":"وأبيد جميع بهائمها المرتوية من المياه الكثيرة، فلا تكدرها من بعد رجل إنسان ولا تعكرها أظلاف البهائم.","32:14":"حينئذ أجعل مياههم صافية، وأنهارهم تجري بنعومة كالزيت، يقول السيد الرب.","32:15":"وحين أحول أرض مصر إلى خراب، وأقفرها ممن فيها، وعندما أقضي على جميع سكانها، حينئذ يدركون أني أنا الرب.","32:16":"هذه هي المرثاة التي ترثو بها بنات الأمم مصر وكل جندها، يقول السيد الرب».","32:17":"وفي اليوم الخامس عشر من الشهر نفسه، في السنة الثانية عشرة أوحى إلي الرب بكلمته قائلا:","32:18":"«ياابن آدم، أعول على جند مصر، وأحدره مع سائر الأمم العظيمة إلى طبقات الأرض السفلى مع الهابطين إلى الجب.","32:19":"على من تفوقت بالجمال؟ انزل وارقد مع الغلف.","32:20":"يسقطون صرعى وسط قتلى السيف. قد أسلمت مصر للسيف، وأسروها مع كل حلفائها.","32:21":"يخاطبه صناديد الجبابر ة هو وأعوانه من وسط مقر الموتى. قد هبطوا واضطجعوا. جميعهم غلف قتلى السيف.","32:22":"هناك أشور وقومه جميعا قد أحاطت به قبورهم. كلهم صرعى السيف.","32:23":"الذين صارت قبورهم في أسافل الجب، وحوله قبور حلفائه، كلهم قتلى، صرعى السيف. أولئك الذين أشاعوا الرعب في أرض الأحياء.","32:24":"وهناك أيضا عيلام وحلفاؤها بأسرهم يحيطون بقبرها. جميعهم غلف صرعى السيف. هبطوا إلى الأرض السفلى، أولئك الذين أشاعوا الرعب في أرض الأحياء، فحملوا عارهم مع المنحدرين إلى الجب.","32:25":"قد جعلوا لمصر ولحلفائها مثوى بين القتلى، وقبورهم حول عيلام، كلهم غلف قتلى السيف مع أنهم أشاعوا الرعب في أرض الأحياء. وها هم قد حملوا عارهم مع المنحدرين إلى الجب. عيلام أيضا وسط القتلى.","32:26":"وهناك أيضا ماشك وتوبال وكل حلفائهما تحيط بهما قبورهم. كلهم غلف قتلى السيف، مع أنهم أشاعوا الرعب في أرض الأحياء.","32:27":"إنهم لا يثوون مع الجبابرة الصرعى من الغلف المنحدرين إلى مقر الموتى، الذين دفنوا بأسلحتهم، وقد وضعت سيوفهم تحت رؤوسهم. إنما يحل على عظامهم عقاب آثامهم مع أنهم أشاعوا الرعب في أرض الأحياء.","32:28":"أما أنت يافرعون ففي وسط الغلف تنكسر، وترقد بين قتلى السيف.","32:29":"وهناك أيضا أدوم وملوكها ورؤساؤها ممن طرحوا مع قتلى السيف رغم عتوهم. هؤلاء يرقدون مع الغلف ومع المنحدرين إلى الجب.","32:30":"وهناك أمراء الشمال جميعهم وكل الصيدونيين المنحدرين مع القتلى، رغم ما أشاعوه من رعب ناجم عن طغيانهم. قد رقدوا غلفا مع قتلى السيف، وحملوا عارهم مع المنحدرين إلى الجب.","32:31":"يراهم فرعون جميعا فيتعزى عن جميع حلفائه الذين قتلهم السيف، ولم ينج منه حتى فرعون وجيشه، يقول السيد الرب.","32:32":"فمع أني أشعت رعبه في أرض الأحياء، فإن فرعون وحلفاءه كلهم سيرقدون بين الغلف قتلى السيف يقول السيد الرب».","33:1":"وأوحى إلي الرب قائلا:","33:2":"«ياابن آدم، خاطب أبناء إسرائيل وقل لهم: إذا جلبت سيفا على أرض كان أهلها قد أقاموا لهم رقيبا من بينهم.","33:3":"فإذا رأى الأعداء مقبلين لمهاجمة الأرض، فنفخ بالبوق تحذيرا للشعب،","33:4":"فمن يسمع دوي البوق ولا يحترس، ثم أتى السيف وقتله، فدمه يقع على رأسه.","33:5":"لأنه سمع دوي البوق ولم يحترس. لهذا يكون دمه على نفسه، إذ لو احترس لأنقذ نفسه.","33:6":"ولكن إن رأى الرقيب العدو مقبلا ولم ينفخ بالبوق، فلم يحترس الشعب، فأقدم العدو وقتل نفسا منهم، فالقتيل قد لاقى حتفه جزاء ذنبه، أما دمه فمن يد الرقيب أطلبه.","33:7":"وأنت ياابن آدم، قد أقمتك رقيبا لشعب إسرائيل، فتسمع قضائي، وتحذرهم من قبلي.","33:8":"إن قلت للشرير: ياشر ير إنك حتما تموت من أجل شرك، ولم تعمد إلى تحذيره من طريقه، فإن ذلك الشرير يموت بذنبه، أما دمه فمن يدك أطلبه.","33:9":"ولكن إن حذرت الشرير ليرتدع عن طريقه فأبى فهو يموت بذنبه، أما أنت فتكون قد خلصت نفسك.","33:10":"وأنت ياابن آدم، قل لشعب إسرائيل: أنتم تقولون: حقا إن معاصينا وخطايانا واقعة علينا، وبها نحن هالكون، فكيف إذا نحيا؟","33:11":"قل لهم: حي أنا يقول السيد الرب، إني لا أبتهج بموت الشرير بل بأن يرتدع عن غيه ويحيا. ارجعوا، ارجعوا عن طرقكم الرديئة! لماذا تموتون ياشعب إسرائيل؟","33:12":"وأنت ياابن آدم، قل لأبناء شعبك: لا ينجو البار ببره في يوم معصيته، ولا يعثر الشرير بشره في يوم توبته. كذلك لا يستطيع البار أن يحيا ببره في يوم اقترافه لخطيئته.","33:13":"وإن قلت للبار إنك لا محالة تحيا، فاعتمد على بره وأثم، فإن بره كله لا يذكر له، بل يموت بما ارتكب من إثم.","33:14":"وإذا قلت للشرير إنك لا محالة مائت: فارتدع عن خطيئته ومارس العدل والحق،","33:15":"ورد الرهن، وعوض عما اغتصبه، وسلك في الفرائض التي تؤمن له الحياة، من غير أن يرتكب إثما، فإنه لا محالة يحيا ولا يموت في خطاياه،","33:16":"ولا تذكر كل خطيئة ارتكبها، لأنه عاد فمارس العدل والحق. إنه حياة يحيا!","33:17":"ومع ذلك يدعي أبناء شعبك أن طريق الرب معوجة. بل إن طريقهم هم هي المعوجة.","33:18":"فعند ارتداد البار عن بره وارتكابه الإثم فإنه به يموت.","33:19":"وعند ارتداع الشرير عن غيه، وممارسته العدل والحق، فإنه بهما يحيا.","33:20":"وأنتم مع ذلك تقولون إن طريق الرب معوجة. إنني أدين كل واحد منكم بمقتضى طرقه ياشعب إسرائيل».","33:21":"وفي اليوم الخامس من الشهر العاشر من السنة الثانية عشرة من سبينا، أقبل إلي ناج من أورشليم وقال: «قد تم تدمير المدينة».","33:22":"وكانت يد الرب علي في المساء قبيل مجيء الناجي، وفتح الرب فمي في الصباح عند وصوله، فانفكت عقدة لساني ولم أعد أبكم.","33:23":"فأوحى إلي الرب بكلمته قائلا:","33:24":"«ياابن آدم، إن المقيمين في خرائب أرض إسرائيل يقولون إن إبراهيم كان فردا واحدا ومع ذلك ورث الأرض، وهكذا نحن كثيرون، وقد وهبت لنا الأرض ميراثا.","33:25":"لذلك قل لهم: أتأكلون اللحم بالدم وتتعلق عيونكم بأصنامكم وتسفكون الدم، ثم ترثون الأرض؟","33:26":"اعتمدتم على سيوفكم، وارتكبتم الموبقات، وزنى كل منكم مع امرأة صاحبه. فهل ترثون الأرض؟","33:27":"قل لهم، هذا ما يعلنه السيد الرب: حي أنا، إن الذين يقيمون في الخرائب يقتلون بالسيف، والذين يسكنون في العراء أبذلهم قوتا للوحوش، والمتمنعون في الحصون والمغاور يموتون بالوباء.","33:28":"فأجعل الأرض أطلالا مقفرة وتبطل كبرياء عزتها، وتصبح جبال إسرائيل جرداء لا يجتاز بها عابر.","33:29":"فيدركون أني أنا الرب حين أجعل الأرض خربة مقفرة من جراء ما ارتكبوه من رجاسات.","33:30":"أما أنت ياابن آدم فإن أبناء شعبك يتحدثون عنك بجوار الجدران وفي مداخل أبواب البيوت، ويخاطب أحدهم الآخر، والرجل أخاه قائلين: هيا تعالوا اسمعوا كلام الوحي الصادر من عند الرب.","33:31":"ويقبلون إليك مثل سائر الشعب ويجلسون في حضرتك نظير شعبي، ويصغون إلى كلامك ولا يعملون به. إنهم يعربون عن أشواقهم بكلامهم، أما قلبهم فقد غوى وراء مكسبهم.","33:32":"وها أنت لهم كقصيدة حب يتغنى بها ذو صوت عذب، يحسن العزف، فيصغون إلى كلامك ولا يعملون به.","33:33":"وإذا تحقق هذا، وهو لابد أن يتم، يدركون أن نبيا كان بينهم».","34:1":"وأوحى إلي الرب بكلمته قائلا:","34:2":"«ياابن آدم، تنبأ على رعاة إسرائيل وقل لهم: هذا ما يعلنه لهم السيد الرب: ويل لرعاة إسرائيل الذين كانوا منهمكين في رعاية أنفسهم. أليس من شأن الرعاة رعاية الغنم؟","34:3":"إنما أنتم تأكلون الشحم، وترتدون الصوف، وتذبحون الخروف السمين، ولا ترعون الغنم.","34:4":"فالمريض لم تقووه، والمجروح لم تعصبوه، والمكسور لم تجبروه، والمطرود لم تسترجعوه، والضال لم تبحثوا عنه، بل تسلطتم عليهم بقسوة وعنف.","34:5":"فتشتتت الرعية وأضحت بلا راع، وصارت قوتا لجميع وحوش البرية.","34:6":"ضلت غنمي بين الجبال وفوق كل أكمة مرتفعة. تبددت غنمي في العراء ولم يوجد من ينشدها أو يلتمسها.","34:7":"لذلك اسمعوا أيها الرعاة كلام الرب:","34:8":"حي أنا يقول السيد الرب، لأن غنمي باتت غنيمة وصارت قوتا لكل وحش البرية، إذ لم يكن هناك راع ولا سأل رعاتي عن غنمي، بل انهمكوا في رعاية أنفسهم وأهملوا غنمي،","34:9":"لذلك، اسمعوا أيها الرعاة كلام الرب:","34:10":"ها أنا أنقلب على الرعاة وأطالبهم بغنمي، وأعزلهم عن رعايتها، فلا يرعون حتى أنفسهم بعد. وأنقذ غنمي من أشداقهم فلا تكون لهم مأكلا.","34:11":"لأن هذا ما يعلنه السيد الرب: ها أنا أبحث عن غنمي وأفتقدها.","34:12":"وكما يتفقد الراعي قطيعه في اليوم الذي يكون فيه بين غنمه المشتتة، هكذا أتفقد قطيعي وأخلصه من كل الأماكن التي تفرق إليها في يوم غائم كئيب.","34:13":"وأخرجه من بين الشعوب وأجمعه من البلدان، وأرده إلى أرضه، حيث أرعاه على جبال إسرائيل وفي الأودية وفي جميع أماكن الأرض الآهلة.","34:14":"وأرعاه في مروج خصيبة، وتكون جبال إسرائيل الشاهقة مراعي رائعة يربضون في مراحها الطيب، ويرعون في مراع خصيبة على جبال إسرائيل.","34:15":"أنا أرعى غنمي وأربضها يقول السيد الرب،","34:16":"وأطلب الضال وأسترجع المطرود وأجبر الكسير وأعصب الجريح وأستأصل السمين والقوي، وأرعاها بعدل.","34:17":"أما أنتم ياغنمي فها أنا أقضي بين شاة وشاة، وبين كباش وتيوس.","34:18":"أتحسبون أنه أمر تافه أن ترعوا في المرعى الخصيب وتدوسوا بأرجلكم بقية المراعي؟ وأن تشربوا من المياه الصافية وتعكروا بقيتها بأقدامكم؟","34:19":"فيتحتم على غنمي أن ترعى ما داسته أقدامكم وتشرب ما كدرته أرجلكم.","34:20":"لذلك ها أنا أقضي بين الشاة السمينة والشاة الهزيلة،","34:21":"لأنكم دفعتم بالجنب والكتف الشاة المريضة ونطحتموها بقرونكم حتى شتتموها إلى خارج.","34:22":"ولكني أنقذ غنمي فلا تكون من بعد غنيمة، وأقضي بين شاة وشاة،","34:23":"وأنصب عليها راعيا واحدا عبدي داود (أي المسيح) يرعاها بنفسه ويكون لها راعيا أمينا.","34:24":"وأنا الرب أكون لهم إلها، وعبدي داود يكون لهم رئيسا. أنا الرب تكلمت.","34:25":"وأبرم معهم ميثاق سلام، وأقضي على الوحوش الضارية في الأرض فيقيمون في الصحراء آمنين، وينامون في الغابات مطمئنين.","34:26":"وأجعلهم مع ما يحيط بأكمتي بركة، وأسكب عليهم المطر في أوانه، فتكون أمطار بركة.","34:27":"وتثمر شجرة الحقل، وتنتج الأرض غلتها، ويكونون آمنين في ديا رهم، ويدركون عندما أحطم نيرهم وأنقذهم من قبضة مستعبديهم أني أنا الرب.","34:28":"فلا يكونون بعد غنيمة للأمم، ولا يفترسهم وحش الأرض، بل يسكنون آمنين لا يفزعهم أحد.","34:29":"وأقيم لهم مغرسا ذائع الصيت، فلا يكونون بعد ضحايا مجاعة في الأرض، ولا يتحملون بعد مشقة تعيير الأمم،","34:30":"فيدركون أني أنا الرب إلههم معهم، وأنهم شعبي بيت إسرائيل، يقول السيد الرب.","34:31":"وأنتم ياقطيعي غنم مرعاي، أنتم بشر وأنا إلهكم يقول السيد الرب».","35:1":"وأوحى إلي الرب بكلمته قائلا:","35:2":"«ياابن آدم، التفت بوجهك نحو جبل سعير وتنبأ عليه.","35:3":"وقل لأهله: ها أنا أنقلب عليك ياجبل سعير وأعاقبك لأجعلك خرابا مقفرا.","35:4":"أجعل مدنك أطلالا وتكون أنت مقفرا، فتدرك أني أنا الرب.","35:5":"لأنك أضمرت في نفسك بغضة أبدية، وأسلمت بني إسرائيل إلى حد السيف في أثناء محنتهم، في ساعة دينونة إثمهم.","35:6":"لذلك حي أنا يقول السيد الرب، إني أعدك لسفك الدم، والدم يتعقبك. لأنك لم تمقت سفك الدم فالدم يتعقبك.","35:7":"فأحول جبل سعير إلى أطلال وأستأصل منه كل ذاهب وآيب.","35:8":"وأجعل جباله تكتظ بقتلاه، فيتساقطون في تلالك وأوديتك وجميع أنهارك صرعى السيف.","35:9":"وأحيلك إلى خرائب أبدية، فلا يبقى لمدنك أثر، فتدركون أني أنا الرب.","35:10":"لأنك قلت: إن هاتين الأمتين، وهاتين الأرضين تصبحان لي فأمتلكهما، ولو كان الرب هناك.","35:11":"لذلك حي أنا يقول السيد الرب: لأعاملنك بمقتضى غضبك وحسدك اللذين أبديتهما في بغضائك لهم، فأعلن ذاتي عندما أدينك.","35:12":"فتدرك أني أنا الرب قد سمعت كل إهانتك التي عيرت بها جبال إسرائيل قائلا: قد أصبحت خرابا وصارت لنا مغنما.","35:13":"قد تباهيتم علي بأفواهكم، وأكثرتم من لغوكم علي وأنا سمعت.","35:14":"ففي موسم الربيع أجعلك مقفرا","35:15":"وكما فرحت لخراب ميراث شعب إسرائيل، كذلك أفعل بك، فتصير ياجبل سعير خرابا أنت وكل بلاد أدوم فتدركون أني أنا الرب».","36:1":"»أما أنت ياابن آدم، فتنبأ لجبال إسرائيل وقل: اسمعي ياجبال إسرائيل كلمة الرب.","36:2":"هذا ما يعلنه السيد الرب: لأن العدو قد تهكم عليكم قائلا: هه. قد صار ت المرتفعات القديمة ميراثا لنا.","36:3":"لذلك تنبأ وقل: لأنهم قد دمروكم واقتحموكم من كل جهة لتصبحوا ميراثا لسائر الأمم، وصرتم حديث كل شفة ومذمة الشعب،","36:4":"لذلك اسمعي ياجبال إسرائيل وحي السيد الرب للجبال والآكام والأنهار والأودية وللخرائب المقفرة وللمدن المهجورة التي صارت نهبا لبقية الأمم المحيطة بها ومثار استهزاء:","36:5":"ها أنا في أثناء احتدام نار غيرتي أصدرت قضائي على بقية الأمم وعلى أدوم قاطبة، الذين اغتصبوا أرضي ميراثا لهم، بقلوب مغتبطة ونفوس حاقدة لتكون لهم نهبا وغنيمة.","36:6":"لذلك تنبأ عن أرض إسرائيل وقل للجبال والتلال والأودية: هذا ما يعلنه السيد الرب: ها أنا في غيرتي وسخطي قد أصدرت قضائي لأنكم قد تحملتم تعيير الأمم،","36:7":"فأقسمت أن تتحمل الأمم المحيطة بكم عار أنفسهم.","36:8":"أما أنت ياجبال إسرائيل فتفرخين فروعك، وتحمل أشجارك أثمارا لشعبي إسرائيل لأن موعد رجوعهم بات وشيكا.","36:9":"فأنا لك، أعتني بك فتحرثين وتزرعين.","36:10":"وأجعلك آهلة بالناس، كل شعب إسرائيل، فتعمر المدن وتبنى الخرائب.","36:11":"وأكثر عليك الإنسان والبهيمة فيكثرون ويثمرون، فتصبحين آهلة كسالف الزمان، وأحسن إليك أكثر مما أحسنت في الأيام الغابرة، فتدركون جميعا أني أنا الرب.","36:12":"وأجعل الناس من شعبي إسرائيل يخطرون عليك، فيرثونك وتكونين لهم ملكا ولا تثكلينهم من بعد.","36:13":"لأ نهم قالوا لك: أنت مفترسة الناس ومثكلة شعوبك","36:14":"لهذا لن تفترسي الناس بعد، ولن تثكلي شعوبك يقول السيد الرب.","36:15":"ولا يتردد فيك من بعد تعيير الأمم، ولا تحملين تعيير الشعوب ولا تعودين تعثرين شعوبك يقول السيد الرب».","36:16":"وأوحى إلي الرب بكلمته قائلا:","36:17":"«ياابن آدم، عندما أقام شعب إسرائيل في أرضهم نجسوها بطرقهم الشريرة وتصرفاتهم. كانت طريقهم أمامي نجسة كنجاسة الطامث.","36:18":"فسكبت غضبي عليهم من جراء ما سفكوه من دم على الأرض التي نجسوها بأصنامهم.","36:19":"ففرقتهم بين الأمم وشتتهم في البلدان، ودنتهم بمقتضى طريقهم وتصرفاتهم.","36:20":"وحين استقروا بين الأمم التي تفرقوا بينها، دنسوا اسمي القدوس إذ قيل لهم: هؤلاء شعب الرب وقد طردوا من أرضه.","36:21":"فغرت على اسمي الذي نجسه شعب إسرائيل بين الأمم التي تفرقوا بينها.","36:22":"لذلك قل لشعب إسرائيل: ليس لأجلكم أنا موشك أن أعمل (عظائم) ياشعب إسرائيل، بل غيرة على اسمي الذي دنستموه بين الأمم التي تفرقتم بينها.","36:23":"فأقدس اسمي العظيم الذي صار بسببكم منجسا بين الأمم التي تفرقتم بينها، فتدرك الأمم أني أنا الرب حين أتقدس فيكم أمام أعينهم يقول السيد الرب.","36:24":"إذ آخذكم من بين الأمم وأجمعكم من كل البلدان وأحضركم إلى أرضكم،","36:25":"وأرش عليكم ماء نقيا فتطهرون من كل نجاستكم ومن كل أصنامكم،","36:26":"وأهبكم قلبا جديدا، وأضع في داخلكم روحا جديدة، وأنتزع من لحمكم قلب الحجر وأعطيكم عوضا عنه قلب لحم.","36:27":"وأضع روحي في داخلكم فأجعلكم تمارسون فرائضي وتطيعون أحكامي عاملين بها،","36:28":"وتستوطنون الأرض التي وهبتها لآبائكم وتكونون لي شعبا وأنا أكون لكم إلها،","36:29":"وأخلصكم من جميع نجاستكم وآمر الحنطة أن تتكاثر، ولا أجلب عليكم المجاعة.","36:30":"وأكثر أثمار الأشجار ومحاصيل الحقل لئلا تتعرضوا لعار الجوع بين الأمم.","36:31":"فتذكرون طرقكم الأثيمة وتصرفاتكم الطالحة، وتمقتون أنفسكم في أعينكم لما ارتكبتم من آثام ورجاسات.","36:32":"لهذا اعلموا أنه ليس من أجلكم أنا أفعل هذا، يقول السيد الرب، فاخجلوا واخزوا من طرقكم ياشعب إسرائيل.","36:33":"وهذا ما يعلنه السيد الرب: في اليوم الذي أطهركم فيه من كل آثامكم أسكنكم في المدن فتبنى الخرائب،","36:34":"وتفلح الأرض الجرداء عوض أن تبقى أرضا خربة في عيني كل عابر.","36:35":"فيقولون: قد صارت هذه الأرض الجرداء كجنة عدن، وأصبحت المدن المهجورة المتهدمة مدنا محصنة آهلة.","36:36":"فتدرك الأمم التي ما برحت حولكم أني أنا الرب، قد بنيت ما تهدم، وغرست ما أقفر أنا الرب قد نطقت وأنجز ما وعدت به.","36:37":"عندئذ أجعل شعب إسرائيل يلتمسون هذا مني، فأستجيب لمطلبهم: أن أكثرهم كقطيع غنم.","36:38":"كغنم الذبائح المقدسة، كغنم أورشليم في مواسم أعيادها، فتكتظ المدن الخربة بجماعات الناس الغفيرة، فيدركون أني أنا الرب».","37:1":"وكانت يد الرب علي فأحضرني بالروح إلى وسط واد مليء بعظام،","37:2":"وجعلني أجتاز بينها وحولها، وإذا بها كثيرة جدا، تغطي سطح أرض الوادي، كما كانت شديدة اليبوسة.","37:3":"فقال لي «ياابن آدم، أيمكن أن تحيا هذه العظام؟» فأجبت: «ياسيد الرب، أنت أعلم».","37:4":"فقال لي: «تنبأ على هذه العظام وقل لها: اسمعي أيتها العظام اليابسة كلمة الرب:","37:5":"ها أنا أجعل روحا يدخل فيك فتحيين.","37:6":"وأكسوك بالعصب واللحم، وأبسط عليك جلدا وأجعل فيك روحا فتحيين وتدركين أني أنا الرب».","37:7":"وفيما كنت أتنبأ كما أمرت، حدث صوت جلبة وزلزلة، فتقاربت العظام كل عظم إلى عظمه،","37:8":"واكتست بالعصب واللحم وبسط عليها الجلد. إنما لم يكن فيها روح","37:9":"فقال لي: «تنبأ للروح ياابن آدم، وقل: هذا ما يأمر به السيد الرب: هيا ياروح أقبل من الرياح الأربع وهب على هؤلاء القتلى ليحيوا».","37:10":"فتنبأت كما أمرني الرب، فدخل فيهم الروح فدبت فيهم الحياة، وانتصبوا على أقدامهم جيشا عظيما جدا جدا.","37:11":"ثم قال لي: «ياابن آدم، هذه العظام هي جملة شعب إسرائيل. ها هم يقولون قد يبست عظامنا ومات رجاؤنا وانقطعنا.","37:12":"لذلك تنبأ وقل لهم هذا ما يعلنه السيد الرب: ها أنا أفتح قبوركم وأخرجكم منها ياشعبي وأحضركم إلى أرض إسرائيل،","37:13":"فتدركون أني أنا الرب حين أفتح قبوركم وأخرجكم منها ياشعبي.","37:14":"وأضع روحي فيكم فتحيون، وأردكم إلى أرضكم فتدركون أني أنا الرب قد تكلمت وأنجزت ما وعدت به، يقول الرب».","37:15":"وأوحى إلي الرب بكلمته قائلا:","37:16":"«وأنت ياابن آدم، خذ لك قضيبا واحدا واكتب عليه: هذا ليهوذا ولأبناء إسرائيل رفاقه، ثم خذ قضيبا آخر واكتب عليه: هذا ليوسف قضيب أفرايم وكل شعب إسرائيل رفاقه.","37:17":"وضمهما معا كقضيب واحد فيصبحا في يدك قضيبا واحدا.","37:18":"وإذا سألك أبناء شعبك: ألا تخبرنا ما معنى هذا؟","37:19":"فقل لهم: هذا ما يعلنه السيد الرب: ها أنا أتناول قضيب يوسف الذي في حوزة أفرايم وأسباط إسرائيل رفاقه، وأضم إليه قضيب يهوذا، وأجعلهم جميعا قضيبا واحدا فيصبحون واحدا في يدي.","37:20":"ويكون في يدك، على مشهد منهم القضيبان اللذان كتبت عليهما.","37:21":"وها أنا أحشد أبناء إسرائيل من بين الأمم التي تفرقوا فيها وأجمعهم من كل جهة وأحضرهم إلى أرضهم.","37:22":"وأجعلهم أمة واحدة في الأرض وعلى الجبال، تحت رئاسة ملك واحد، فلا يكونون بعد أمتين، ولا ينقسمون إلى مملكتين.","37:23":"ولا يتدنسون بعد بأصنامهم ورجاساتهم ولا بأي من معاصيهم، بل أخلصهم من مواطن إثمهم، وأطهرهم فيكونون لي شعبا وأنا أكون لهم إلها.","37:24":"ويصبح داود عبدي (أي المسيح) ملكا عليهم، فيكون لهم جميعا راع واحد فيمارسون أحكامي ويطيعون فرائضي عاملين بها.","37:25":"ويقيمون في الأرض التي وهبتها لعبدي يعقوب التي سكن فيها آباؤكم، فيستوطنون فيها هم وأبناؤهم وأحفادهم إلى الأبد. ويكون عبدي داود (أي المسيح) رئيسا عليهم مدى الدهر.","37:26":"وأبرم معهم ميثاق سلام، فيكون معهم عهدا أبديا، وأوطنهم وأكثرهم وأقيم مقدسي في وسطهم إلى الأبد.","37:27":"ويكون مسكني معهم، فأكون لهم إلها ويكونون لي شعبا.","37:28":"فتدرك الأمم أني أنا الرب مقدس إسرائيل، حين يكون مقدسي قائما في وسطهم إلى الأبد».","38:1":"وأوحى إلي الرب بكلمته قائلا:","38:2":"«ياابن آدم، التفت بوجهك نحو جوج أرض ماجوج رئيس روش ماشك وتوبال وتنبأ عليه،","38:3":"وقل، هذا ما يعلنه السيد الرب: ها أنا أنقلب عليك ياجوج رئيس روش ماشك وتوبال،","38:4":"وأقهرك وأضع شكائم في فكيك، وأطردك أنت وكل جيشك خيلا وفرسانا وجميعهم مرتدون أفخر ثياب، جمهورا غفيرا كلهم حملة أتراس ومجان من كل قابض سيف.","38:5":"ومن جملتهم رجال فارس وإثيوبيا وفوط يحمل كل واحد مجنا وخوذة،","38:6":"وأيضا جومر وكل جيوشه، وبيت توجرمة من أقاصي الشمال مع كل جيشه. جميعهم جيوش غفيرة اجتمعت إليك.","38:7":"تأهب واستعد أنت وجميع الجيوش المنضمة إليك، لأنك أصبحت لهم قائدا،","38:8":"إذ بعد أيام كثيرة تستدعى للقتال، فتقبل في السنين الأخيرة إلى الأرض الناجية من السيف التي تم جمع أهلها من بين شعوب كثيرة، فأقاموا مطمئنين على جبال إسرائيل التي كانت دائما مقفرة في نظر الذين لم شتاتهم من بين الأمم،","38:9":"فتأتي مندفعا كزوبعة، وتكون كسحابة تغطي الأرض أنت وجيوشك وكل من معك من شعوب كثيرة.","38:10":"ويحدث في ذلك اليوم أن أفكار سوء تراودك","38:11":"فتقول: أزحف على أرض عراء مكشوفة وأهاجم المطمئنين الساكنين في أمن، المقيمين كلهم من غير سور يقيهم، وليس لديهم مزاليج ولا مصاريع،","38:12":"للاستيلاء على الأسلاب ونهب الغنائم ومهاجمة الخرائب التي أصبحت آهلة، ولمحاربة الشعب المجتمع من بين الأمم، المقتني ماشية وأملاكا، المستوطن في مركز الأرض.","38:13":"ويسألك أهل شبا ورودس وتجار ترشيش وكل قراها؛ أقادم أنت للاستيلاء على الأسلاب؟ هل حشدت جيوشك لنهب الغنائم ولحمل الفضة والذهب وأخذ الماشية والمقتنيات وللسلب العظيم؟","38:14":"لذلك تنبأ ياابن آدم، وقل لجوج هذا ما يعلنه السيد الرب: في ذلك اليوم عندما يسكن شعبي إسرائيل آمنا، ألا تعلم ذلك؟","38:15":"وتقبل أنت من مقرك في أقاصي الشمال مع جيوش غفيرة، تغشي الأرض؛ كلهم راكبو خيل وجمع عظيم وجيش كثير.","38:16":"وتزحف على شعبي إسرائيل كسحابة تغطي الأرض، أني في الأيام الأخيرة آتي بك إلى أرضي لكي تعرفني الشعوب عندما تتجلى قداستي حين أدمرك ياجوج أمام عيونهم.هذا ما يقوله السيد الرب:","38:17":"ألست أنت الذي تحدثت عنه في الأيام الغابرة على ألسنة عبيدي أنبياء إسرائيل الذين تنبأوا في تلك الأيام لسنين كثيرة بأني سآتي بك عليهم؟","38:18":"ويقول السيد الرب: في ذلك اليوم عندما يزحف جوج على أرض إسرائيل يحتدم غضبي في وجهي.","38:19":"وفي خضم غيرتي واتقاد سخطي أقول إنه في ذلك اليوم تحدث هزة عظيمة في أرض إسرائيل،","38:20":"فيرتعش من حضرتي سمك البحر وطيور السماء ووحوش البرية وجميع الحيوانات الدابة على الأرض، وكل الناس الذين على وجه المسكونة، وتندك الجبال وتسقط المعاقل وتنهار كل الأسوار إلى الأرض.","38:21":"وأسلط عليه السيف في كل جبالي يقول السيد الرب، فيكون سيف كل رجل ضد أخيه.","38:22":"وأدينه بالوباء وبالدم، وأمطر عليه وعلى جيوشه وعلى جموع حلفائه الغفيرة مطرا جارفا وبردا عظيما ونارا وكبريتا.","38:23":"فأعظم نفسي وأقدسها، وأعلن ذاتي على مرأى من كل الأمم، فيدركون أني أنا الرب».","39:1":"»وتنبأ أنت ياابن آدم على جوج وقل: هذا ما يعلنه السيد الرب:","39:2":"ها أنا أنقلب عليك ياجوج رئيس روش، ماشك وتوبال، فأحول طريقك وأقودك وأحضرك من أقاصي الشمال وآتي بك إلى جبال إسرائيل،","39:3":"وأحطم قوسك في يدك اليسرى، وأسقط سهامك من يدك اليمنى.","39:4":"فتتهاوى أنت وجميع جيوشك وسائر حلفائك الذين معك على جبال إسرائيل، وأجعلك قوتا لكل أصناف الطيور الجارحة ولوحوش البرية.","39:5":"فتصرع على وجه الصحراء، لأني قضيت يقول السيد الرب.","39:6":"وأصب نارا على ماجوج وعلى حلفائه الساكنين بأمان في الأرض الساحلية، فيدركون أني أنا الرب.","39:7":"وأعرف اسمي القدوس بين شعبي إسرائيل، ولا أعود أدعه يتدنس فتدرك الأمم أني أنا الرب قدوس إسرائيل.","39:8":"ها إن الأمر قد وقع وتم يقول السيد الرب. هذا هو اليوم الذي أخبرت به،","39:9":"فيخرج سكان مدن إسرائيل ويحرقون الأسلحة والمجان والأتراس والقسي والسهام والحراب والرماح، ويوقدون بها النار سبع سنين.","39:10":"ولا يجمعون من الحقل قضيبا ولا يحتطبون من الغاب، لأنهم يوقدون النار بالسلاح، وينهبون ناهبيهم ويسلبون سالبيهم، يقول السيد الرب.","39:11":"ومن ذلك اليوم أجعل لجوج موضعا يدفن فيه في إسرائيل، هو وادي العابرين المتجه شرقا نحو البحر (الميت)، فيسد الطريق أمام العابرين إذ هناك يدفنون جوجا وسائر جيوشه ويدعون الموضع «وادي جمهور جوج».","39:12":"ويقوم شعب إسرائيل بدفنهم طوال سبعة أشهر تطهيرا للأرض.","39:13":"ويتولى كل شعب الأرض دفنهم، ويكون يوم تمجيدي يوما مشهودا لهم، يقول السيد الرب.","39:14":"ويخصصون رجالا يتجولون دائما في الأرض ليدفنوا مع العابرين جثث الباقين على وجه الأرض تطهيرا لها. وبعد سبعة أشهر يستكشفونها.","39:15":"فيجتاز العابرون فيها، فإن عثر أحد على عظم إنسان يكوم إلى جواره صوة إلى أن يأتي العابرون ليدفنوه في وادي جمهور جوج.","39:16":"ويكون اسم المدينة همونة (أي حشدا أو جماعة) وهكذا يطهرون الأرض.","39:17":"أما أنت ياابن آدم، فهذا ما يعلنه السيد الرب: قل لكل أصناف الطيور ولجميع وحوش البرية اجتمعي وتعالي، احتشدي من كل جهة حول ذبيحتي التي أعدها لك، ذبيحة عظيمة أقيمها على جبال إسرائيل فتأكلين لحما وتشربين دما.","39:18":"تأكلين لحم الجبابرة وترتوين من دماء رؤساء الأرض وكأنها كباش وحملان وتيوس وعجول كلها من قطعان باشان السمينة.","39:19":"فتأكلين شحما حتى الشبع، وتشربين دما حتى السكر من ذبيحتي التي أعددتها لك.","39:20":"فتشبعين على مائدتي من الخيل وفرسانها، من الجبابرة وكل المحاربين، يقول السيد الرب.","39:21":"وأجعل مجدي يتجلى بين الأمم فتشهد دينونتي التي أنزلتها بهم، وقدرة يدي التي مددتها عليهم.","39:22":"فيدرك شعب إسرائيل أني أنا الرب إلههم من ذلك اليوم فصاعدا.","39:23":"وتعلم الأمم أيضا أن سبي إسرائيل كان عقابا لهم على إثمهم، لأنهم خانوني، فحجبت وجهي عنهم وأسلمتهم ليد أعدائهم، فسقطوا كلهم بحد السيف،","39:24":"فعاملتهم بمقتضى نجاستهم ومعاصيهم، وحجبت وجهي عنهم.","39:25":"أما الآن فها أنا أرد سبي ذرية يعقوب وأرحم كل شعب إسرائيل وأغار على اسمي القدوس،","39:26":"فينسون عارهم وخيانتهم التي ارتكبوها بحقي بعد أن أسكنهم في أرضهم مطمئنين لا يفزعهم أحد.","39:27":"عندما أستردهم من بين الشعوب وأجمعهم من بلدان أعدائهم وأتقدس فيهم أمام عيون الأمم الكثيرة،","39:28":"فيدركون أني أنا الرب إلههم، إذ نفيتهم إلى الأمم، ثم عدت وجمعتهم إلى أرضهم، من غير أن أبقي هناك منهم أحدا من بعد.","39:29":"ولا أعود أحجب وجهي عنهم لأني أسكب روحي على شعب إسرائيل يقول السيد الرب».","40:1":"وفي اليوم العاشر من مطلع السنة الخامسة والعشرين من سبينا الموافقة للسنة الرابعة عشرة من سقوط أورشليم، كانت علي يد الرب فأحضرني إلى هناك،","40:2":"وأتى بي في رؤى الله إلى أرض إسرائيل، ووضعني على جبل شاهق حيث كان عليه من جهة الجنوب ما يشبه بناء المدينة.","40:3":"فنقلني إلى هناك، وإذا برجل مظهره كمظهر النحاس يحمل بيده خيط كتان وقصبة وهو واقف بالباب.","40:4":"فقال لي الرجل: «ياابن آدم، انظر بعينيك واصغ بأذنيك وانتبه أشد الانتباه إلى كل ما أطلعك عليه، لأنك لهذا أحضرت إلى هنا. ثم أبلغ شعب إسرائيل بكل ما تشهده».","40:5":"وإذا بسور قائم خارج الهيكل محيط به. وكان طول القصبة التي في يد الرجل (نحو ثلاثة أمتار) فشرع يقيس البناء فكان كل من عرضه وارتفاعه قصبة واحدة (نحو ثلاثة أمتار).","40:6":"ثم تقدم من الباب المواجه للشرق وارتقى درجه وقاس عتبة الباب، فكان عرضها قصبة واحدة (نحو ثلاثة أمتار)، كما كان عرض العتبة الأخرى قصبة واحدة","40:7":"وقاس كذلك الحجرات الجانبية فكان طول وعرض كل منها قصبة واحدة، وبين كل حجرة وحجر ة خمس أذرع (نحو مترين ونصف المتر) وكان عرض عتبة الباب الداخلية بجانب رواق الباب قصبة واحدة.","40:8":"ثم قاس رواق الباب من داخل فكان قصبة واحدة،","40:9":"وقاس أيضا رواق الباب مع عضائده فكانت بجملتها عشر أذرع (نحو خمسة أمتار). وكان رواق الباب هذا من الداخل باتجاه الهيكل.","40:10":"وكانت حجرات الحراس عند الباب ستا، ثلاثا على كل جانب، وكلها ذات قياس واحد هي وعضائدها.","40:11":"ثم قاس عرض مدخل الباب فكان عشر أذرع (نحو خمسة أمتار) وطوله ثلاث عشرة ذراعا (نحو ستة أمتار ونصف المتر).","40:12":"أما الحافة التي أمام الحجرات فكانت ذراعا واحدة (نحو نصف متر) في كل جانب. وكان طول كل حجرة من حجرات الحراس وعرضها ست أذرع (نحو ثلاثة أمتار).","40:13":"ثم قاس الباب من سقف الحائط الخلفي للحجرة إلى سقف الحائط الخلفي للحجرة المقابلة، فكانت المسافة بينها خمسا وعشرين ذراعا (نحو اثنتي عشر مترا ونصف المتر)، الباب مقابل الباب.","40:14":"وكان طول محيط العضائد القائمة حول ممر المدخل الداخلي ستين ذراعا (نحو ثلاثين مترا).","40:15":"كما كانت المسافة بين حافة باب المدخل وحافة باب الرواق الداخلي خمسين ذراعا (نحو خمسة وعشرين مترا).","40:16":"ولحجرات المدخل وجدرانه والرواق كوى مشبكة داخلية محيطة بها جميعا، كما حفر على العضادة رسم شجرة نخيل.","40:17":"ثم أخذني إلى الساحة الخارجية، وإذا بمخادع ورصيف محيط بالساحة شيد عليه ثلاثون مخدعا.","40:18":"وكان الرصيف ممتدا على جوانب البوابات، وعرضه مماثل لطول البوابات. هذا هو الرصيف الأسفل.","40:19":"وقام الملاك بقياس العرض من أمام الباب الأسفل إلى أمام الساحة الداخلية من الخارج، فكانت المسافة مئة ذراع (نحو خمسين مترا) إلى الشرق وإلى الشمال.","40:20":"ثم قاس طول وعرض باب الساحة الخارجية المتجه نحو الشمال،","40:21":"وكذلك حجراته المتقابلة، ثلاثا من كل جهة، وعضائده ورواقه، فكانت مقاييسها مماثلة لمقاييس الأول. طولها خمسون ذراعا (نحو خمسة وعشرين مترا)، وعرضها خمس وعشرون ذراعا (نحو اثنتي عشر مترا ونصف المتر).","40:22":"كما كانت كواه وأروقته ونخيله مماثلة في قيا سها لقياس الباب نحو الشرق. وكانت له سبع درجات يصعدون عليها للوصول إليه. وانتصبت أمامه أقواس أروقته.","40:23":"وللساحة الداخلية باب مقابل لباب الشمال، وآخر مقابل لباب الشرق. وقاس المسافة من باب إلى باب، وإذا بها مئة ذراع (نحو خمسين مترا).","40:24":"ثم أخذني نحو الجنوب، وإذا هناك باب متجه نحو الجنوب، فقاس عضائده وأروقته فكانت مماثلة للأقيسة السابقة.","40:25":"وكان في مدخله وأروقته كوى تحيط بها مماثلة لكوى المدخلين الآخرين. وكان طوله خمسين ذراعا (نحو خمسة وعشرين مترا) وعرضه خمسا وعشرين ذراعا (نحو اثني عشر مترا ونصف المتر).","40:26":"وكانت له سبع درجات يصعدون عليها للوصول إليه. وانتصبت أمامه أقواس أروقته، ونقشت على عضائده شجرتا نخيل كل واحدة من جانب.","40:27":"وللساحة الداخلية باب متجه نحو الجنوب. وقاس المسافة من الباب إلى الباب وإذا بها مئة ذراع (نحو خمسين مترا) باتجاه الجنوب.","40:28":"ثم أحضرني إلى الساحة الداخلية من باب الجنوب، وقاس الباب، فكانت مقاييسه مماثلة لمقاييس البابين الآخرين،","40:29":"وكذلك مقاييس حجراته وعضائده وأروقته. كما كان له ولأروقته على امتداد محيطها كوى. أما طوله فكان خمسين ذراعا (نحو خمسة وعشرين مترا) وعرضه خمسا وعشرين ذراعا (نحو اثني عشر مترا ونصف المتر)","40:30":"وكان على مد محيطه أروقة طولها خمس وعشرون ذراعا (نحو اثني عشر مترا ونصف)، وعرضها خمس أذرع (نحو مترين ونصف المتر).","40:31":"وكانت أروقته المقببة مواجهة للساحة الخارجية، وقد نقشت على عضائدها أشجار نخيل، وله ثماني درجات تفضي إليه.","40:32":"وأتى بي إلى الساحة الداخلية المتجهة نحو الشرق وقاس الباب، فكانت قياساته مماثلة للمقاييس الأخرى.","40:33":"وكذلك مقاييس حجراته وعضائده وأروقته. كما كان له ولأروقته كوى على طول محيطها. أما طوله فكان خمسين ذراعا (نحو خمسة وعشرين مترا)، وعرضه خمسا وعشرين ذراعا (نحو اثني عشر مترا ونصف المتر)","40:34":"وكانت أروقته المقببة مواجهة للساحة الخارجية، وقد نقشت على عضائده أشجار نخيل، وله ثماني درجات تفضي إليه.","40:35":"ثم أخذني إلى باب الشمال وقاسه، فكانت مقاييسه مماثلة للمقاييس الأخرى.","40:36":"وكذلك مقاييس حجراته وعضائده وأروقته والكوى التي على محيطه. أما طوله فكان خمسين ذراعا (نحو خمسة وعشرين مترا)، وعرضه خمسا وعشرين ذراعا (نحو اثني عشر مترا ونصف المتر).","40:37":"وكانت أروقته المقببة مواجهة للساحة الخارجية، وقد نقشت على عضائدها أشجار نخيل، وله ثماني درجات تفضي إليه.","40:38":"وكان هناك مخدع ملحق به مع بابه، مجاورا لعضائد الأبواب، حيث كانت تغسل ذبيحة المحرقة.","40:39":"وكان على كل جانب من جانبي الرواق مائدتان تذبح عليهما المحرقة وذبيحة الخطيئة وذبيحة الإثم،","40:40":"كما كان في الجانب الخارجي عند الدرجات المفضية إلى باب الشمال مائدتان، وفي الجانب الآخر عند رواق الباب مائدتان أخريان،","40:41":"أي أربع موائد في كل جانب. فتكون في جملتها ثماني موائد تذبح عليها القرابين.","40:42":"وكان هناك أيضا أربع موائد أخرى مربعة الشكل، مصنوعة من حجارة منحوتة، طول وعرض كل واحدة منها ذراع ونصف (نحو خمسة وسبعين سنتيمترا،) وارتفاعها ذراع واحدة (نحو خمسين سنتيمترا،) كانوا يضعون عليها الأدوات المستخدمة في ذبح المحرقات وسائر الذبائح.","40:43":"ولها كلابات مزدوجة طولها شبر معقوفة مثبتة حول محيطها. وكان على الموائد لحم القرابين.","40:44":"وأقيم خارج الباب الداخلي مخدعان في الساحة الداخلية، أحدهما مجاور لباب الشمال باتجاه الجنوب، والآخر مجاور للباب الجنوبي باتجاه الشمال.","40:45":"وقال لي الملاك: «هذا المخدع المتجه نحو الجنوب هو للكهنة الذين يحرسون الهيكل.","40:46":"والمخدع المتجه نحو الشمال هو للكهنة الذين يحرسون المذبح، وهم أبناء صادوق، الذين وحدهم من أبناء لاوي يحق لهم أن يقتربوا من الرب ليخدموه».","40:47":"ثم قاس الساحة فكانت مربعة طولها وعرضها مئة ذراع (نحو خمسين مترا) والمذبح قائم أمام الهيكل.","40:48":"وأحضرني إلى رواق الهيكل وقاس سمك عضادتيه من كل من جانبيه، فكان خمس أذرع (نحو مترين ونصف المتر) لكل عضادة وعرض الباب ثلاث أذرع (نحو مترين ونصف المتر)","40:49":"وكان طول الرواق عشرين ذراعا (نحو عشرة أمتار) وعرضه إحدى عشر ذراعا (نحو خمسة أمتار ونصف المتر) عند الدرجات التي تؤدي إليه، كما نصب عند العضائد عمودان واحد عن كل جانب.","41:1":"وأحضرني إلى الهيكل ثم قاس العضائد فكان عرضها في كل جانب ست أذرع (نحو ثلاثة أمتار) مماثلا لعرض الخيمة.","41:2":"أما عرض المدخل فكان عشرة أذرع (نحو خمسة أمتار)، كما كان عرض كل من جانبي المدخل خمس أذرع (نحو مترين ونصف المتر). ثم قاس الهيكل فكان طوله أربعين ذراعا (نحو عشرين مترا)، وعرضه عشرين ذراعا (نحو عشرة أمتار).","41:3":"ثم تقدم من الداخل وقاس عضادة المدخل، فكانت ذراعين (نحو متر) أما المدخل نفسه فكان طوله ست أذرع (نحو ثلاثة أمتار)، وعرضه سبع أذرع (نحو ثلاثة أمتار ونصف المتر)،","41:4":"وقاس الداخل فكان كل من طوله وعرضه عشرين ذراعا (نحو عشرة أمتار) باتجاه القدس. وقال لي: «هذا هو قدس الأقداس»","41:5":"وقاس حائط الهيكل فكان سمكه ست أذرع (نحو ثلاثة أمتار)، وعرض كل حجرة من الحجرات المحيطة بالهيكل أربع أذرع (نحو مترين).","41:6":"وكانت الحجرات مؤلفة من ثلاث طبقات، في كل طبقة ثلاثون حجرة. كل حجرة مبنية فوق أختها. وكانت الحجرات داخلات في الحائط المحيط بالهيكل لتعتمد عليه ولا تعتمد على حائط الهيكل نفسه.","41:7":"وكانت الحجرات الجانبية هذه تتسع من طابق إلى طابق وفقا لاَتساع كل طابق محيط بالهيكل، لهذا كان المرء يصعد من أسفل طابق إلى أعلى طابق عن طريق الطابق الأوسط.","41:8":"ورأيت أن للهيكل رصيفا سميكا على امتداد محيطه. وكان مقاس الحجرات الجانبية قصبة كاملة أي ست أذرع (نحو ثلاثة أمتار) إلى المفصل.","41:9":"وسمك حائط الحجرات من خارج خمس أذرع (نحو مترين ونصف المتر). وما تبقى هو فسحة لحجرات الهيكل.","41:10":"وما بين الرصيف والمخادع عشرون ذراعا (نحو عشرة أمتار) على امتداد محيط الهيكل الخارجي.","41:11":"وكان للحجرات الجانبية المطلة على الفسحة مدخلان: مدخل باتجاه الشمال، ومدخل آخر باتجاه الجنوب. وكان عرض هذه الفسحة خمس أذرع (نحو مترين ونصف المتر) على امتداد محيط الهيكل.","41:12":"وكان عرض البناء المواجه لساحة الهيكل نحو الغرب سبعين ذراعا (نحو خمسة وثلاثين مترا) وسمك حائط البناء على امتداد محيطه خمس أذرع (نحو مترين ونصف المتر).","41:13":"ثم قاس الهيكل فكان طوله مئة ذراع (نحو خمسين مترا) كما كان طول الساحة والبناء مع جدرانه مئة ذراع (نحو خمسين مترا).","41:14":"وكذلك عرض الواجهة الشرقية للهيكل مع الساحة كان مئة ذراع (نحو خمسين مترا).","41:15":"ثم قاس طول البناء المواجه للساحة الخلفية باتجاه الغرب مع أساطينه، فكان مئة ذراع (نحو خمسين مترا). مع الهيكل الداخلي وأروقته.","41:16":"وكانت العتبات والكوى المشبكة والأساطين المحيطة بالطبقات الثلاث مقابل العتبة، وكانت من الأرض إلى الكوى، والكوى نفسها، كلها مغطاة بألواح الخشب من جميع جوانبها.","41:17":"وكذلك ما فوق المدخل وداخل الهيكل وخارجه، ومحيط الجدار من جانبيه الداخلي والخارجي بموجب الأقيسة المعينة.","41:18":"وحفر فيه كروبيم وأشجار نخيل، نخلة بين كروب وكروب. وكان لكل كروب وجهان،","41:19":"أحدهما وجه إنسان باتجاه النخلة السابقة له، والآخر وجه شبل باتجاه النخلة التي تليه. وجميعها حفرت على كل جوانب الهيكل.","41:20":"وقد انتشرت محفورات الكروبيم وأشجار النخيل من الأرض إلى ما فوق المداخل، وكذلك على جدار الهيكل.","41:21":"وكانت قوائم الهيكل مربعة، كما كان وجه القدس مماثلا في منظره لوجه الهيكل.","41:22":"أما المذبح فكان مصنوعا من خشب ارتفاعه ثلاث أذرع (نحو متر ونصف المتر)، وطوله ذراعان (نحو متر). وكانت زواياه وقاعدته وجوانبه مصنوعة من خشب. وقال لي الملاك: «هذه هي المائدة التي أمام الرب».","41:23":"وكان لكل من الهيكل والقدس بابان مزدوجان،","41:24":"ولكل باب مصراعان ينطويان على نفسيهما.","41:25":"وحفر على مصاريع الهيكل كروبيم وأشجار نخيل مثل ما حفر على الجدران. وثبت إفريز من خشب على وجه الرواق من خارج.","41:26":"وانتشرت الكوى المشبكة ورسوم أشجار النخيل على جانبي الرواق وعلى حجرات البيت وعلى الأفاريز.","42:1":"ثم أخرجني إلى الساحة الخارجية من الطريق المتجه شمالا، وأدخلني إلى المخادع المواجهة للساحة المنفصلة مقابل البناء الشمالي.","42:2":"وكان طول البناء ذي الباب المشرع شمالا مئة ذراع (نحو خمسين مترا) وعرضه خمسين ذراعا (نحو خمسة وعشرين مترا).","42:3":"ومقابل الساحة الداخلية التي طولها عشرون ذراعا (نحو عشرة أمتار) ومقابل رصيف الساحة الخارجية أروقة متقابلة قائمة في ثلاث طبقات.","42:4":"وأمام المخادع ممر عرضه عشر أذرع (نحو خمسة أمتار) وطوله مئة ذراع (نحو خمسين مترا) وأبوابه مشرعة نحو الشمال.","42:5":"وكانت المخادع العليا أضيق من مخادع الطابقين الآخرين لأن الأعمدة شغلت جزءا منها.","42:6":"لأن المخادع مؤلفة من ثلاث طبقات، ولم يكن لها أعمدة كأعمدة الساحات. لذلك فإن المخادع العليا كانت أضيق من مخادع الطابقين الآخرين: الأسفل والأوسط","42:7":"وكان طول الجدار الخارجي الموازي لامتداد المخادع، باتجاه الساحة الخارجية، خمسين ذراعا (نحو خمسة وعشرين مترا)،","42:8":"لأن طول امتداد المخادع في الساحة الخارجية خمسون ذراعا (نحو خمسة وعشرين مترا)، بينما طول امتداد المخادع المواجهة للهيكل مئة ذراع (نحو خمسين مترا)","42:9":"وأقيم تحت هذه المخادع مدخل في الجهة الشرقية يفضي إلى المخادع من الساحة الخارجية.","42:10":"وفي عرض جدار الدار نحو الشرق كانت هناك مخادع قائمة في الشمال، في مواجهة الساحة، مقابل البناء.","42:11":"وأمامها ممر. وكانت مماثلة في طولها وعرضها وجميع مخارجها وأشكالها وأبوابها للمخادع التي نحو الشمال.","42:12":"وكان تحت المخادع المتجهة نحو الجنوب مدخل شرقي يفضي إلى الممر المؤدي إليها، وفي مواجهتها جدار فاصل.","42:13":"ثم قال لي الملاك: «إن المخادع الشمالية والمخادع الجنوبية المقابلة للساحة مخادع مقدسة، حيث يأكل الكهنة الذين يقربون في خدمتهم إلى الرب أقداس القرابين. هناك يضعون أقداس القرابين وتقدمة الحبوب، وذبيحة الخطية، وذبيحة الإثم لأن المكان مقدس.","42:14":"وعلى الكهنة بعد دخولهم إليها أن لا يخرجوا إلى الساحة الخارجية إلا بعد أن يخلعوا ثيابهم المقدسة التي يخدمون بها، ويرتدون ثيابا غيرها. ثم يذهبون إلى حيث يجتمع الشعب.","42:15":"وعندما انتهى من قياس الهيكل الداخلي أخرجني إلى الباب الشرقي، وقاس منطقة الهيكل المحيطة به.","42:16":"فقاس الجانب الشرقي بقصبة القياس فكان خمس مئة قصبة (نحو ألف وخمس مئة متر).","42:17":"ثم تحول إلى الجانب الشمالي فقاسه، فكان خمس مئة قصبة (نحو ألف وخمس مئة متر).","42:18":"وقاس الجانب الجنوبي فكان خمس مئة قصبة (نحو ألف وخمس مئة متر).","42:19":"وكذلك قاس الجانب الغربي فكان خمس مئة قصبة (نحو ألف وخمس مئة متر).","42:20":"وهكذا أتم قياس محيط جوانبه الأربعة وكان له سور مربع طوله خمس مئة قصبة (نحو ألف وخمس مئة متر)، وكذلك عرضه، ليفصل بين الموضع المقدس والمواضع العامة.","43:1":"ثم أحضرني إلى الباب المتجه نحو الشرق،","43:2":"وإذا بمجد إله إسرائيل مقبل من المشرق، وصوته كهدير تدفق ميا ه كثيرة، فأضاءت الأرض من مجده.","43:3":"وكانت الرؤيا التي شاهدتها مماثلة للرؤيا التي تجلت لي عندما جاء الرب لتدمير المدينة، وكالرؤى التي شاهدتها عند نهر خابور. فانطرحت على وجهي،","43:4":"وعبر مجد الرب إلى الهيكل من الباب المتجه نحو طريق الشرق،","43:5":"فنقلني الروح إلى الساحة الداخلية، وإذا بمجد الرب قد غمر الهيكل،","43:6":"والملاك مازال واقفا إلى جواري، فسمعت من يخاطبني من الهيكل.","43:7":"يقول لي: ياابن آدم، هذا مقر عرشي ومستقر باطن قدمي، حيث أقيم بين بني إسرائيل إلى الأبد. ولن ينجس شعب إسرائيل ولا ملوكهم بعد اسمي القدوس بما يرتكبونه من زنى، ودفن جثث ملوكهم في مرتفعاتهم،","43:8":"إذ شيدوا عتبات معابد آلهتهم إلى جوار عتبتي، وقوائمها إلى جوار قوائم هيكلي، لا يفصل بيني وبينهم سوى حائط. وهكذا دنسوا اسمي القدوس برجاساتهم التي ارتكبوها، فأفنيتهم في حنقي.","43:9":"فليبعدوا عني زناهم وجثث ملوكهم، فأقيم بينهم إلى الأبد.","43:10":"أما أنت ياابن آدم فصف لشعب إسرائيل الهيكل ومقاييس تصميمه ورسمه ليخجلوا من آثامهم،","43:11":"فإن اعتراهم الخزي من كل ما اقترفوه من رجس، فأطلعهم على تصاميم الهيكل ورسمه وتفاصيل مخارجه ومداخله وأشكاله وكل فرائضه وشرائعه. ودون ذلك أمامهم، ليحفظوا جميع شرائعه وأحكامه ويمارسوها.","43:12":"وهذه هي شريعة الهيكل: إن رأس الجبل وكل المنطقة المحيطة به، هي قدس أقداس.","43:13":"وهذه هي مقاييس المذبح بالأذرع (والأمتار): ارتفاع القاعدة ذراع (نحو نصف متر)، وعرضها ذراع (نحو نصف متر)، وارتفاع حافتها نحو شبر واحد.","43:14":"ومن قاعدة المذبح على الأرض إلى الحافة العليا للرف الأسفل ذراعان (نحو متر)، والعرض ذراع (نحو نصف متر)، ومن الرف الأسفل إلى الرف الأوسط أربع أذرع (نحو مترين). والعرض ذراع (نحو نصف متر).","43:15":"أما ارتفاع موقد المذبح فأربع أذرع (نحو مترين) وتمتد من زوايا الموقد إلى فوق أربعة قرون.","43:16":"وكان الموقد نفسه مربعا طوله اثنتا عشرة ذراعا (نحو ستة أمتار)، وكذلك عرضه","43:17":"أما رف الموقد فكان مربعا أيضا، طوله أربع عشرة ذراعا (نحو سبعة أمتار)، وكذلك عرضه. وله حافة عرضها نصف ذراع (نحو ربع المتر)، وقاعدتها ذراع (نحو نصف المتر، وتواجه درجات المذبح الشرق.","43:18":"وقال لي: «ياابن آدم، هذا ما يعلنه السيد الرب: هذه هي مراسيم المذبح في اليوم الذي ينصب فيه لتقريب المحرقات ورش الدم عليه:","43:19":"تقدم ثورا لذبيحة خطيئة للكهنة اللاويين من ذرية هرون المقتربين إلي ليخدموني يقول السيد الرب.","43:20":"وتأخذ من دمه وتضع منه على قرون المذبح الأربعة، وعلى زوايا الرف وعلى محيط حافته، فتطهره وتكفر عنه.","43:21":"وتأخذ ثور الخطيئة إلى حيث يحرق في الموضع المعين من الهيكل خارج المقدس.","43:22":"وفي اليوم الثاني تقرب تيسا من المعز سليما ذبيحة خطيئة، فيتم تطهير المذبح كما طهروه بدم الثور.","43:23":"وعندما يكتمل مرسوم التطهير تقرب ثورا وكبشا سليمين.","43:24":"تقربهما في محضر الرب، ويرش عليهما الكهنة ملحا، ويصعدونهما محرقة للرب.","43:25":"وتقرب كل يوم ولمدة سبعة أيام تيس خطيئة وثورا وكبشا سليمين.","43:26":"فتكفرون عن المذبح وتطهرونه وتكرسونه سبعة أيام.","43:27":"وفي اليوم الثامن وما يليه من أيام بعد إتمام أسبوع التطهير، يقرب الكهنة على المذبح محرقاتكم وذبائح سلامكم، فأرضى عنكم يقول السيد الرب.","44:1":"ثم أرجعني إلى باب الهيكل الخارجي المواجه للشرق وكان آنئد مغلقا،","44:2":"وقال لي: «سيظل هذا الباب موصدا لا يفتح ولا يدخل منه إنسان، لأن الرب إله إسرائيل قد اجتاز منه. لذلك يظل موصدا","44:3":"إنما الرئيس لكونه رئيسا يجلس في مدخله ليأكل طعاما أمام الرب. يقبل إليه عن طريق رواق الباب، ومن ذات الطريق يعود.","44:4":"ثم أحضرني عن طريق باب الشمال إلى أمام الهيكل. فالتفت حولي وإذا بي أرى مجد الرب يغمر هيكل الرب، فانطرحت على وجهي.","44:5":"وخاطبني قائلا: ياابن آدم، وجه قلبك وانظر بعينيك، وأصغ بأذنيك إلى كل ما أحدثك به عن جميع فرائض هيكل الرب وأحكامه، وراقب بحرص مداخل الهيكل ومخارج المقدس.","44:6":"وقل للمتمردين، لشعب إسرائيل، هذا ما يعلنه السيد الرب: يكفيكم جميع رجاساتكم يا شعب إسرائيل،","44:7":"إذ أدخلتم الغرباء غير المختوني القلوب واللحم إلى مقدسي، فدنستموه حين قربتم طعامي من شحم ودم، فنقضتم عهدي، فضلا عن كل رجاساتكم.","44:8":"ولم تتولوا بأنفسكم حراسة مقدساتي، بل عهدتم بها إلى غرباء بدلا عنكم ليحرسوا مقدسي.","44:9":"لذلك لا يدخل مقدسي غريب غير مختون القلب واللحم من الغرباء المقيمين بين إسرائيل.","44:10":"حتى اللاويون الذين ابتعدوا عني حين ضل إسرائيل وراء أصنامه يحملون عقاب إثمهم.","44:11":"فيكونون خداما في الهيكل وكحراس لأبوابه وخدام له. هم يذبحون المحرقة والقربان للشعب ويخدمونهم،","44:12":"لأنهم قاموا على خدمة عبادة أصنامهم، وكانوا عثرة إثم لشعب إسرائيل، لذلك أقسمت يقول السيد الرب أن أحملهم عقاب إثمهم،","44:13":"فلا يقتربون مني ليكونوا لي كهنة، ولا يدنون من شيء من أقداسي ومن قدس الأقداس، بل يحملون عقاب خزيهم ورجاستهم التي ارتكبوها.","44:14":"لكن أكلفهم بحراسة الهيكل، وبكل خدمة سواها من أعمال الصيانة.","44:15":"أما الكهنة اللاويون من نسل صادوق الذين واظبوا بحرص على حراسة مقدسي حين ضل عني بنو إسرائيل فهؤلاء فقط يتقدمون لخدمتي ويمثلون في حضرتي ليقربوا لي الشحم والدم يقول السيد الرب.","44:16":"هم وحدهم يدخلون مقدسي ويتقدمون إلى مائدتي لخدمتي وللمحافظة على شعائري.","44:17":"وحالما يدخلون أبواب الساحة الداخلية يرتدون ثيابا من كتان ولا يضعون عليهم ثيابا من صوف في أثناء خدمتهم عند أبواب الساحة الداخلية وما يليها.","44:18":"ويتعممون بعمائم كتانية على رؤوسهم، ويرتدون سراويل كتانية أيضا على أحقائهم ولا يلبسون ما يجعل العرق ينز من أجسامهم.","44:19":"وإذا انصرفوا إلى الساحة الخارجية حيث يجتمع الشعب، يخلعون ثياب خدمتهم ويضعونها في مخادع القدس، ثم يرتدون ثيابا أخرى لئلا يقدسوا الشعب بثيابهم.","44:20":"ولا يحلقون رؤوسهم ولا يرخون خصلا، بل يجزون شعر رؤوسهم.","44:21":"ولا يشربن كاهن خمرا عند دخوله إلى الساحة الداخلية.","44:22":"ولا يتزوج الكهنة أرملة ولا مطلقة، بل يتزوجون فتيات عذارى من شعب إسرائيل، أو أرملة كاهن.","44:23":"ويعلمون شعبي التمييز بين المقدس والمباح، ويعرفونهم النجس من الطاهر.","44:24":"ويكونون قضاة في الخصام، فيحكمون بمقتضى أحكامي، ويمارسون شرائعي وفرائضي في كل مواسم أعيادي ويقدسون أيام سبوتي.","44:25":"ولا يقتربون من جثة ميت فيتنجسون، إلا إذا كان الميت أبا أو أما أو ابنا أو ابنة أو أخا أو أختا غير متزوجة.","44:26":"وبعد سبعة أيام من تطهيره،","44:27":"وفي اليوم الذي يقبل فيه إلى القدس، إلى الساحة الداخلية، يقرب ما عليه من ذبيحة خطيئة.","44:28":"ولا يكون لهم ميراث، لأني أنا ميراثهم. ولا تعطونهم ملكا في إسرائيل، لأني ملكهم.","44:29":"ويكون طعامهم من تقدمات الحبوب وذبيحة الخطيئة وذبيحة الإثم وكل تقدمة مخصصة للرب في إسرائيل.","44:30":"وتكون للكهنة أيضا كل باكورة من باكورات غلاتكم ونتاجكم ومن كل صنوف تقدماتكم وتعطونهم أول عجينكم لتحل البركة على بيوتكم.","44:31":"ولا يأكلن الكاهن من أية ميتة أو فريسة، طيرا كانت أو بهيمة.","45:1":"وحين تقسمون الأرض ميراثا تخصصون منها تقدمة مقدسة للرب، طولها خمسة وعشرون ألف ذراع (نحو اثني عشر كيلومترا ونصف)، وعرضها عشرة آلاف ذراع (نحو خمسة كيلومترات) فتكون مقدسة على امتداد طول تخومها.","45:2":"وتفرزون من هذه الأرض قطعة مربعة طولها خمس مئة ذراع (نحو مئتين وخمسين مترا)، وكذلك عرضها، فتكون لبناء المقدس. كما تخصصون للساحة المكشوفة المحيطة به قطعة أخرى يبلغ عرضها من كل جانب خمسين ذراعا (نحو خمسة وعشرين مترا).","45:3":"ويكون المقدس، قدس الأقداس ضمن قطعة أرض يبلغ طولها خمسة وعشرين ألف ذراع (نحو اثني عشر كيلومترا ونصف)، وعرضها عشرة آلاف ذراع (نحو خمسة كيلومترات).","45:4":"وتكون قطعة مخصصة مقدسة للكهنة خدام المقدس المقتربين لخدمة الرب، وموقعا لإقامة منازلهم وموضعا لبناء المقدس.","45:5":"وتفرز قطعة أخرى للاويين طولها خمسة وعشرون ألف ذراع (نحو اثني عشر كيلومترا ونصف) وعرضها عشر ة آلاف ذراع (نحو خمسة كيلومترات)، تكون ملكا لهم يقيمون عليها منازلهم.","45:6":"وتقسطون للمدينة قطعة أرض عرضها خمسة آلاف ذراع (نحو كيلومترين ونصف الكيلومتر)، وطولها خمسة وعشرون ألف ذراع (نحو اثني عشر كيلومترا ونصف)، موازية للتقدمة المقدسة، فتكون لكل شعب إسرائيل.","45:7":"وتخصص للرئيس قطعتا أرض على جانبي تقدمة القدس وأملاك المدينة من الشرق ومن الغرب، ويكون طولها موازيا لطول تخوم تقدمة القدس وأملاك المدينة في كلا الجهتين.","45:8":"فتكون هذه الأرض ملكا له، فلا يعود رؤسائي يغتصبون أملاك شعبي، بل يعطون سائر الأرض لشعب إسرائيل بحسب أسباطهم.","45:9":"وهذا ما يعلنه السيد الرب، حسبكم يارؤساء إسرائيل، توقفوا عن الظلم والاغتصاب، واحكموا بالحق والإنصاف، وكفوا عن ظلم شعبي يقول السيد الرب.","45:10":"لتكن لكم موازين عادلة وإيفة حق وبث حق.","45:11":"فتكون الإيفة والبث متساويتين في المقدار، وتسع كل منهما عشر الحومر. ويكون الحومر هو المكيال المعتمد.","45:12":"ويكون الشاقل معادلا لعشرين جيرة، فتكون قيمة الخمسة شواقل خمسة شواقل، وقيمة العشرة شواقل عشرة شواقل، وقيمة المن خمسين شاقلا.","45:13":"وهذه هي التقدمة التي تقدمونها: سدس الإيفة من الحنطة (نحو ثلاثة لترات وثلثي اللتر) لقاء كل حومر حنطة وسدس الإيفة من الشعير لقاء كل حومر شعير","45:14":"أما فريضة الزيت فتقدمون بثا لقاء كل كر، والكر يساوي حومرا، وهو يعادل عشرة أبثاث أيضا.","45:15":"وشاة واحدة من الضأن من كل قطيع فيه مئتان من الضأن منتجة من مراعي إسرائيل الخصيبة. هذه هي تقدمة الحبوب والمحرقة وذبائح السلام للتكفير عنهم يقول السيد الرب.","45:16":"أما تقدمة الرئيس من الحبوب في إسرائيل فهي فريضة على كل شعب الأرض.","45:17":"وعلى الرئيس تكون قرابين المحرقات وتقدمات الدقيق وسكيب الخمر في الأعياد ورؤوس الشهور وأيام السبوت، وفي كل مواسم احتفالات شعب إسرائيل، إذ عليه أن يقدم ذبيحة الخطيئة وتقدمة الدقيق وذبيحة المحرقة وذبائح السلام للتكفير عن شعب إسرائيل.","45:18":"وهذا ما يعلنه السيد الرب: في اليوم الأول من الشهر الأول تأخذ ثورا سليما وتطهر المقدس بدمه.","45:19":"ويتناول الكاهن من دم ذبيحة الخطيئة، ويضع منه على قوائم الهيكل وعلى أربع زوايا رف المذبح، وعلى قوائم باب الساحة الداخلية.","45:20":"وتقوم بمثل ذلك أيضا في اليوم السابع من الشهر، عن كل من ضل سهوا أو جهلا، فتكفرون عن الهيكل.","45:21":"وفي اليوم الرابع عشر من الشهر الأول تحتفلون بالفصح، فتأكلون فطيرا لمدة سبعة أيام.","45:22":"ويقرب الرئيس في ذلك اليوم عن نفسه وعن سائر شعب الأرض ثورا ليكون ذبيحة خطيئة،","45:23":"كما يقرب في كل يوم من سبعة أيام العيد محرقة للرب من سبعة ثيران وسبعة كباش سليمة، وتيس من المعز ليكون ذبيحة خطيئة.","45:24":"أما تقدمة الدقيق التي يقربها فتكون إيفة (نحو اثنين وعشرين لترا) عن كل ثور، وأيضا عن كل كبش، وهينا (نحو أربعة لترات) من الزيت عن كل إيفة (نحو اثنين وعشرين لترا).","45:25":"وفي اليوم الخامس عشر من الشهر السابع يقوم الرئيس بتقريب مثل هذه في سبعة أيام العيد كذبيحة خطيئة ومحرقة وتقدمة الدقيق وتقدمة الزيت.","46:1":"هذا ما يعلنه السيد الرب: يجب أن يظل باب الساحة الداخلية المتجه شرقا موصدا ستة أيام العمل، ولا يفتح سوى في أيام السبت وفي رأس كل شهر.","46:2":"ويدخل الرئيس إليها من رواق الباب من خارج، ويبقى واقفا عند قائمة الباب، إلى أن يتمم الكهنة تقريب محرقته وذبائح سلامه، ثم يسجد على عتبة الباب وينصرف. أما الباب فلا يغلق إلى المساء.","46:3":"ويسجد الشعب في حضرة الرب عند مدخل هذا الباب في أيام السبت وفي أوائل الشهور.","46:4":"وتكون المحرقة التي يقربها الرئيس للرب في يوم السبت ستة حملان صحيحة وكبشا سليما.","46:5":"أما تقدمة الدقيق فتكون إيفة (نحو اثنين وعشرين لترا) للكبش، وللحملان ما تجود به نفسه، وهينا (نحو أربعة لترات) من الزيت عن كل إيفة","46:6":"ويقرب في أول يوم من كل شهر عجلا سليما وستة حملان وكبشا، تكون كلها سليمة","46:7":"ويرفع تقدمة الدقيق إيفة لقاء كل عجل ولقاء كل كبش. أما للحملان فما تجود به نفسه، وكذلك هينا من الزيت عن كل إيفة.","46:8":"ويقبل الرئيس عند دخوله عن طريق الرواق ومنه ينصرف أيضا.","46:9":"وعند مثول الشعب في حضرة الرب في المواسم، فالمقبل من طريق باب الشمال ينصرف من طريق باب الجنوب، والمقبل من طريق باب الجنوب ينصرف من طريق باب الشمال. لا يرجع من طريق الباب الذي أقبل منه بل ينصرف من طريق الباب المقابل.","46:10":"وعندما يدخلون يدخل الرئيس معهم، وعندما ينصرفون ينصرف الرئيس معهم.","46:11":"وتكون تقدمة الأعياد والمواسم من الدقيق إيفة لقاء كل عجل، وأيضا لقاء كل كبش. أما للحملان فما تجود به نفسه، وكذلك هينا من الزيت عن كل إيفة","46:12":"وإذا قرب الرئيس محرقة أو ذبائح سلامة طوعية يفتح له الباب الشرقي فيصعد محرقته وذبائح سلامه، كما يفعل في كل يوم سبت. ثم حالما ينصرف يغلق الباب من خلفه.","46:13":"وتقرب صباح كل يوم حملا حوليا سليما ليكون محر قة صباحية للرب،","46:14":"وتقرب عليه أيضا من الدقيق في كل صباح سدس الإيفة مع ثلث الهين من الزيت لرش الدقيق، فتكون هذه تقدمة للرب وفريضة أبدية دائمة،","46:15":"وتقربون الحمل وتقدمة الدقيق والزيت في كل صباح محرقة دائمة.","46:16":"إن وهب الرئيس أحد أبنائه نصيبا من ميراثه فإنه يصبح ملكا له بحق الوراثة،","46:17":"ولكن إن أنعم على أحد عبيده بعطية من ميراثه، فإنها تصبح له حتى سنة العتق ثم ترد إلى الرئيس. أما مير اثه فيكون ملكا لأولاده.","46:18":"ولا يغتصبن الرئيس شيئا من ميراث الشعب حارما إياهم من ملكهم. إنما يورث أبناءه مما يملكه فقط، لئلا يحرم أحدا من شعبي من ملكه».","46:19":"ثم أحضرني الملاك من المدخل القائم إلى جانب الباب إلى مخادع الكهنة في القدس، المتجهة نحو الشمال. وإذا هناك موضع على الجانبين في أقصى الغرب.","46:20":"فقال لي: «هذا هو الموضع الذي يطبخ فيه الكهنة ذبيحة الإثم وذبيحة الخطيئة، وحيث يخبزون دقيق التقدمة، لئلا يخرجوا بها إلى الساحة فيقدسون بها الشعب».","46:21":"ثم نقلني إلى الساحة الخارجية وطاف بي في زوايا الساحة الأربع، فإذا في كل زاوية في الساحة فناء.","46:22":"كان في زوايا الساحة الأربع ساحات صغيرة، طولها أربعون ذراعا (نحو عشرين مترا) وعرضها ثلاثون ذراعا (نحو خمسة عشر مترا) وللزوايا الأربع مقاس واحد.","46:23":"وأحاطت بكل ساحة من الساحات الأربع جدران منخفضة بنيت المطابخ عند أسفلها على طول مدارها،","46:24":"فقال لي: «هذه هي بيوت الطباخين، حيث يطبخ فيها خدام الهيكل ذبائح الشعب».","47:1":"ثم أرجعني إلى مدخل الهيكل، وإذا بمياه تتدفق من تحت عتبته نحو الشرق، لأن واجهة الهيكل كانت نحو الشرق. وكانت المياه جارية من تحت، من أسفل الطرف الأيمن لعتبة الهيكل جنوبي المذبح.","47:2":"ثم انطلق بي من طريق باب الشمال، سالكا بي الطريق الخارجي إلى الباب الشرقي الخارجي، وإذا بالمياه تجري في الجانب الأيمن.","47:3":"وبعد أن خرج الرجل نحو المشرق شرع يقيس ألف ذراع (نحو خمس مئة متر) بخيط قياس كان بيده. واجتاز بي المياه التي بلغ عمقها إلى الكعبين.","47:4":"ثم قاس ألف ذراع (نحو خمس مئة متر) أخرى واجتاز بي المياه التي بلغ عمقها الركبتين، وعاد فقاس ألف ذراع (نحو خمس مئة متر) ثالثة واجتاز بي المياه التي بلغ عمقها إلى الحقوين.","47:5":"ثم قاس ألف ذراع (نحو خمس مئة متر) رابعة، وإذا بنهر لم أستطع خوضه، لأن المياه كانت طاغية عميقة، مياه سباحة لنهر يتعذر عبوره.","47:6":"وقال لي: أرأيت هذا ياابن آدم؟» ثم أعادني إلى شاطيء النهر،","47:7":"وإذا بي أجد عليه أشجارا كثيرة قائمة على ضفتيه،","47:8":"وقال لي: «هذه المياه جارية نحو المنطقة الشرقية، ومنحدرة إلى الغور حيث تصب في البحر (الميت) فتجعل مياهه عذبة.","47:9":"وفي مجاريه تعيش كل نفس حية وتتكاثر الأسماك، لأن مياهه تبلغ إليها، فيبرأ كل ما تبلغ إليه مياه النهر وتسري الحياة فيه.","47:10":"ويجتمع الصيادون على شاطئه من عين جدي إلى عين عجلايم، فيصبح مبسطا لشباكهم، ويعج بكل أصناف الأسماك، كسمك البحر العظيم (الأبيض المتوسط).","47:11":"أما مستنقعاته وبركه فلا تبرأ من ملوحتها.","47:12":"وتنمو على ضفتيه كل أنواع أشجار الفاكهة التي تؤكل. لا يذبل ورقها ولا ينقطع ثمرها. تحمل أثمارها في كل شهر، لأن مياه النهر تنبع من المقدس، فتكون ثمار أشجاره للأكل وورقها عقاقير للمداواة.","47:13":"وهذه هي حدود الأرض التي تمتلكونها بحسب أسباط إسرائيل الاثني عشر. يكون لذرية يوسف نصيبان.","47:14":"وتقسمون بينكم بالتساوي هذه الأرض التي أقسمت لآبائكم أن أهبها لهم لتكون لكم ميراثا.","47:15":"وهذه هي حدود الأرض نحو الشمال: من البحر الكبير مرورا بطريق حثلون حتى صدد.","47:16":"ومن حماة وبيروثة وسبرائم الواقعة بين تخم دمشق وتخم حماة وحصر الوسطى التي على حدود حوران.","47:17":"فتمتد الحدود الشمالية من البحر إلى حصر عينان التي على الحدود الشمالية مع حماة وإلى حدود دمشق جنوبا. فتكون هذه هي حدودكم الشمالية.","47:18":"وتمتد الحدود الشرقية من حصر عينان، بين حوران ودمشق وعلى طول الأردن الفاصل بين جلعاد وإسرائيل، مرورا (بالبحر الميت) حت ثامار. فتكون هذه هي حدودكم الشرقية.","47:19":"أما الحدود الجنوبية فتمتد غربا من ثامار إلى مياه مريبوث قادش، ومن متفرع نهر مصر إلى البحر الكبير، فتكون هذه هي حدودكم الجنوبية.","47:20":"أما الحدود الغربية فتكون تخم البحر الكبير، فتمتد من الحدود الجنوبية إلى مدخل حماة شمالا. فتكون هذه هي حدودكم الغربية.","47:21":"وهكذا تقتسمون هذه الأرض بحسب أسباط إسرائيل.","47:22":"تقتسمونها بالقرعة لتكون ميراثا لكم وللغرباء والمقيمين بينكم، الذين أنجبوا أبناء في وسطكم، فيكونون لكم كالمواطنين من أبناء إسرائيل، فيرثون بينكم في وسط أسباط إسرائيل.","47:23":"فتعطون الغريب ميراثا في أرض السبط التي يتغرب فيها يقول السيد الرب.","48:1":"وهذه هي أسماء أسباط إسرائيل. بدءا من الحدود الشمالية بجانب طريق حثلون حتى مدخل حماة حصر عينان على تخوم دمشق باتجاه الشمال بجانب حماة، امتدادا من الشرق إلى البحر غربا تكون لدان حصة واحدة.","48:2":"ومن تخوم دان شرقا حتى البحر غربا تكون لأشير حصة واحدة.","48:3":"ومن حدود أشير شرقا حتى البحر غربا تكون لنفتالي حصة واحدة.","48:4":"ومن حدود نفتالي شرقا حتى البحر غربا تكون لمنسى حصة واحدة.","48:5":"ومن تخوم منسى شرقا حتى البحر غربا تكون لأفرايم حصة واحدة.","48:6":"ومن تخوم أفرايم شرقا حتى البحر غربا تكون لرأوبين حصة واحدة.","48:7":"ومن حدود رأوبين شرقا حتى البحر غربا تكون ليهوذا حصة واحدة.","48:8":"ومن حدود يهوذا شرقا حتى البحر غربا يكون عرض قطعة الأرض التي تقدمونها قدسا لله خمسة وعشرين ألف ذراع (نحو اثني عشر كيلومترا ونصف الكيلومتر). ويضاهي طولها طول أي حصة من الشرق إلى البحر غربا، ويكون المقدس في وسطها.","48:9":"ويكون طول الحصة التي تقدمونها للرب خمسة وعشرين ألف ذراع (نحو اثني عشر كيلومترا ونصف الكيلومتر). أما عرضها فيكون عشرة آلاف ذراع (نحو خمسة كيلومترات).","48:10":"أما الجزء المخصص للكهنة فيها فيكون طوله شمالا خمسة وعشرين ألف ذراع (نحو اثني عشر كيلومترا ونصف الكيلومتر)، وكذلك جنوبا. أما عرضه من الجهة الشرقية ومن الجهة الغربية فيكون عشرة آلاف ذراع (نحو خمسة كيلومترات) لكل جانب، ويكون مقدس الرب في وسطه.","48:11":"ويكون هذا مخصصا للكهنة المقدسين من أبناء صادوق الذين أخلصوا في خدمتي ولم يضلوا حين ضل أبناء إسرائيل كما ضل اللاويون.","48:12":"وتكون لهم تقدمة خاصة من تقدمة الأرض المفرزة لقدس الأقداس المجاورة للجزء الموهوب للاويين.","48:13":"وتخصص للاويين على موازاة حدود أرض الكهنة حصة طولها خمسة وعشرون ألف ذراع (نحو اثني عشر كيلومترا ونصف الكيلومتر)، وعرضها عشرة آلاف ذراع (نحو خمسة كيلومترات)، مماثلة في مساحتها لأرض الكهنة.","48:14":"ويحظر عليهم بيع جزء منها أو مقايضتها أو رهنها لأنها مقدسة للرب.","48:15":"أما قطعة الأرض الباقية التي عرضها خمسة آلاف ذراع (نحو كيلومترين ونصف الكيلومتر)، وطولها خمسة وعشرون ألف ذراع (نحو اثني عشر كيلومترا ونصف الكيلومتر)، فتكون مشاعا لسكان المدينة ومراعي. وتبنى المدينة في وسطها.","48:16":"وهذه هي مقاييس المدينة: هي مربعة الشكل، فيكون مقياس حدودها من جميع اتجاهاتها شمالا وجنوبا وغربا أربعة آلاف وخمس مئة ذراع (نحو كيلومترين وربع الكيلومتر).","48:17":"ويكون للمدينة مروج تحيط بها من جوانبها الأربعة عرض كل منها مِئتان وخمسون ذراعا (نحو مئة متر).","48:18":"ويكون الجزء الباقي من الطول الموازي لتقدمة القدس عشرة آلاف ذراع (نحو خمسة كيلومترات) شرقا، وعشرة آلاف ذراع (نحو خمسة كيلومترات) غربا. وتكون غلته قوتا لعمال المدينة.","48:19":"ويشرف على خدمة المدينة عمال من كل أسباط إسرائيل.","48:20":"وهكذا تكون مساحة أرض التقدمة، ومن جملتها أرض الهيكل وملك المدينة همسة وعشرين ألف ذراع في خمسة وعشرين ألف ذراع (نحو ست مئة وثمانية وثمانين كيلومترا مربعا).","48:21":"وما يتبقى عن جانبي التقدمة المقدسة وأملاك المدينة يكون من نصيب الرئيس، مما يلي مساحة الأرض المقدسة شرقا وغربا حتى حدود أسباط إسرائيل، فتكون التقدمة المقدسة والهيكل في وسطها.","48:22":"وباستثناء أملاك اللاويين وأملاك المدينة القائمة في وسط أراضي الرئيس فإن المنطقة الواقعة ما بين تخوم يهوذا وتخوم بنيامين تكون من نصيب الرئيس.","48:23":"أما أراضي بقية الأسباط فهي: من جهة الشرق حتى البحر غربا تكون لبنيامين حصة واحدة.","48:24":"ومن تخوم بنيامين شرقا حتى البحر غربا تكون لشمعون حصة واحدة.","48:25":"ومن تخوم شمعون شرقا حتى البحر غربا تكون ليساكر حصة واحدة.","48:26":"ومن تخوم يساكر شرقا حتى البحر غربا تكون لزبولون حصة واحدة.","48:27":"ومن تخوم زبولون شرقا حتى البحر غربا تكون لجاد حصة واحدة.","48:28":"ومن تخوم جاد جنوبا باتجاه اليمين تكون الحدود من ثامار إلى مياه مريبة قادش، ومن متفرع نهر مصر إلى البحر الكبير (الأبيض المتوسط).","48:29":"هذه هي الأرض التي تقسمونها ميراثا بين أسباط إسرائيل، وهذه هي حصصهم، يقول السيد الرب.","48:30":"وهذه هي مخارج المدينة: في الجانب الشمالي الذي يمتد أربعة آلاف وخمس مئة ذراع (نحو كيلومترين وربع الكيلومتر)،","48:31":"ثلاثة أبواب، هي باب رأوبين وباب يهوذا وباب لاوي. جميع الأبواب تكون على أسماء أسباط إسرائيل.","48:32":"وفي الجانب الشرقي الذي يمتد أربعة آلاف وخمس مئة ذراع (نحو كيلو مترين وربع الكيلومتر)، ثلاثة أبواب، هي باب يوسف وباب بنيامين وباب دان.","48:33":"وفي الجانب الجنوبي الذي يمتد أربعة آلاف وخمس مئة ذراع (نحو كيلومترين وربع الكيلومتر)، ثلاثة أبواب، هي باب شمعون وباب يساكر وباب زبولون.","48:34":"وفي الجانب الغربي الذي يمتد أربعة آلاف وخمس مئة ذراع (نحو كيلومترين وربع الكيلومتر)، ثلاثة أبواب، هي باب جاد وباب أشير وباب نفتالي.","48:35":"أما محيط المدينة فهو ثمانية عشر ألف ذراع (نحو تسعة كيلومترات)، ويكون اسم المدينة من ذلك اليوم «يهوه شمة» ومعناه: «الرب هناك»."};
